/*
 * Korean Word Notes — usage guidance and worked example sentences.
 * Hand-written companion to shared-vocab.js. Keyed by shared-vocab entry id,
 * with the Korean headword kept on each note as a fallback key.
 *
 * Each note carries:
 *   korean  - headword, used for lookup when an id is missing
 *   note    - how the word is actually used, including the distinctions
 *             learners get wrong (e.g. 높다 for height vs 크다 for size)
 *   example - { ko, en, form }, where form says what happened to the headword
 *             in the sentence, e.g. "크다 → 커요 (present tense, polite casual)"
 *
 * Coverage so far: Bab 5. Words without a note simply render without one.
 *
 * Browser: <script src="./word-notes.js"></script>  -> window.KoreanWordNotes
 * Node:    const KoreanWordNotes = require("./word-notes.js");
 */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.KoreanWordNotes = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  "use strict";

  const NOTES = {
    // ---------------------------------------------------------------- nouns
    "kv0007": { korean: "사람", note: "The neutral word for a person or human being. It doubles as the plain counter for people (한 사람 = one person); 명 is the more formal counter and 분 is the honorific one, so use 분 when counting guests or elders.", example: { ko: "저 사람은 제 친구예요.", en: "That person is my friend.", form: "사람 + 은 (topic particle after a batchim); 이다 → 예요 (present, polite casual)" } },
    "kv0013": { korean: "일", note: "Three senses share this shape: work or a job, a matter or affair, and the Sino-Korean number one (which is also 'day' in dates — 오일 is the 5th). Only the work sense takes 하다: 일하다.", example: { ko: "오늘 일이 많아요.", en: "I have a lot of work today.", form: "일 + 이 (subject particle after a batchim); 많다 → 많아요 (present, polite casual)" } },
    "kv0018": { korean: "안", note: "A position noun meaning the inside of something, normally used as noun + 안에. Do not confuse it with the identical-looking negation adverb 안 (안 가요 = I don't go); the position noun always follows another noun.", example: { ko: "가방 안에 책이 있어요.", en: "There is a book inside the bag.", form: "안 + 에 (location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0050": { korean: "운동", note: "Physical exercise or sport in general. As a verb it takes 하다 (운동하다 = to work out). For a specific sport, name the sport instead: 축구를 해요, not 운동을 해요.", example: { ko: "저는 운동을 좋아해요.", en: "I like exercise.", form: "운동 + 을 (object particle after a batchim); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "kv0063": { korean: "물", note: "Water as a substance or as a drink. It is uncountable, so count it by container: 물 한 잔 (a glass of water), 물 한 병 (a bottle).", example: { ko: "물이 차가워요.", en: "The water is cold.", form: "물 + 이 (subject particle); 차갑다 → 차가워요 (ㅂ-irregular, present, polite casual)" } },
    "kv0084": { korean: "책", note: "A book of any kind. The counter is 권 (책 세 권 = three books). 책을 읽다 is 'read a book'; 책을 보다 is also natural and slightly more casual.", example: { ko: "한국어 책이 재미있어요.", en: "The Korean book is interesting.", form: "책 + 이 (subject particle); 재미있다 → 재미있어요 (present, polite casual)" } },
    "kv0086": { korean: "시장", note: "A traditional open-air or covered market. A supermarket is 슈퍼 or 마트 and a department store is 백화점, so 시장 signals the traditional kind.", example: { ko: "시장이 커요.", en: "The market is big.", form: "시장 + 이 (subject particle); 크다 → 커요 (ㅡ drops before -어요; present, polite casual)" } },
    "kv0107": { korean: "방", note: "A room in a home, and the second half of many compounds: 노래방 (karaoke room), 찜질방 (sauna). A classroom is 교실, not 방, and 가방 (bag) is unrelated despite the shape.", example: { ko: "제 방은 좁아요.", en: "My room is cramped.", form: "방 + 은 (topic particle); 좁다 → 좁아요 (present, polite casual)" } },
    "kv0110": { korean: "영화", note: "A movie. You watch one with 보다 (영화를 보다), never 읽다 or 듣다. A cinema is 영화관 or 극장.", example: { ko: "이 영화는 재미없어요.", en: "This movie is boring.", form: "영화 + 는 (topic particle after a vowel); 재미없다 → 재미없어요 (present, polite casual)" } },
    "kv0122": { korean: "커피", note: "Coffee, counted by the cup: 커피 한 잔. Drink it with 마시다; 커피를 먹다 is heard casually, but 마시다 is the safe choice.", example: { ko: "커피가 뜨거워요.", en: "The coffee is hot.", form: "커피 + 가 (subject particle after a vowel); 뜨겁다 → 뜨거워요 (ㅂ-irregular, present, polite casual)" } },
    "kv0125": { korean: "음식", note: "Food as a category — a cuisine or the dishes served. For a single meal use 밥 or 식사. 한국 음식 means Korean food in general.", example: { ko: "한국 음식이 매워요.", en: "Korean food is spicy.", form: "음식 + 이 (subject particle); 맵다 → 매워요 (ㅂ-irregular, present, polite casual)" } },
    "kv0174": { korean: "팀", note: "A team, borrowed from English. Used for sports sides and work groups alike: 축구 팀, 우리 팀.", example: { ko: "우리 팀이 좋아요.", en: "Our team is good.", form: "팀 + 이 (subject particle); 좋다 → 좋아요 (present, polite casual)" } },
    "kv0185": { korean: "여름", note: "Summer. Seasons take 에 for 'in': 여름에 = in summer. Its weather word is 덥다 (hot air), not 뜨겁다 (hot to the touch).", example: { ko: "여름에 아주 더워요.", en: "It is very hot in summer.", form: "여름 + 에 (time particle); 덥다 → 더워요 (ㅂ-irregular, present, polite casual)" } },
    "kv0198": { korean: "겨울", note: "Winter. Its default weather adjective is 춥다 (cold air), not 차갑다, which is reserved for things that feel cold when you touch them.", example: { ko: "겨울이 추워요.", en: "Winter is cold.", form: "겨울 + 이 (subject particle); 춥다 → 추워요 (ㅂ-irregular, present, polite casual)" } },
    "kv0202": { korean: "텔레비전", note: "A television set, often shortened to 티브이 in speech. You watch it with 보다: 텔레비전을 봐요.", example: { ko: "텔레비전이 커요.", en: "The television is big.", form: "텔레비전 + 이 (subject particle); 크다 → 커요 (present, polite casual)" } },
    "kv0206": { korean: "봄", note: "Spring. Like the other seasons it takes 에 for 'in spring'. Its shape is identical to the noun form of 보다 (seeing), so context decides.", example: { ko: "봄에 날씨가 좋아요.", en: "The weather is nice in spring.", form: "봄 + 에 (time particle); 좋다 → 좋아요 (present, polite casual)" } },
    "kv0443": { korean: "가을", note: "Autumn. Takes 에 for 'in autumn', and pairs naturally with 시원하다 (pleasantly cool) rather than 춥다.", example: { ko: "가을에 바람이 불어요.", en: "The wind blows in autumn.", form: "가을 + 에 (time particle); 불다 → 불어요 (present, polite casual)" } },
    "kv0446": { korean: "날씨", note: "The weather. It is the subject of weather adjectives — 날씨가 좋다 / 덥다 / 흐리다 — while 기후 is the climate over a long period.", example: { ko: "오늘 날씨가 맑아요.", en: "The weather is clear today.", form: "날씨 + 가 (subject particle); 맑다 → 맑아요 (present, polite casual)" } },
    "kv0451": { korean: "축구", note: "Soccer. Body sports take 하다 (축구를 해요 = I play soccer). Only racket sports take 치다, and only 스키/스케이트 take 타다.", example: { ko: "저는 축구를 좋아해요.", en: "I like soccer.", form: "축구 + 를 (object particle after a vowel); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "kv0454": { korean: "교실", note: "A classroom specifically. A lecture hall is 강의실 and a school is 학교; 방 is a room in a home, so it is the wrong word here.", example: { ko: "교실이 깨끗해요.", en: "The classroom is clean.", form: "교실 + 이 (subject particle); 깨끗하다 → 깨끗해요 (하다 verb, present, polite casual)" } },
    "kv0456": { korean: "색", note: "Colour, often extended to 색깔 in speech. Colour words are usually a name plus 색: 빨간색, 파란색. 무슨 색이에요? is the standard way to ask what colour something is.", example: { ko: "이 가방은 무슨 색이에요?", en: "What colour is this bag?", form: "색 + 이에요 (이다 after a batchim; present, polite casual, question)" } },
    "kv0467": { korean: "가방", note: "Any carried bag — handbag, backpack (책가방), or suitcase. Counted with 개.", example: { ko: "가방이 무거워요.", en: "The bag is heavy.", form: "가방 + 이 (subject particle); 무겁다 → 무거워요 (ㅂ-irregular, present, polite casual)" } },
    "kv0493": { korean: "화장실", note: "The polite everyday word for a restroom, literally a 'make-up room'. 화장실이 어디에 있어요? is the standard way to ask where it is.", example: { ko: "화장실이 어디에 있어요?", en: "Where is the restroom?", form: "화장실 + 이 (subject particle); 있다 → 있어요 (present, polite casual, question)" } },
    "kv0527": { korean: "바지", note: "Trousers. Grammatically singular in Korean — 바지가 길어요, with no plural form — and counted with 벌 (바지 한 벌). Worn with 입다.", example: { ko: "바지가 길어요.", en: "The trousers are long.", form: "바지 + 가 (subject particle); 길다 → 길어요 (present, polite casual)" } },
    "kv0530": { korean: "한국어", note: "The Korean language as a subject of study — the word used in textbooks and course names. 한국말 is the colloquial equivalent, and 한글 is only the alphabet, never the language.", example: { ko: "한국어가 어려워요.", en: "Korean is difficult.", form: "한국어 + 가 (subject particle); 어렵다 → 어려워요 (ㅂ-irregular, present, polite casual)" } },
    "kv0532": { korean: "야구", note: "Baseball. Played with 하다 (야구를 해요); watching a game is 야구를 봐요.", example: { ko: "야구가 재미있어요.", en: "Baseball is fun.", form: "야구 + 가 (subject particle); 재미있다 → 재미있어요 (present, polite casual)" } },
    "kv0538": { korean: "수영", note: "Swimming. The verb is 수영하다 or 수영을 하다; the place is 수영장 (pool).", example: { ko: "여름에 수영을 해요.", en: "I swim in summer.", form: "수영 + 을 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0547": { korean: "연필", note: "A pencil, counted with 자루 (연필 한 자루). A pen is 볼펜, and the instrument you write with takes 로/으로: 연필로 써요.", example: { ko: "연필이 짧아요.", en: "The pencil is short.", form: "연필 + 이 (subject particle); 짧다 → 짧아요 (present, polite casual)" } },
    "kv0550": { korean: "모자", note: "A hat or cap. Things worn on the head take 쓰다, not 입다: 모자를 써요. 입다 is only for clothing on the torso and legs.", example: { ko: "모자가 작아요.", en: "The hat is small.", form: "모자 + 가 (subject particle); 작다 → 작아요 (present, polite casual)" } },
    "kv0568": { korean: "테니스", note: "Tennis. Racket sports take 치다 (테니스를 쳐요) rather than 하다, the same way 골프를 치다 works.", example: { ko: "저는 테니스를 좋아해요.", en: "I like tennis.", form: "테니스 + 를 (object particle); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "kv0575": { korean: "우체국", note: "A post office. Buildings take 에 for the destination (우체국에 가요) and 에서 for an action done there (우체국에서 일해요).", example: { ko: "우체국이 가까워요.", en: "The post office is close.", form: "우체국 + 이 (subject particle); 가깝다 → 가까워요 (ㅂ-irregular, present, polite casual)" } },
    "kv0582": { korean: "태권도", note: "Taekwondo. Martial arts take 하다 or 배우다: 태권도를 배워요 = I learn taekwondo.", example: { ko: "태권도가 어려워요.", en: "Taekwondo is difficult.", form: "태권도 + 가 (subject particle); 어렵다 → 어려워요 (ㅂ-irregular, present, polite casual)" } },
    "kv0592": { korean: "바나나", note: "A banana. Fruit is counted with 개: 바나나 두 개 = two bananas.", example: { ko: "바나나가 맛있어요.", en: "The banana is delicious.", form: "바나나 + 가 (subject particle); 맛있다 → 맛있어요 (present, polite casual)" } },
    "kv0601": { korean: "스키", note: "Skiing or skis. One of the few sports that takes 타다 ('to ride'): 스키를 타요, the same pattern as 자전거를 타다.", example: { ko: "겨울에 스키를 타요.", en: "I ski in winter.", form: "스키 + 를 (object particle); 타다 → 타요 (identical ㅏ merges; present, polite casual)" } },
    "kv1024": { korean: "골프", note: "Golf. Like tennis the ball is struck, so the verb is 치다: 골프를 쳐요.", example: { ko: "아버지가 골프를 쳐요.", en: "My father plays golf.", form: "골프 + 를 (object particle); 치다 → 쳐요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "kv1034": { korean: "배드민턴", note: "Badminton — another racket sport with 치다: 배드민턴을 쳐요.", example: { ko: "친구하고 배드민턴을 쳐요.", en: "I play badminton with a friend.", form: "배드민턴 + 을 (object particle); 치다 → 쳐요 (present, polite casual)" } },
    "kv1037": { korean: "농구", note: "Basketball. Takes 하다 like the other team sports: 농구를 해요.", example: { ko: "우리는 농구를 해요.", en: "We play basketball.", form: "농구 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv1044": { korean: "스케이트", note: "Ice skates or skating. Like 스키 it is ridden, so use 타다: 스케이트를 타요.", example: { ko: "겨울에 스케이트를 타요.", en: "I skate in winter.", form: "스케이트 + 를 (object particle); 타다 → 타요 (present, polite casual)" } },

    // -------------------------------------------------------- proper nouns
    "kv0738": { korean: "한국", note: "Korea (the Republic of Korea). Country names attach directly to another noun with no particle between them: 한국 사람, 한국 음식, 한국어.", example: { ko: "저는 한국에 가요.", en: "I am going to Korea.", form: "한국 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },

    // ------------------------------------------------------------ pronouns
    "kv0004": { korean: "나", note: "The casual 'I', used with friends and people younger than you; in polite speech use 저. Before the subject particle it contracts: 나 + 가 → 내가 (저 + 가 → 제가).", example: { ko: "나는 축구를 좋아해.", en: "I like soccer.", form: "나 + 는 (topic particle); 좋아하다 → 좋아해 (present, plain casual 반말 — the register that matches 나)" } },

    // --------------------------------------------------------------- verbs
    "kv0014": { korean: "오다", note: "To come — motion toward where the speaker is. Its pair is 가다 (to go, away from the speaker), so the choice depends on where you are standing, not on the destination. The destination takes 에, the starting point 에서.", example: { ko: "친구가 한국에 와요.", en: "My friend is coming to Korea.", form: "오다 → 와요 (ㅗ + 아 contracts to 와; present, polite casual)" } },
    "kv0077": { korean: "잡다", note: "To grab, catch, or take hold of — a hand closing on something: 손을 잡다 (hold hands), 택시를 잡다 (catch a taxi), 도둑을 잡다 (catch a thief). Catching a cold is not 잡다 but 감기에 걸리다.", example: { ko: "동생이 손을 잡아요.", en: "My younger sibling holds my hand.", form: "잡다 → 잡아요 (stem vowel ㅏ takes -아요; present, polite casual)" } },
    "kv0113": { korean: "입다", note: "To wear, but only clothing worn on the body: 바지를 입다, 옷을 입다. Other items each take their own verb — 모자를 쓰다 (hat), 신발을 신다 (shoes), 시계를 차다 (watch), 안경을 쓰다 (glasses).", example: { ko: "저는 바지를 입어요.", en: "I wear trousers.", form: "입다 → 입어요 (stem vowel ㅣ takes -어요; present, polite casual)" } },
    "kv0442": { korean: "불다", note: "To blow. Wind blowing is the most common use, and it also covers blowing on something or playing a wind instrument. It is intransitive with 바람 as the subject, so say 바람이 불어요, never 바람을 불어요.", example: { ko: "가을에 바람이 불어요.", en: "The wind blows in autumn.", form: "불다 → 불어요 (stem vowel ㅜ takes -어요; present, polite casual)" } },

    // ------------------------------- adjectives (Korean descriptive verbs)
    "kv0016": { korean: "크다", note: "Big in size or volume — objects, rooms, sounds (목소리가 크다), clothes that are too large. A tall person is 키가 크다 (literally 'the height is big'), but the height of a building or mountain is 높다, not 크다.", example: { ko: "가방이 커요.", en: "The bag is big.", form: "크다 → 커요 (ㅡ-irregular: ㅡ drops before -어요; present, polite casual)" } },
    "kv0017": { korean: "많다", note: "Many or much — quantity or number, never physical size. 사람이 많아요 = there are a lot of people. Its opposite is 적다 (few), which is one letter away from 작다 (small).", example: { ko: "교실에 사람이 많아요.", en: "There are a lot of people in the classroom.", form: "많다 → 많아요 (stem vowel ㅏ takes -아요; present, polite casual)" } },
    "kv0019": { korean: "좋다", note: "To be good or nice — a description of the thing itself, so it takes 이/가: 날씨가 좋아요. To say that a person likes something, use the separate verb 좋아하다, which takes an object with 을/를.", example: { ko: "오늘 날씨가 좋아요.", en: "The weather is nice today.", form: "좋다 → 좋아요 (stem vowel ㅗ takes -아요; present, polite casual)" } },
    "kv0088": { korean: "어렵다", note: "Difficult — tasks, subjects, and situations that demand effort. Something physically hard to the touch is 딱딱하다, and a hard, tiring life is 힘들다.", example: { ko: "한국어가 어려워요.", en: "Korean is difficult.", form: "어렵다 → 어려워요 (ㅂ-irregular: ㅂ becomes 우 before a vowel ending; present, polite casual)" } },
    "kv0092": { korean: "쉽다", note: "Easy — the opposite of 어렵다, for tasks and subjects. Also a ㅂ-irregular, so the ㅂ turns into 우 before a vowel ending.", example: { ko: "시험이 쉬웠어요.", en: "The exam was easy.", form: "쉽다 → 쉬웠어요 (ㅂ-irregular plus past-tense -었-; past, polite casual)" } },
    "kv0094": { korean: "작다", note: "Small in physical size. Keep it apart from 적다 (few in number): 옷이 작아요 means the clothes are too small, while 옷이 적어요 means there are not many clothes.", example: { ko: "모자가 작아요.", en: "The hat is small.", form: "작다 → 작아요 (stem vowel ㅏ takes -아요; present, polite casual)" } },
    "kv0098": { korean: "높다", note: "High — vertical height measured from the ground: buildings, mountains, prices, temperatures. A tall person is 키가 크다, never 키가 높다.", example: { ko: "산이 높아요.", en: "The mountain is high.", form: "높다 → 높아요 (stem vowel ㅗ takes -아요; present, polite casual)" } },
    "kv0123": { korean: "길다", note: "Long — physical length (머리가 길다) and duration (시간이 길다). Its ㄹ drops before endings starting with ㄴ, ㅂ, or ㅅ: 긴 머리, 깁니다.", example: { ko: "바지가 길어요.", en: "The trousers are long.", form: "길다 → 길어요 (stem vowel ㅣ takes -어요; present, polite casual)" } },
    "kv0157": { korean: "적다", note: "Few or not much — a small quantity, the opposite of 많다. Never use it for size; that is 작다. A homograph 적다 also means 'to write down'.", example: { ko: "물이 적어요.", en: "There is little water.", form: "적다 → 적어요 (stem vowel ㅓ takes -어요; present, polite casual)" } },
    "kv0167": { korean: "넓다", note: "Wide or spacious — surface area rather than distance: rooms, roads, parks. Its opposite is 좁다. The ㅂ belongs to the cluster ㄼ and does not trigger the ㅂ-irregular.", example: { ko: "방이 넓어요.", en: "The room is spacious.", form: "넓다 → 넓어요 (regular; stem vowel ㅓ takes -어요; present, polite casual)" } },
    "kv0170": { korean: "가깝다", note: "Near — distance between two points, with the reference point marked by 에서: 학교에서 가까워요. It also covers closeness between people: 친구하고 가까워요.", example: { ko: "우체국이 가까워요.", en: "The post office is close.", form: "가깝다 → 가까워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0176": { korean: "재미있다", note: "Fun or interesting. Built from 재미 (fun) + 있다, so it conjugates on 있다 and its negative is the fixed word 재미없다, not 재미있지 않다. A person who makes you laugh is 웃기다.", example: { ko: "그 영화가 재미있었어요.", en: "That movie was interesting.", form: "재미있다 → 재미있었어요 (past-tense -었-; past, polite casual)" } },
    "kv0180": { korean: "멀다", note: "Far — the opposite of 가깝다, with the reference point marked by 에서: 집에서 멀어요. Like 길다 it is a ㄹ-stem, so the ㄹ drops in 먼 곳 and 멉니다.", example: { ko: "시장이 집에서 멀어요.", en: "The market is far from home.", form: "집 + 에서 marks the reference point; 멀다 → 멀어요 (present, polite casual)" } },
    "kv0186": { korean: "싫다", note: "To be disliked or unpleasant — it describes the thing, so the disliked item takes 이/가: 저는 겨울이 싫어요. When the person is the subject doing the disliking, use 싫어하다 with an object: 저는 겨울을 싫어해요.", example: { ko: "저는 겨울이 싫어요.", en: "I dislike winter.", form: "the disliked thing takes 이/가; 싫다 → 싫어요 (present, polite casual)" } },
    "kv0190": { korean: "짧다", note: "Short in length or duration — hair, trousers, a trip. A short person is 키가 작다, not 짧다.", example: { ko: "연필이 짧아요.", en: "The pencil is short.", form: "짧다 → 짧아요 (stem vowel ㅏ takes -아요; present, polite casual)" } },
    "kv0207": { korean: "낮다", note: "Low — the opposite of 높다, for heights, prices, temperatures, and sounds. Watch the near-twins: 낮다 (low), 낫다 (to be better), 낮 (daytime).", example: { ko: "의자가 낮아요.", en: "The chair is low.", form: "낮다 → 낮아요 (stem vowel ㅏ takes -아요; present, polite casual)" } },
    "kv0417": { korean: "맛있다", note: "Delicious. From 맛 (taste) + 있다, so it conjugates on 있다 and its opposite is 맛없다. It describes food, never a person.", example: { ko: "한국 음식이 맛있어요.", en: "Korean food is delicious.", form: "맛있다 → 맛있어요 (present, polite casual)" } },
    "kv0420": { korean: "맑다", note: "Clear — clear skies and fine weather (날씨가 맑다), and also clear water or a clear voice. Its weather opposite is 흐리다.", example: { ko: "하늘이 맑아요.", en: "The sky is clear.", form: "맑다 → 맑아요 (stem vowel ㅏ takes -아요; present, polite casual)" } },
    "kv0431": { korean: "뜨겁다", note: "Hot to the touch — coffee, soup, a stove. Hot weather is 덥다. Getting these two backwards is the classic mistake: 커피가 뜨거워요 but 날씨가 더워요.", example: { ko: "커피가 뜨거워요.", en: "The coffee is hot.", form: "뜨겁다 → 뜨거워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0434": { korean: "가볍다", note: "Light in weight, the opposite of 무겁다. It also stretches to minor or light-hearted things (가벼운 감기 = a mild cold). Light as in bright is 밝다, not 가볍다.", example: { ko: "가방이 가벼워요.", en: "The bag is light.", form: "가볍다 → 가벼워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0452": { korean: "밝다", note: "Bright — a well-lit room or a bright colour, and figuratively a promising future (미래가 밝다) or a cheerful personality. Its opposite is 어둡다.", example: { ko: "교실이 밝아요.", en: "The classroom is bright.", form: "밝다 → 밝아요 (stem vowel ㅏ takes -아요; present, polite casual)" } },
    "kv0463": { korean: "깨끗하다", note: "Clean and tidy — rooms, clothes, air. A 하다 adjective, so it becomes 깨끗해요 in the present and 깨끗한 before a noun. Its opposite is 더럽다.", example: { ko: "방이 깨끗해요.", en: "The room is clean.", form: "깨끗하다 → 깨끗해요 (하다 contracts to 해요; present, polite casual)" } },
    "kv0473": { korean: "춥다", note: "Cold weather, or a person feeling cold: 날씨가 추워요, 저는 추워요. Something cold to the touch is 차갑다, so cold water is 물이 차가워요, never 물이 추워요.", example: { ko: "겨울에 아주 추워요.", en: "It is very cold in winter.", form: "춥다 → 추워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0474": { korean: "무겁다", note: "Heavy in weight, the opposite of 가볍다. Also used for a heavy mood or atmosphere: 분위기가 무거워요.", example: { ko: "책이 무거워요.", en: "The book is heavy.", form: "무겁다 → 무거워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0485": { korean: "비싸다", note: "Expensive — it describes the price of a thing, so the thing takes 이/가: 가방이 비싸요. It never describes a person.", example: { ko: "이 가방은 비싸요.", en: "This bag is expensive.", form: "비싸다 → 비싸요 (identical ㅏ merges rather than doubling; present, polite casual)" } },
    "kv0512": { korean: "싸다", note: "Cheap, the opposite of 비싸다. Note the homograph 싸다 meaning 'to wrap or pack' (도시락을 싸다), which is an action verb with an object — the price meaning always describes a subject with 이/가.", example: { ko: "시장에서 옷이 싸요.", en: "Clothes are cheap at the market.", form: "시장 + 에서 marks where; 싸다 → 싸요 (present, polite casual)" } },
    "kv0531": { korean: "덥다", note: "Hot weather, or a person feeling hot: 날씨가 더워요, 저는 더워요. Hot objects and drinks are 뜨겁다. Its weather opposite is 춥다.", example: { ko: "여름에 더워요.", en: "It is hot in summer.", form: "덥다 → 더워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0572": { korean: "재미없다", note: "Boring — the fixed negative of 재미있다. Say 재미없어요; 재미있지 않아요 is grammatical but sounds unnatural.", example: { ko: "그 책은 재미없어요.", en: "That book is boring.", form: "재미없다 → 재미없어요 (present, polite casual)" } },
    "kv0580": { korean: "맵다", note: "Spicy hot. Only for chilli heat — food that is hot in temperature is 뜨겁다. A ㅂ-irregular: 매워요, 매운 음식.", example: { ko: "이 음식이 매워요.", en: "This food is spicy.", form: "맵다 → 매워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0625": { korean: "맛없다", note: "To taste bad — the fixed opposite of 맛있다, pronounced [마덥따]. Like 맛있다 it conjugates on 없다.", example: { ko: "이 커피는 맛없어요.", en: "This coffee tastes bad.", form: "맛없다 → 맛없어요 (present, polite casual)" } },
    "kv1004": { korean: "어둡다", note: "Dark or dim — a room with the lights off, a dark colour, or a gloomy mood. Its opposite is 밝다. A ㅂ-irregular: 어두워요, 어두운 방.", example: { ko: "방이 어두워요.", en: "The room is dark.", form: "어둡다 → 어두워요 (ㅂ-irregular; present, polite casual)" } },
    "kv1006": { korean: "좁다", note: "Narrow or cramped — rooms, streets, seats. The opposite of 넓다. Despite ending in ㅂ it conjugates regularly: 좁아요, not 조워요.", example: { ko: "길이 좁아요.", en: "The road is narrow.", form: "좁다 → 좁아요 (regular ㅂ, not a ㅂ-irregular; present, polite casual)" } },
    "kv1009": { korean: "차갑다", note: "Cold to the touch — water, hands, drinks — and also a cold personality (차가운 사람). Cold weather is 춥다.", example: { ko: "물이 차가워요.", en: "The water is cold.", form: "차갑다 → 차가워요 (ㅂ-irregular; present, polite casual)" } },
    "kv1017": { korean: "더럽다", note: "Dirty — the opposite of 깨끗하다, for rooms, clothes, and hands. A ㅂ-irregular: 더러워요, 더러운 방.", example: { ko: "교실이 더러워요.", en: "The classroom is dirty.", form: "더럽다 → 더러워요 (ㅂ-irregular; present, polite casual)" } },
    "kv1026": { korean: "흐리다", note: "Cloudy or overcast, and by extension blurry (기억이 흐리다). Its weather opposite is 맑다. The stem ends in ㅣ, so -어요 contracts to 려요.", example: { ko: "오늘 날씨가 흐려요.", en: "The weather is cloudy today.", form: "흐리다 → 흐려요 (ㅣ + 어 contracts to 여; present, polite casual)" } },

    // ------------------------------------------------------------- adverbs
    "kv0020": { korean: "더", note: "More — placed directly before the adjective or verb it strengthens: 더 커요 (bigger), 더 좋아요 (better). Korean has no -er ending, so 더 does that job. 'Less' is 덜.", example: { ko: "이 가방이 더 커요.", en: "This bag is bigger.", form: "더 stands before the predicate and never changes; 크다 → 커요 (present, polite casual)" } },
    "kv0078": { korean: "같이", note: "Together, pronounced [가치]. The companion is marked with 하고, 와/과, or 랑: 친구하고 같이 가요. 함께 means the same thing in more formal or written style.", example: { ko: "친구하고 같이 영화를 봐요.", en: "I watch a movie together with a friend.", form: "같이 modifies the verb; 보다 → 봐요 (ㅗ + 아 contracts to 와; present, polite casual)" } },
    "kv0173": { korean: "조금", note: "A little, a bit — softens an adjective or reduces a quantity: 조금 매워요. Shortened to 좀 in speech, where it also softens requests (좀 주세요). 'Very' is 아주 or 정말.", example: { ko: "이 음식이 조금 매워요.", en: "This food is a little spicy.", form: "조금 stands before the predicate; 맵다 → 매워요 (ㅂ-irregular, present, polite casual)" } },

    // -------------------------------------------- nouns used as adverbials
    "kv0070": { korean: "지금", note: "Now. It works as a bare time adverb at the front of a sentence — 지금 가요 — and takes no 에, unlike clock times (세 시에). It can also behave as a plain noun: 지금이 좋아요.", example: { ko: "지금 비가 와요.", en: "It is raining now.", form: "지금 used adverbially with no particle; 오다 → 와요 (present, polite casual)" } },

    // --------------------------------------- determiners (관형사, prenouns)
    "kv0087": { korean: "무슨", note: "'What kind of' — a determiner that sits directly in front of a noun with no particle between: 무슨 색, 무슨 음식. Compare 어떤 (asking for a description) and 어느 (picking from a known set).", example: { ko: "무슨 운동을 좋아해요?", en: "What kind of exercise do you like?", form: "무슨 + noun, never conjugated and never with a particle; 좋아하다 → 좋아해요 (present, polite casual, question)" } },

    // ---------------------------------------------- interjections (감탄사)
    "kv0103": { korean: "아", note: "'Ah' or 'oh' — the sound of sudden realisation, mild pain, or dismay. It stands alone at the front of a sentence and takes no particle or ending.", example: { ko: "아, 오늘 날씨가 좋아요!", en: "Ah, the weather is nice today!", form: "아 is an interjection — never conjugated; 좋다 → 좋아요 (present, polite casual)" } },
    "kv0114": { korean: "네", note: "Yes. Also a soft acknowledgement ('I see', 'go ahead') and, with rising intonation, 'pardon?'. 예 is the more formal yes. Note that 네 agrees with the question as asked, so a negative question gets 네 to confirm the negative.", example: { ko: "네, 저는 축구를 좋아해요.", en: "Yes, I like soccer.", form: "네 is a fixed reply word — never conjugated; 좋아하다 → 좋아해요 (present, polite casual)" } },
    "kv0136": { korean: "어", note: "'Huh?' or 'oh' — a casual filler marking surprise or hesitation. It belongs to 반말; in polite speech soften it or drop it entirely.", example: { ko: "어, 지금 비가 와요?", en: "Oh, is it raining now?", form: "어 is an interjection — never conjugated; 오다 → 와요 (present, polite casual, question)" } },
    "kv0520": { korean: "아니요", note: "No — the polite negative answer, written 아니오 in older texts. It contradicts the question as asked. Do not confuse it with the adjective 아니다 (to not be), which does conjugate: 학생이 아니에요.", example: { ko: "아니요, 저는 커피를 안 마셔요.", en: "No, I do not drink coffee.", form: "아니요 is a fixed reply word — never conjugated; 안 + 마시다 → 안 마셔요 (short negation, present, polite casual)" } },

    // ------------------------------------------------------------- Bab 1
    "kv0079": { korean: "선생님", note: "Teacher. The 님 on the end is the honorific suffix, so the word is already respectful and is used to address a teacher directly: 선생님, 안녕하세요. Never call yourself 선생님.", example: { ko: "저는 선생님이에요.", en: "I am a teacher.", form: "선생님 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "kv0090": { korean: "학생", note: "A student at any level. A university student is 대학생 and a middle-schooler 중학생 — 학생 is the general term, and it is also how a teacher addresses a student they do not know.", example: { ko: "제 친구는 학생이에요.", en: "My friend is a student.", form: "학생 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "kv0091": { korean: "이름", note: "A given or full name. Asking politely you say 이름이 뭐예요?; to an elder or in formal settings use the honorific noun 성함 instead (성함이 어떻게 되세요?).", example: { ko: "이름이 뭐예요?", en: "What is your name?", form: "이름 + 이 (subject particle); 뭐 + 예요 (이다 after a vowel; present, polite casual, question)" } },
    "kv0165": { korean: "경찰", note: "The police, or a police officer. For the individual person 경찰관 is more precise, and the station is 경찰서.", example: { ko: "아버지는 경찰이에요.", en: "My father is a police officer.", form: "경찰 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "kv0447": { korean: "의사", note: "A medical doctor. Note that a PhD is 박사, and when addressing a doctor you add the honorific: 의사 선생님.", example: { ko: "언니는 의사예요.", en: "My older sister is a doctor.", form: "의사 + 예요 (이다 after a vowel; present, polite casual)" } },
    "kv0501": { korean: "가수", note: "A singer. Built from 歌 (song) + 手 (hand/doer), the same 수 that appears in 선수 (athlete) and 운전수 (driver).", example: { ko: "제 친구는 가수예요.", en: "My friend is a singer.", form: "가수 + 예요 (이다 after a vowel; present, polite casual)" } },
    "kv0555": { korean: "안녕히", note: "'Peacefully' — the adverb form of 안녕하다, used almost only inside the two goodbyes 안녕히 가세요 and 안녕히 계세요. Like all -히 adverbs it modifies the verb that follows.", example: { ko: "안녕히 가세요.", en: "Goodbye (to someone leaving).", form: "안녕히 modifies the verb; 가다 + -(으)세요 → 가세요 (honorific polite request)" } },
    "kv0588": { korean: "간호사", note: "A nurse. Paired with 의사 in hospital vocabulary; the workplace is 병원.", example: { ko: "어머니는 간호사예요.", en: "My mother is a nurse.", form: "간호사 + 예요 (이다 after a vowel; present, polite casual)" } },
    "kv0641": { korean: "감사합니다", note: "Thank you, in the formal 합니다 style — the safest thanks for strangers, service staff, and anyone older. 감사해요 exists but sounds oddly soft; keep the fixed 감사합니다.", example: { ko: "선생님, 감사합니다.", en: "Thank you, teacher.", form: "감사하다 → 감사합니다 (present, formal polite 하십시오체 — used as a fixed phrase)" } },
    "kv0643": { korean: "고맙습니다", note: "Thank you — the native-Korean twin of 감사합니다 and equally polite. 고마워 is its casual form for friends, while 감사합니다 has no comfortable casual form.", example: { ko: "정말 고맙습니다.", en: "Thank you very much.", form: "고맙다 → 고맙습니다 (ㅂ-irregular stem, but -습니다 attaches directly; present, formal polite)" } },
    "kv0644": { korean: "괜찮아요", note: "'It's okay' — three jobs at once: declining an offer politely, reassuring someone, and answering 어때요? Rising intonation turns it into 'are you all right?'.", example: { ko: "괜찮아요, 고맙습니다.", en: "It's okay, thank you.", form: "괜찮다 → 괜찮아요 (present, polite casual)" } },
    "kv0649": { korean: "독일", note: "Germany. The country plus 사람 gives the nationality (독일 사람) and plus 어 gives the language (독일어), with no particle between the two nouns.", example: { ko: "저는 독일 사람이에요.", en: "I am German.", form: "독일 + 사람 (noun compound, no particle); 이에요 (present, polite casual)" } },
    "kv0653": { korean: "러시아", note: "Russia. Nationality is 러시아 사람 and the language 러시아어.", example: { ko: "그 사람은 러시아 사람이에요.", en: "That person is Russian.", form: "러시아 + 사람 (noun compound); 이에요 (present, polite casual)" } },
    "kv0654": { korean: "만나서 반가워요", note: "'Nice to meet you', literally 'having met you, I'm glad'. The -아서/어서 on 만나다 gives the reason, and the whole thing is used only at a first meeting. The formal version is 만나서 반갑습니다.", example: { ko: "안녕하세요, 만나서 반가워요.", en: "Hello, nice to meet you.", form: "만나다 + -아서 → 만나서 (reason link); 반갑다 → 반가워요 (ㅂ-irregular, present, polite casual)" } },
    "kv0660": { korean: "뭘요", note: "'Not at all' / 'don't mention it' — a modest brush-off after being thanked or praised. 아니에요 does the same job and is more common.", example: { ko: "뭘요, 괜찮아요.", en: "Not at all, it's fine.", form: "뭘요 is a fixed reply — 뭐 + 를 + 요, never conjugated" } },
    "kv0661": { korean: "미국", note: "The United States. 미국 사람 is an American and 미국어 does not exist — the language is 영어.", example: { ko: "저는 미국에서 왔어요.", en: "I came from the United States.", form: "미국 + 에서 (origin particle); 오다 → 왔어요 (past, polite casual)" } },
    "kv0666": { korean: "베트남", note: "Vietnam. Nationality 베트남 사람, language 베트남어.", example: { ko: "베트남 음식이 맛있어요.", en: "Vietnamese food is delicious.", form: "베트남 + 음식 (noun compound); 맛있다 → 맛있어요 (present, polite casual)" } },
    "kv0681": { korean: "안녕하세요", note: "Hello, at any hour of the day. It is 안녕하다 with the honorific -(으)세요, so it literally asks whether the other person is at peace; with a question mark it is a greeting question, without one a statement — both are read the same way.", example: { ko: "안녕하세요, 저는 마이클이에요.", en: "Hello, I am Michael.", form: "안녕하다 + -세요 → 안녕하세요 (honorific present, polite casual)" } },
    "kv0682": { korean: "안녕히 가세요", note: "Goodbye said to the person who is leaving — literally 'go peacefully'. Pick this one when you are the one staying put.", example: { ko: "안녕히 가세요, 선생님.", en: "Goodbye, teacher.", form: "가다 + -(으)세요 → 가세요 (honorific request, polite casual)" } },
    "kv0683": { korean: "안녕히 계세요", note: "Goodbye said to the person who is staying — literally 'stay peacefully', from 계시다, the honorific of 있다. Use this one when you are the one leaving.", example: { ko: "안녕히 계세요.", en: "Goodbye (I'm the one leaving).", form: "계시다 + -세요 → 계세요 (honorific request, polite casual)" } },
    "kv0687": { korean: "영국", note: "The United Kingdom. 영국 사람 is British; the language is 영어, which is shared with 미국.", example: { ko: "친구는 영국 사람이에요.", en: "My friend is British.", form: "영국 + 사람 (noun compound); 이에요 (present, polite casual)" } },
    "kv0694": { korean: "요리사", note: "A cook or chef. The 사 suffix marks a trained professional, as in 간호사 and 변호사; the act of cooking is 요리하다.", example: { ko: "형은 요리사예요.", en: "My older brother is a chef.", form: "요리사 + 예요 (이다 after a vowel; present, polite casual)" } },
    "kv0702": { korean: "일본", note: "Japan. Nationality 일본 사람, language 일본어. Note the shape overlap with 일 (work/day) — 일본 is a single unit.", example: { ko: "일본에 가요.", en: "I am going to Japan.", form: "일본 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv0708": { korean: "죄송합니다", note: "'I'm sorry' in the formal style — heavier and more apologetic than 미안합니다, and the right choice with strangers, customers, or anyone senior.", example: { ko: "늦어서 죄송합니다.", en: "I am sorry for being late.", form: "늦다 + -어서 → 늦어서 (reason link); 죄송하다 → 죄송합니다 (present, formal polite)" } },
    "kv0710": { korean: "중국", note: "China. Nationality 중국 사람, language 중국어. Do not confuse 중국 with 중 ('middle' or 'during').", example: { ko: "중국 음식을 좋아해요.", en: "I like Chinese food.", form: "중국 + 음식 (noun compound) + 을 (object particle); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "kv0717": { korean: "캐나다", note: "Canada. Nationality 캐나다 사람; the languages are 영어 and 프랑스어.", example: { ko: "저는 캐나다 사람이에요.", en: "I am Canadian.", form: "캐나다 + 사람 (noun compound); 이에요 (present, polite casual)" } },
    "kv0742": { korean: "호주", note: "Australia. Nationality 호주 사람. The alternative 오스트레일리아 exists but 호주 is what people actually say.", example: { ko: "호주에서 왔어요.", en: "I came from Australia.", form: "호주 + 에서 (origin particle); 오다 → 왔어요 (past, polite casual)" } },
    "kv0743": { korean: "회사원", note: "An office worker or company employee — the standard answer for 'what do you do?' when you work at a company. From 회사 (company) + 원 (member), the same 원 as in 은행원 and 공무원.", example: { ko: "저는 회사원이에요.", en: "I am an office worker.", form: "회사원 + 이에요 (이다 after a batchim; present, polite casual)" } },

    // ------------------------------------------------------------- Bab 2
    "kv0022": { korean: "그것", note: "'That thing' — near the listener, or something already mentioned. The three-way set is 이것 (near me), 그것 (near you), 저것 (away from both). In speech it shortens to 그거, and with the topic particle to 그건.", example: { ko: "그것은 사전이에요.", en: "That is a dictionary.", form: "그것 + 은 (topic particle); 이에요 (present, polite casual)" } },
    "kv0066": { korean: "이것", note: "'This thing' — near the speaker. Shortened to 이거 in speech, 이건 with the topic particle, 이게 with the subject particle. Note that 이것 is a pronoun standing alone, while 이 is a determiner needing a noun: 이 책.", example: { ko: "이것은 제 책이에요.", en: "This is my book.", form: "이것 + 은 (topic particle); 이에요 (present, polite casual)" } },
    "kv0099": { korean: "컴퓨터", note: "A computer. A laptop is 노트북 (not 랩탑), and 노트 on its own is a notebook you write in.", example: { ko: "컴퓨터가 비싸요.", en: "The computer is expensive.", form: "컴퓨터 + 가 (subject particle); 비싸다 → 비싸요 (present, polite casual)" } },
    "kv0426": { korean: "질문", note: "A question in the sense of asking something. The verb is 질문하다 or 질문을 하다, and 'to have a question' is 질문이 있다. A test question is 문제, not 질문.", example: { ko: "질문이 있어요.", en: "I have a question.", form: "질문 + 이 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0460": { korean: "대답", note: "An answer or reply. The verb 대답하다 takes 에 for what you are answering: 질문에 대답해요. A written answer on a test is 답.", example: { ko: "질문에 대답해요.", en: "I answer the question.", form: "질문 + 에 (target particle); 대답하다 → 대답해요 (present, polite casual)" } },
    "kv0464": { korean: "과일", note: "Fruit as a category. Counted with 개 for individual pieces, and note that 과일 is the food — the fruit of a tree in the abstract sense is 열매.", example: { ko: "과일을 좋아해요.", en: "I like fruit.", form: "과일 + 을 (object particle); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "kv0472": { korean: "책상", note: "A desk, literally 'book table'. A dining table is 식탁 and a low table is 상 — the 상 in 책상 is that same word.", example: { ko: "책상 위에 책이 있어요.", en: "There is a book on the desk.", form: "책상 + 위 + 에 (position noun plus location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0477": { korean: "시계", note: "A clock or a watch — Korean uses one word for both, with 손목시계 when you need to specify a wristwatch. A watch is worn with 차다, not 입다 or 쓰다.", example: { ko: "시계가 있어요.", en: "I have a watch.", form: "시계 + 가 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0504": { korean: "우유", note: "Milk. Counted by container: 우유 한 잔, 우유 한 병. Drink it with 마시다.", example: { ko: "우유를 마셔요.", en: "I drink milk.", form: "우유 + 를 (object particle); 마시다 → 마셔요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "kv0515": { korean: "의자", note: "A chair. Sitting on one uses 에 with 앉다: 의자에 앉아요. Note the pronunciation — 의 at the start of a word keeps its full [ɰi] sound.", example: { ko: "의자에 앉아요.", en: "I sit on the chair.", form: "의자 + 에 (location particle); 앉다 → 앉아요 (present, polite casual)" } },
    "kv0543": { korean: "사과", note: "An apple — and also an apology (사과하다 = to apologise). Same spelling, different words; the fruit is counted with 개.", example: { ko: "사과가 맛있어요.", en: "The apple is delicious.", form: "사과 + 가 (subject particle); 맛있다 → 맛있어요 (present, polite casual)" } },
    "kv0552": { korean: "오렌지", note: "An orange, the imported kind. The native Korean citrus 귤 (mandarin) is the fruit people actually eat in winter, so the two are not interchangeable.", example: { ko: "오렌지 주스를 마셔요.", en: "I drink orange juice.", form: "오렌지 + 주스 (noun compound) + 를 (object particle); 마시다 → 마셔요 (present, polite casual)" } },
    "kv0553": { korean: "저것", note: "'That thing over there' — away from both speaker and listener, and visible to both. Shortens to 저거, and to 저건 with the topic particle.", example: { ko: "저것은 뭐예요?", en: "What is that over there?", form: "저것 + 은 (topic particle); 뭐 + 예요 (present, polite casual, question)" } },
    "kv0554": { korean: "수박", note: "Watermelon. Counted with 통 for whole ones and 조각 for slices.", example: { ko: "여름에 수박을 먹어요.", en: "I eat watermelon in summer.", form: "수박 + 을 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0569": { korean: "공책", note: "A notebook for writing in, literally 'empty book'. The loanword 노트 means the same thing; 노트북 with 북 on the end is a laptop computer.", example: { ko: "공책이 있어요.", en: "I have a notebook.", form: "공책 + 이 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0573": { korean: "주스", note: "Juice. Usually named by fruit: 오렌지 주스, 포도 주스. Counted by the glass with 잔.", example: { ko: "주스를 마셔요.", en: "I drink juice.", form: "주스 + 를 (object particle); 마시다 → 마셔요 (present, polite casual)" } },
    "kv0574": { korean: "콜라", note: "Cola. Counted by can (캔) or bottle (병), and ordered with 주세요: 콜라 주세요.", example: { ko: "콜라 한 잔 주세요.", en: "One glass of cola, please.", form: "한 + 잔 (counter phrase, no particle needed); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0586": { korean: "사전", note: "A dictionary. 사전을 찾다 is 'to look something up', literally to search the dictionary.", example: { ko: "사전이 필요해요.", en: "I need a dictionary.", form: "사전 + 이 (subject particle — 필요하다 marks what is needed with 이/가); 필요하다 → 필요해요 (present, polite casual)" } },
    "kv0595": { korean: "딸기", note: "Strawberry. Counted with 개, and the flavour compound is 딸기 우유, 딸기 케이크.", example: { ko: "딸기가 아주 달아요.", en: "The strawberries are very sweet.", form: "딸기 + 가 (subject particle); 달다 → 달아요 (present, polite casual)" } },
    "kv0597": { korean: "포도", note: "Grapes. Korean treats it as a mass noun — 포도를 먹어요 covers any number — and a bunch is 포도 한 송이.", example: { ko: "포도를 먹어요.", en: "I eat grapes.", form: "포도 + 를 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0608": { korean: "칠판", note: "A blackboard or whiteboard at the front of a classroom. Writing on it uses 에: 칠판에 써요.", example: { ko: "선생님이 칠판에 써요.", en: "The teacher writes on the board.", form: "칠판 + 에 (surface particle); 쓰다 → 써요 (ㅡ-irregular; present, polite casual)" } },
    "kv0612": { korean: "지우개", note: "An eraser. The -개 suffix turns a verb into the tool that does it, from 지우다 (to erase) — the same pattern as 베개 (pillow) and 덮개 (cover).", example: { ko: "지우개가 없어요.", en: "I don't have an eraser.", form: "지우개 + 가 (subject particle); 없다 → 없어요 (present, polite casual)" } },
    "kv0645": { korean: "그건", note: "The contraction of 그것 + 은 — 'that thing, as for it'. Used constantly in speech; the full 그것은 sounds bookish. Its subject-particle counterpart is 그게 (그것이).", example: { ko: "그건 뭐예요?", en: "What is that?", form: "그것 + 은 contracted to 그건 (topic); 뭐 + 예요 (present, polite casual, question)" } },
    "kv0659": { korean: "뭐예요", note: "'What is it?' — 뭐 (the casual form of 무엇) plus 이다 in the polite casual ending. After a noun ending in a batchim the copula is 이에요 instead: 뭐예요 vs 책이에요.", example: { ko: "이건 뭐예요?", en: "What is this?", form: "뭐 + 예요 (이다 after a vowel; present, polite casual, question)" } },
    "kv0696": { korean: "이건", note: "The contraction of 이것 + 은 — 'this thing, as for it'. The everyday spoken form; 이게 is the subject version (이것이).", example: { ko: "이건 제 가방이에요.", en: "This is my bag.", form: "이것 + 은 contracted to 이건 (topic); 이에요 (present, polite casual)" } },
    "kv0704": { korean: "저건", note: "The contraction of 저것 + 은 — 'that thing over there, as for it'. Its subject version is 저게.", example: { ko: "저건 시계예요.", en: "That over there is a clock.", form: "저것 + 은 contracted to 저건 (topic); 예요 (present, polite casual)" } },
    "kv0705": { korean: "전자사전", note: "An electronic dictionary. 전자 ('electronic') builds many compounds: 전자책, 전자레인지, 전자 우편.", example: { ko: "전자사전을 사요.", en: "I buy an electronic dictionary.", form: "전자사전 + 을 (object particle); 사다 → 사요 (identical ㅏ merges; present, polite casual)" } },
    "kv0725": { korean: "파인애플", note: "Pineapple. Written as one word in Korean even though it is two in English, and counted with 개.", example: { ko: "파인애플이 맛있어요.", en: "The pineapple is delicious.", form: "파인애플 + 이 (subject particle); 맛있다 → 맛있어요 (present, polite casual)" } },
    "kv1018": { korean: "토마토", note: "Tomato. Treated as a fruit in Korean shops and counted with 개.", example: { ko: "토마토를 좋아해요.", en: "I like tomatoes.", form: "토마토 + 를 (object particle); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "kv1032": { korean: "음료수", note: "A soft drink or beverage — what a menu means by 'drinks'. Plain water is 물, and the general noun for a drink you order is this one.", example: { ko: "음료수를 마셔요.", en: "I drink a soft drink.", form: "음료수 + 를 (object particle); 마시다 → 마셔요 (present, polite casual)" } },
    "kv1043": { korean: "녹차", note: "Green tea. Tea names end in 차: 홍차 (black tea), 보리차 (barley tea). Counted by the cup with 잔.", example: { ko: "녹차 한 잔 주세요.", en: "One cup of green tea, please.", form: "한 + 잔 (counter phrase); 주다 + -세요 → 주세요 (polite request)" } },

    // ------------------------------------------------------------- Bab 3
    "kv0001": { korean: "하다", note: "To do — the most productive verb in Korean. Thousands of nouns become verbs by adding it (공부하다, 운동하다, 전화하다), and it is irregular: the stem plus -여요 contracts to 해요.", example: { ko: "저는 숙제를 해요.", en: "I do my homework.", form: "숙제 + 를 (object particle); 하다 → 해요 (하다-irregular; present, polite casual)" } },
    "kv0009": { korean: "보다", note: "To see or watch. It covers TV, movies, books, and also 'to meet up with' someone (친구를 봐요). Watching is 보다 but listening is 듣다, so music takes 듣다.", example: { ko: "텔레비전을 봐요.", en: "I watch television.", form: "텔레비전 + 을 (object particle); 보다 → 봐요 (ㅗ + 아 contracts to 와; present, polite casual)" } },
    "kv0010": { korean: "가다", note: "To go — motion away from the speaker, the pair of 오다. The destination takes 에 (학교에 가요) and the purpose takes -(으)러 (밥을 먹으러 가요).", example: { ko: "학교에 가요.", en: "I go to school.", form: "학교 + 에 (destination particle); 가다 → 가요 (identical ㅏ merges; present, polite casual)" } },
    "kv0015": { korean: "씨", note: "The neutral title attached to a name: 마이클 씨, 지영 씨. It is a dependent noun, so it never stands alone and always follows the name, with a space. Do not use it with your own name, and do not attach it to a family name alone (김 씨 sounds rude) — and never use it for someone clearly senior, who takes 선생님 or a job title.", example: { ko: "마이클 씨, 어디에 가요?", en: "Michael, where are you going?", form: "name + 씨 (dependent noun, always after the name); 가다 → 가요 (present, polite casual, question)" } },
    "kv0023": { korean: "집", note: "A house, and also 'home' in the abstract: 집에 가요 = I'm going home. As a suffix it names shops: 빵집 (bakery), 술집 (bar).", example: { ko: "집에 가요.", en: "I am going home.", form: "집 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv0029": { korean: "먹다", note: "To eat. Its honorific is 드시다 or 잡수시다, used when the eater deserves respect: 할머니가 드세요. Medicine is also 'eaten' in Korean: 약을 먹어요.", example: { ko: "밥을 먹어요.", en: "I eat a meal.", form: "밥 + 을 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0036": { korean: "다", note: "All, entirely — an adverb placed before the verb: 다 먹었어요 = I ate it all. It differs from the determiner 모든 (every) and from 전부, which is a noun.", example: { ko: "다 먹었어요.", en: "I ate it all.", form: "다 modifies the verb; 먹다 → 먹었어요 (past, polite casual)" } },
    "kv0051": { korean: "학교", note: "A school — the institution and the building. 학교에 가요 is 'go to school'; studying done there takes 에서: 학교에서 공부해요.", example: { ko: "학교에서 공부해요.", en: "I study at school.", form: "학교 + 에서 (particle for where an action happens); 공부하다 → 공부해요 (present, polite casual)" } },
    "kv0071": { korean: "앉다", note: "To sit down. The place you sit on takes 에: 의자에 앉아요. Its opposite is 서다 (to stand), and 'please sit' is 앉으세요.", example: { ko: "의자에 앉아요.", en: "I sit on the chair.", form: "의자 + 에 (location particle); 앉다 → 앉아요 (present, polite casual)" } },
    "kv0081": { korean: "읽다", note: "To read. Pronounced [익따] — the ㄹ of the cluster drops before a consonant but comes back before a vowel ending: 읽어요 is [일거요].", example: { ko: "책을 읽어요.", en: "I read a book.", form: "책 + 을 (object particle); 읽다 → 읽어요 (present, polite casual)" } },
    "kv0112": { korean: "밥", note: "Cooked rice, and by extension a meal — 밥 먹었어요? ('have you eaten?') is a standard greeting. Uncooked rice is 쌀 and the rice plant is 벼.", example: { ko: "밥을 먹어요.", en: "I eat a meal.", form: "밥 + 을 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0116": { korean: "마시다", note: "To drink. Its honorific is 드시다, shared with 먹다. Soup eaten with a spoon takes 먹다, not 마시다.", example: { ko: "물을 마셔요.", en: "I drink water.", form: "물 + 을 (object particle); 마시다 → 마셔요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "kv0120": { korean: "전화", note: "A telephone, and a phone call. Making a call is 전화하다 or 전화를 걸다; receiving one is 전화를 받다. A mobile phone is 휴대폰 or 핸드폰.", example: { ko: "친구한테 전화해요.", en: "I call my friend.", form: "친구 + 한테 (particle for a person receiving the action); 전화하다 → 전화해요 (present, polite casual)" } },
    "kv0124": { korean: "회사", note: "A company or firm. Its employee is 회사원, and going to work is 회사에 가요.", example: { ko: "회사에 가요.", en: "I go to the company.", form: "회사 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv0134": { korean: "배우다", note: "To learn — the student's side of 가르치다. What you learn takes 을/를, and the teacher takes 한테서 or 에게서.", example: { ko: "한국어를 배워요.", en: "I learn Korean.", form: "한국어 + 를 (object particle); 배우다 → 배워요 (ㅜ + 어 contracts to 워; present, polite casual)" } },
    "kv0147": { korean: "신문", note: "A newspaper. Read with 읽다 or 보다. Do not confuse it with 질문 (a question) or 소식 (news as information).", example: { ko: "신문을 읽어요.", en: "I read the newspaper.", form: "신문 + 을 (object particle); 읽다 → 읽어요 (present, polite casual)" } },
    "kv0172": { korean: "일하다", note: "To work. Built from 일 + 하다, so the workplace takes 에서: 회사에서 일해요. You can also split it as 일을 하다.", example: { ko: "회사에서 일해요.", en: "I work at a company.", form: "회사 + 에서 (particle for where an action happens); 일하다 → 일해요 (present, polite casual)" } },
    "kv0177": { korean: "가르치다", note: "To teach — the teacher's side of 배우다. The subject taught takes 을/를 and the learner takes 한테 or 에게. Careful: 가리키다 (to point at) is a different verb one letter away.", example: { ko: "선생님이 한국어를 가르쳐요.", en: "The teacher teaches Korean.", form: "한국어 + 를 (object particle); 가르치다 → 가르쳐요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "kv0188": { korean: "공부하다", note: "To study. The subject takes 을/를 (한국어를 공부해요) and can also be built as a compound: 한국어 공부를 해요.", example: { ko: "한국어를 공부해요.", en: "I study Korean.", form: "한국어 + 를 (object particle); 공부하다 → 공부해요 (present, polite casual)" } },
    "kv0422": { korean: "영어", note: "The English language. Language names are the country plus 어: 한국어, 일본어, 중국어 — but note that English is 영어, from 영국.", example: { ko: "영어를 가르쳐요.", en: "I teach English.", form: "영어 + 를 (object particle); 가르치다 → 가르쳐요 (present, polite casual)" } },
    "kv0453": { korean: "장소", note: "A place or venue in the abstract — the word used on forms and schedules ('location'). For 'where' in conversation people say 어디, and for a spot 곳.", example: { ko: "장소가 어디예요?", en: "Where is the venue?", form: "장소 + 가 (subject particle); 어디 + 예요 (present, polite casual, question)" } },
    "kv0457": { korean: "식당", note: "A restaurant or a cafeteria — anywhere meals are served, including a school canteen. A fancier restaurant is 레스토랑.", example: { ko: "식당에서 밥을 먹어요.", en: "I eat a meal at the restaurant.", form: "식당 + 에서 (particle for where an action happens); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0479": { korean: "도서관", note: "A library. The 관 suffix names public buildings: 영화관, 미술관, 체육관. Borrowing a book is 책을 빌려요.", example: { ko: "도서관에서 책을 읽어요.", en: "I read a book at the library.", form: "도서관 + 에서 (particle for where an action happens); 읽다 → 읽어요 (present, polite casual)" } },
    "kv0496": { korean: "닫다", note: "To close a door, window, or shop. Its opposite is 열다. For closing a book or eyes Koreans use 덮다 and 감다 instead.", example: { ko: "문을 닫아요.", en: "I close the door.", form: "문 + 을 (object particle); 닫다 → 닫아요 (present, polite casual)" } },
    "kv0556": { korean: "전화하다", note: "To make a phone call. The person called takes 한테 or 에게 (친구한테 전화해요), never 을/를.", example: { ko: "어머니한테 전화했어요.", en: "I called my mother.", form: "어머니 + 한테 (recipient particle); 전화하다 → 전화했어요 (past, polite casual)" } },
    "kv0563": { korean: "운동하다", note: "To exercise or work out. Built from 운동 + 하다; naming a specific sport is more natural than 운동하다 when you mean a game.", example: { ko: "아침에 운동해요.", en: "I exercise in the morning.", form: "아침 + 에 (time particle); 운동하다 → 운동해요 (present, polite casual)" } },
    "kv0635": { korean: "오", note: "Five in the Sino-Korean system — the one used for dates, money, phone numbers, and minutes. Its native-Korean counterpart is 다섯, used with counters like 개 and 명.", example: { ko: "오월 오일이에요.", en: "It is the fifth of May.", form: "오 + 월 / 오 + 일 (Sino-Korean number plus counter); 이에요 (present, polite casual)" } },
    "kv0658": { korean: "목욕하다", note: "To take a bath — soaking in a tub. A shower is 샤워하다, and washing just your face or hands is 씻다.", example: { ko: "저녁에 목욕해요.", en: "I take a bath in the evening.", form: "저녁 + 에 (time particle); 목욕하다 → 목욕해요 (present, polite casual)" } },
    "kv0718": { korean: "커피숍", note: "A coffee shop. 카페 is just as common; the place where an action happens takes 에서.", example: { ko: "커피숍에서 친구를 만나요.", en: "I meet a friend at the coffee shop.", form: "커피숍 + 에서 (particle for where an action happens); 만나다 → 만나요 (present, polite casual)" } },

    // ------------------------------------------------------------- Bab 4
    "kv0076": { korean: "사다", note: "To buy. The thing bought takes 을/를 and the shop takes 에서: 가게에서 빵을 사요. Its opposite is 팔다.", example: { ko: "시장에서 과일을 사요.", en: "I buy fruit at the market.", form: "시장 + 에서 (where the action happens); 사다 → 사요 (identical ㅏ merges; present, polite casual)" } },
    "kv0106": { korean: "오늘", note: "Today. Like 지금 it is a bare time word and takes no 에 — say 오늘 가요, not 오늘에 가요. The same is true of 어제 and 내일.", example: { ko: "오늘 학교에 가요.", en: "I go to school today.", form: "오늘 used adverbially with no particle; 가다 → 가요 (present, polite casual)" } },
    "kv0159": { korean: "은행", note: "A bank. Its employee is 은행원. Note the homophone 은행 meaning ginkgo — context always separates them.", example: { ko: "은행에 가요.", en: "I go to the bank.", form: "은행 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv0164": { korean: "병원", note: "A hospital, and also an ordinary doctor's clinic — Korean does not split the two the way English does. 병원에 가요 can mean a routine appointment.", example: { ko: "병원에 가요.", en: "I go to the hospital.", form: "병원 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv0210": { korean: "쉬다", note: "To rest or take a break. It is intransitive, so nothing takes 을/를: 집에서 쉬어요. It also covers taking a day off work.", example: { ko: "집에서 쉬어요.", en: "I rest at home.", form: "집 + 에서 (where the action happens); 쉬다 → 쉬어요 (present, polite casual)" } },
    "kv0436": { korean: "가게", note: "A small shop or store. Bigger formats have their own words: 마트, 백화점, 편의점.", example: { ko: "가게에서 우유를 사요.", en: "I buy milk at the shop.", form: "가게 + 에서 (where the action happens); 사다 → 사요 (present, polite casual)" } },
    "kv0498": { korean: "백화점", note: "A department store, literally 'hundred goods store'. Larger and pricier than a 마트, and a standard weekend destination.", example: { ko: "백화점에서 옷을 사요.", en: "I buy clothes at the department store.", form: "백화점 + 에서 (where the action happens); 사다 → 사요 (present, polite casual)" } },
    "kv0522": { korean: "호텔", note: "A hotel. Staying somewhere uses 에서 자다 or 묵다; the destination takes 에.", example: { ko: "호텔에서 자요.", en: "I sleep at the hotel.", form: "호텔 + 에서 (where the action happens); 자다 → 자요 (present, polite casual)" } },
    "kv0524": { korean: "운동장", note: "A sports field or schoolyard. The 장 suffix marks a place set aside for an activity: 주차장, 수영장, 시장.", example: { ko: "운동장에서 축구를 해요.", en: "I play soccer on the field.", form: "운동장 + 에서 (where the action happens); 하다 → 해요 (present, polite casual)" } },
    "kv0540": { korean: "공원", note: "A public park. Going there takes 에, doing something there takes 에서: 공원에서 산책해요.", example: { ko: "공원에서 산책해요.", en: "I take a walk in the park.", form: "공원 + 에서 (where the action happens); 산책하다 → 산책해요 (present, polite casual)" } },
    "kv0542": { korean: "구두", note: "Dress shoes — leather formal shoes specifically. Sneakers are 운동화 and the general word for footwear is 신발. All of them are worn with 신다.", example: { ko: "구두를 신어요.", en: "I put on dress shoes.", form: "구두 + 를 (object particle); 신다 → 신어요 (present, polite casual — footwear takes 신다, not 입다)" } },
    "kv0549": { korean: "불고기", note: "Bulgogi — marinated grilled beef, literally 'fire meat'. A dish name, so it takes 먹다: 불고기를 먹어요.", example: { ko: "불고기를 먹어요.", en: "I eat bulgogi.", form: "불고기 + 를 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0565": { korean: "청소하다", note: "To clean a space — a room, a house. Washing an object is 씻다 and doing laundry is 빨래하다, so 청소하다 is specifically tidying and sweeping.", example: { ko: "방을 청소해요.", en: "I clean the room.", form: "방 + 을 (object particle); 청소하다 → 청소해요 (present, polite casual)" } },
    "kv0571": { korean: "서점", note: "A bookstore. The 점 suffix marks shops: 서점, 편의점, 백화점.", example: { ko: "서점에서 책을 사요.", en: "I buy a book at the bookstore.", form: "서점 + 에서 (where the action happens); 사다 → 사요 (present, polite casual)" } },
    "kv0587": { korean: "약국", note: "A pharmacy. 약 is medicine, and medicine is 'eaten' in Korean: 약을 먹어요.", example: { ko: "약국에서 약을 사요.", en: "I buy medicine at the pharmacy.", form: "약국 + 에서 (where the action happens); 사다 → 사요 (present, polite casual)" } },
    "kv0600": { korean: "쇼핑", note: "Shopping. The verb is 쇼핑하다 or 쇼핑을 하다; going shopping is 쇼핑하러 가요.", example: { ko: "주말에 쇼핑을 해요.", en: "I go shopping at the weekend.", form: "쇼핑 + 을 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0607": { korean: "청바지", note: "Jeans, literally 'blue trousers'. Like 바지 it is singular in Korean and worn with 입다.", example: { ko: "청바지를 입어요.", en: "I wear jeans.", form: "청바지 + 를 (object particle); 입다 → 입어요 (present, polite casual)" } },
    "kv0623": { korean: "요리하다", note: "To cook. The dish takes 을/를: 불고기를 요리해요. For simply making food, 만들다 is just as common.", example: { ko: "저녁을 요리해요.", en: "I cook dinner.", form: "저녁 + 을 (object particle); 요리하다 → 요리해요 (present, polite casual)" } },
    "kv0647": { korean: "놀이공원", note: "An amusement park, from 놀이 (play) + 공원 (park). The verb for having fun there is 놀다.", example: { ko: "놀이공원에 가요.", en: "I go to the amusement park.", form: "놀이공원 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv0664": { korean: "미용실", note: "A hair salon. The 실 suffix marks a room or small establishment: 교실, 사무실, 화장실.", example: { ko: "미용실에서 머리를 잘라요.", en: "I get my hair cut at the salon.", form: "미용실 + 에서 (where the action happens); 자르다 → 잘라요 (르-irregular; present, polite casual)" } },
    "kv0688": { korean: "영화관", note: "A cinema. 극장 means the same thing and is slightly older-sounding; both take 에서 for watching a film there.", example: { ko: "영화관에서 영화를 봐요.", en: "I watch a movie at the cinema.", form: "영화관 + 에서 (where the action happens); 보다 → 봐요 (present, polite casual)" } },
    "kv0703": { korean: "자켓", note: "A jacket, also spelled 재킷 in standard orthography. Worn with 입다 like other body clothing.", example: { ko: "자켓을 입어요.", en: "I wear a jacket.", form: "자켓 + 을 (object particle); 입다 → 입어요 (present, polite casual)" } },
    "kv1011": { korean: "시내", note: "Downtown, the city centre — literally 'inside the city'. 시외 is outside it, and a whole city is 도시.", example: { ko: "시내에서 친구를 만나요.", en: "I meet a friend downtown.", form: "시내 + 에서 (where the action happens); 만나다 → 만나요 (present, polite casual)" } },
    "kv1019": { korean: "노래방", note: "A karaoke room — a private room rented by the hour, not a bar stage. The 방 suffix names these rented rooms: 피시방, 찜질방.", example: { ko: "노래방에서 노래해요.", en: "I sing at the karaoke room.", form: "노래방 + 에서 (where the action happens); 노래하다 → 노래해요 (present, polite casual)" } },
    "kv1022": { korean: "주차장", note: "A parking lot. Parking a car is 주차하다, and 장 again marks the place set aside for it.", example: { ko: "주차장이 넓어요.", en: "The parking lot is spacious.", form: "주차장 + 이 (subject particle); 넓다 → 넓어요 (present, polite casual)" } },
    "kv1046": { korean: "세탁소", note: "A dry cleaner's. 세탁 is laundering and the 소 suffix marks a small business or office, as in 사무소.", example: { ko: "세탁소에 가요.", en: "I go to the dry cleaner's.", form: "세탁소 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },

    // ------------------------------------------------------------- Bab 6
    "kv0008": { korean: "우리", note: "We, us, our — and much wider than English 'our': Koreans say 우리 집, 우리 학교, even 우리 엄마 for things that are only theirs. Its humble form before elders is 저희.", example: { ko: "우리는 공원에 가요.", en: "We are going to the park.", form: "우리 + 는 (topic particle); 가다 → 가요 (present, polite casual)" } },
    "kv0025": { korean: "저", note: "The polite 'I' — the default with strangers, elders, and in any formal setting; 나 is its casual counterpart. With the subject particle it becomes 제가, and 'my' is 제. Do not confuse it with the determiner 저 ('that over there').", example: { ko: "저는 학생이에요.", en: "I am a student.", form: "저 + 는 (topic particle); 이에요 (present, polite casual)" } },
    "kv0031": { korean: "어떻다", note: "'To be how' — the adjective behind 어때요? ('how is it?'), the standard way to ask an opinion. It is a ㅎ-irregular: 어떻다 → 어때요, and its noun-modifying form is 어떤 (what kind of).", example: { ko: "한국 음식이 어때요?", en: "How is Korean food?", form: "어떻다 → 어때요 (ㅎ-irregular; present, polite casual, question)" } },
    "kv0075": { korean: "이야기", note: "A talk, a chat, or a story. 이야기하다 is to talk, and the conversation partner takes 하고 or 와/과. Shortened to 얘기 in speech.", example: { ko: "친구하고 이야기를 해요.", en: "I have a chat with a friend.", form: "이야기 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0115": { korean: "그림", note: "A picture or drawing — the noun form of 그리다. Drawing one is 그림을 그려요, and hanging one is 그림을 걸어요.", example: { ko: "그림을 그려요.", en: "I draw a picture.", form: "그림 + 을 (object particle); 그리다 → 그려요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "kv0132": { korean: "좋아하다", note: "To like. Unlike the adjective 좋다, this is an action verb, so the thing liked is an object with 을/를: 저는 커피를 좋아해요. Saying 커피가 좋아요 shifts the meaning to 'coffee is good/appealing'.", example: { ko: "저는 커피를 좋아해요.", en: "I like coffee.", form: "커피 + 를 (object particle); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "kv0133": { korean: "그리다", note: "To draw or paint. Its object is usually 그림 or the thing depicted. Careful with the near-twins 그리고 (and) and 그립다 (to miss).", example: { ko: "동생이 그림을 그려요.", en: "My younger sibling draws a picture.", form: "그림 + 을 (object particle); 그리다 → 그려요 (present, polite casual)" } },
    "kv0142": { korean: "노래", note: "A song. Singing is 노래하다 or, more idiomatically, 노래를 불러요 — the verb 부르다 ('to call') doubles as 'to sing'.", example: { ko: "노래를 불러요.", en: "I sing a song.", form: "노래 + 를 (object particle); 부르다 → 불러요 (르-irregular; present, polite casual)" } },
    "kv0144": { korean: "공부", note: "Study as a noun. Turn it into a verb with 하다 — 공부해요 — or split it: 한국어 공부를 해요.", example: { ko: "공부가 재미있어요.", en: "Studying is interesting.", form: "공부 + 가 (subject particle); 재미있다 → 재미있어요 (present, polite casual)" } },
    "kv0151": { korean: "이야기하다", note: "To talk or chat. The other person takes 하고, 와/과, or 한테, and the topic takes 에 대해: 영화에 대해 이야기해요.", example: { ko: "친구하고 이야기해요.", en: "I chat with a friend.", form: "친구 + 하고 (companion particle); 이야기하다 → 이야기해요 (present, polite casual)" } },
    "kv0152": { korean: "자다", note: "To sleep. Its honorific is 주무시다, and 'to fall asleep' is 잠이 들다. The common phrase 잠을 자다 pairs it with its own noun.", example: { ko: "밤에 자요.", en: "I sleep at night.", form: "밤 + 에 (time particle); 자다 → 자요 (identical ㅏ merges; present, polite casual)" } },
    "kv0169": { korean: "잠", note: "Sleep as a noun — the noun form of 자다. Used in fixed pairings: 잠을 자다 (to sleep), 잠이 오다 (to feel sleepy), 잠이 들다 (to fall asleep).", example: { ko: "잠이 와요.", en: "I feel sleepy.", form: "잠 + 이 (subject particle — sleep is what 'comes'); 오다 → 와요 (present, polite casual)" } },
    "kv0182": { korean: "사진", note: "A photograph. Taking one uses 찍다, never 만들다 or 하다: 사진을 찍어요.", example: { ko: "사진을 찍어요.", en: "I take a photo.", form: "사진 + 을 (object particle); 찍다 → 찍어요 (present, polite casual)" } },
    "kv0193": { korean: "게임", note: "A game, usually a video game. Playing one is 게임을 해요 — 놀다 means to hang out or play in general, not to play a game.", example: { ko: "게임을 해요.", en: "I play a game.", form: "게임 + 을 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0433": { korean: "찍다", note: "To take a photo, and also to stamp or dip — 도장을 찍다 (stamp a seal), 소스에 찍다 (dip in sauce). For photos the object is 사진, even when you name the subject: 친구 사진을 찍어요.", example: { ko: "친구 사진을 찍었어요.", en: "I took a photo of my friend.", form: "사진 + 을 (object particle); 찍다 → 찍었어요 (past, polite casual)" } },
    "kv0450": { korean: "따뜻하다", note: "Warm, in the pleasant sense — spring weather, warm soup, a warm person. Hotter than comfortable is 덥다 (weather) or 뜨겁다 (touch).", example: { ko: "봄 날씨가 따뜻해요.", en: "Spring weather is warm.", form: "따뜻하다 → 따뜻해요 (하다 contracts to 해요; present, polite casual)" } },
    "kv0461": { korean: "춤", note: "A dance — the noun form of 추다. It appears almost only in the pairing 춤을 추다, which is how Koreans say 'to dance'.", example: { ko: "춤을 춰요.", en: "I dance.", form: "춤 + 을 (object particle); 추다 → 춰요 (ㅜ + 어 contracts to 워; present, polite casual)" } },
    "kv0469": { korean: "요리", note: "Cooking, or a cooked dish. 요리하다 is to cook and 요리사 is a chef; 한국 요리 means Korean cuisine.", example: { ko: "한국 요리를 배워요.", en: "I learn Korean cooking.", form: "요리 + 를 (object particle); 배우다 → 배워요 (present, polite casual)" } },
    "kv0488": { korean: "시원하다", note: "Refreshingly cool — autumn air, a cold drink on a hot day, and famously hot soup that clears your head. It is a positive word, unlike 춥다 (unpleasantly cold).", example: { ko: "가을 날씨가 시원해요.", en: "Autumn weather is cool.", form: "시원하다 → 시원해요 (하다 contracts to 해요; present, polite casual)" } },
    "kv0518": { korean: "추다", note: "To dance — but it takes 춤 as its object almost without exception: 춤을 춰요. It never stands alone the way English 'dance' does.", example: { ko: "친구하고 춤을 춰요.", en: "I dance with a friend.", form: "춤 + 을 (object particle); 추다 → 춰요 (present, polite casual)" } },
    "kv0523": { korean: "청소", note: "Cleaning as a noun. Used as 청소를 하다 or the compound verb 청소하다.", example: { ko: "청소를 해요.", en: "I do the cleaning.", form: "청소 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0546": { korean: "노래하다", note: "To sing. Perfectly correct, though 노래를 부르다 is what people say more often in everyday speech.", example: { ko: "노래방에서 노래해요.", en: "I sing at the karaoke room.", form: "노래방 + 에서 (where the action happens); 노래하다 → 노래해요 (present, polite casual)" } },
    "kv0560": { korean: "기숙사", note: "A dormitory. Living there takes 에서 살다: 기숙사에서 살아요.", example: { ko: "기숙사에서 살아요.", en: "I live in the dormitory.", form: "기숙사 + 에서 (where the action happens); 살다 → 살아요 (present, polite casual)" } },
    "kv0561": { korean: "산책", note: "A stroll. The verb is 산책하다 or 산책을 하다, and the place takes 에서: 공원에서 산책해요.", example: { ko: "공원에서 산책을 해요.", en: "I take a walk in the park.", form: "산책 + 을 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0566": { korean: "등산", note: "Hiking or mountain climbing. The verb is 등산하다, and 산에 가다 ('go to the mountain') means the same in casual speech.", example: { ko: "주말에 등산을 해요.", en: "I go hiking at the weekend.", form: "등산 + 을 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0583": { korean: "햄버거", note: "A hamburger. Counted with 개, and eaten with 먹다.", example: { ko: "햄버거를 먹어요.", en: "I eat a hamburger.", form: "햄버거 + 를 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0591": { korean: "김밥", note: "Gimbap — rice and fillings rolled in seaweed. Counted by the roll (한 줄), not by the slice.", example: { ko: "김밥 한 줄 주세요.", en: "One roll of gimbap, please.", form: "한 + 줄 (counter phrase for rolled food); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0603": { korean: "운동화", note: "Sneakers or trainers, literally 'exercise shoes'. The 화 suffix marks footwear: 구두, 등산화, 실내화. Put them on with 신다.", example: { ko: "운동화를 신어요.", en: "I put on sneakers.", form: "운동화 + 를 (object particle); 신다 → 신어요 (present, polite casual)" } },
    "kv0655": { korean: "만화책", note: "A comic book — 만화 (comics) plus 책. Read with 읽다 or 보다, and counted with 권.", example: { ko: "만화책을 읽어요.", en: "I read a comic book.", form: "만화책 + 을 (object particle); 읽다 → 읽어요 (present, polite casual)" } },
    "kv0669": { korean: "빨래하다", note: "To do the laundry. Distinct from 청소하다 (cleaning a space) and 씻다 (washing yourself or an object).", example: { ko: "주말에 빨래해요.", en: "I do laundry at the weekend.", form: "주말 + 에 (time particle); 빨래하다 → 빨래해요 (present, polite casual)" } },
    "kv0674": { korean: "쇼핑하다", note: "To shop. The place takes 에서: 백화점에서 쇼핑해요. To go shopping, use the purpose ending: 쇼핑하러 가요.", example: { ko: "백화점에서 쇼핑해요.", en: "I shop at the department store.", form: "백화점 + 에서 (where the action happens); 쇼핑하다 → 쇼핑해요 (present, polite casual)" } },
    "kv0676": { korean: "수영하다", note: "To swim. The pool takes 에서: 수영장에서 수영해요. 수영을 하다 splits the same word.", example: { ko: "수영장에서 수영해요.", en: "I swim at the pool.", form: "수영장 + 에서 (where the action happens); 수영하다 → 수영해요 (present, polite casual)" } },
    "kv0724": { korean: "탁구", note: "Table tennis, literally 'table ball'. Like other racket sports it takes 치다: 탁구를 쳐요.", example: { ko: "탁구를 쳐요.", en: "I play table tennis.", form: "탁구 + 를 (object particle); 치다 → 쳐요 (present, polite casual)" } },
    "kv1013": { korean: "빨래", note: "Laundry — both the washing and the clothes themselves. Used as 빨래를 하다 or the compound verb 빨래하다.", example: { ko: "빨래를 해요.", en: "I do the laundry.", form: "빨래 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },

    // ------------------------------------------------------------- Bab 7
    "kv0028": { korean: "앞", note: "The front, or the space in front of something. Position words work as noun + 앞 + 에: 학교 앞에 있어요. It also means 'ahead' in time: 앞으로 (from now on).", example: { ko: "학교 앞에 편의점이 있어요.", en: "There is a convenience store in front of the school.", form: "학교 + 앞 + 에 (position noun plus location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0033": { korean: "여자", note: "A woman or girl. 여자 친구 as one unit means girlfriend, while 여자 사람 친구 is a female friend — the spacing matters. The formal word is 여성.", example: { ko: "저 여자는 제 친구예요.", en: "That woman is my friend.", form: "여자 + 는 (topic particle); 예요 (present, polite casual)" } },
    "kv0035": { korean: "뒤", note: "The back, or the space behind something: 집 뒤에 있어요. It also means 'later' in time: 뒤에 봐요.", example: { ko: "집 뒤에 나무가 있어요.", en: "There is a tree behind the house.", form: "집 + 뒤 + 에 (position noun plus location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0045": { korean: "다음", note: "Next, or 'the following'. As a determiner-like noun it sits before another noun with no particle: 다음 주, 다음 달, 다음 사람. On its own with 에 it means 'next time'.", example: { ko: "다음 주에 만나요.", en: "Let's meet next week.", form: "다음 + 주 (no particle between them) + 에 (time particle); 만나다 → 만나요 (present, polite casual — also reads as a suggestion)" } },
    "kv0049": { korean: "위", note: "The top, or the space above something: 책상 위에 있어요. It covers both resting on a surface and floating above it, where English splits 'on' and 'over'.", example: { ko: "책상 위에 책이 있어요.", en: "There is a book on the desk.", form: "책상 + 위 + 에 (position noun plus location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0073": { korean: "몇", note: "'How many' or 'what number' — a determiner that must be followed by a counter, never used alone: 몇 개, 몇 명, 몇 시. It also means 'a few' in statements: 몇 명 왔어요.", example: { ko: "지금 몇 시예요?", en: "What time is it now?", form: "몇 + 시 (determiner plus counter, no particle between); 예요 (present, polite casual, question)" } },
    "kv0093": { korean: "밖", note: "The outside — the opposite of 안. Used as noun + 밖에: 집 밖에 있어요. Careful: the particle 밖에 ('only') is a different word and always pairs with a negative verb.", example: { ko: "집 밖에 차가 있어요.", en: "There is a car outside the house.", form: "집 + 밖 + 에 (position noun plus location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0135": { korean: "옆", note: "The side, or 'next to': 학교 옆에 있어요. For the space between two things use 사이.", example: { ko: "은행 옆에 약국이 있어요.", en: "There is a pharmacy next to the bank.", form: "은행 + 옆 + 에 (position noun plus location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0137": { korean: "아래", note: "Below or underneath: 책상 아래에 있어요. 밑 means the same thing and is more common in speech, while 아래 is slightly more formal.", example: { ko: "의자 아래에 가방이 있어요.", en: "There is a bag under the chair.", form: "의자 + 아래 + 에 (position noun plus location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0139": { korean: "배", note: "Three unrelated words share this shape: stomach, boat, and pear. Context decides — 배가 아파요 (stomach), 배를 타요 (boat), 배를 먹어요 (pear).", example: { ko: "배가 아파요.", en: "My stomach hurts.", form: "배 + 가 (subject particle); 아프다 → 아파요 (ㅡ-irregular; present, polite casual)" } },
    "kv0140": { korean: "산", note: "A mountain. Climbing one is 산에 올라가요 or 등산해요, and Korean mountain names attach it directly: 남산, 설악산.", example: { ko: "산이 높아요.", en: "The mountain is high.", form: "산 + 이 (subject particle); 높다 → 높아요 (present, polite casual)" } },
    "kv0205": { korean: "팔", note: "An arm, and also the Sino-Korean number eight. The body part takes ordinary particles; the number combines with counters: 팔월 (August), 팔 개.", example: { ko: "팔이 아파요.", en: "My arm hurts.", form: "팔 + 이 (subject particle); 아프다 → 아파요 (ㅡ-irregular; present, polite casual)" } },
    "kv0448": { korean: "여러분", note: "'Everyone' as a polite address to a group — the word a teacher or speaker uses for an audience. It is already respectful and is not used to refer to a group in the third person.", example: { ko: "여러분, 안녕하세요.", en: "Hello, everyone.", form: "여러분 used as direct address, no particle; 안녕하다 + -세요 → 안녕하세요 (honorific, polite casual)" } },
    "kv0475": { korean: "침대", note: "A bed. Lying on one takes 에: 침대에 누워요. A traditional floor mattress is 이불 and 요.", example: { ko: "침대 위에 고양이가 있어요.", en: "There is a cat on the bed.", form: "침대 + 위 + 에 (position noun plus location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0503": { korean: "창문", note: "A window. Opening and closing it uses 열다 and 닫다: 창문을 열어요.", example: { ko: "창문을 열어요.", en: "I open the window.", form: "창문 + 을 (object particle); 열다 → 열어요 (present, polite casual)" } },
    "kv0541": { korean: "천", note: "A thousand, in the Sino-Korean system. Korean counts in units of 만 (ten thousand), so 10,000 is 만 and not 십천. Note the homonym 천 meaning cloth.", example: { ko: "이 책은 천 원이에요.", en: "This book is a thousand won.", form: "천 + 원 (Sino-Korean number plus counter); 이에요 (present, polite casual)" } },
    "kv0544": { korean: "냉장고", note: "A refrigerator, literally 'cold storage box'. The freezer compartment is 냉동고.", example: { ko: "냉장고에 우유가 있어요.", en: "There is milk in the fridge.", form: "냉장고 + 에 (location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0577": { korean: "삼", note: "Three in the Sino-Korean system — for dates, money, floors, and phone numbers. The native-Korean three is 셋/세, used with counters like 개 and 명.", example: { ko: "삼월에 학교에 가요.", en: "I go to school in March.", form: "삼 + 월 (Sino-Korean number plus counter) + 에 (time particle); 가다 → 가요 (present, polite casual)" } },
    "kv0609": { korean: "구", note: "Nine in the Sino-Korean system, as in 구월 (September) and 구십 (ninety). The native nine is 아홉.", example: { ko: "구월이에요.", en: "It is September.", form: "구 + 월 (Sino-Korean number plus counter); 이에요 (present, polite casual)" } },
    "kv0613": { korean: "사", note: "Four in the Sino-Korean system. Because it sounds like the 사 of 死 (death), Korean buildings often label the fourth floor F instead of 4. The native four is 넷/네.", example: { ko: "사월이에요.", en: "It is April.", form: "사 + 월 (Sino-Korean number plus counter); 이에요 (present, polite casual)" } },
    "kv0624": { korean: "칠", note: "Seven in the Sino-Korean system, as in 칠월 (July). The native seven is 일곱.", example: { ko: "칠월에 여행을 가요.", en: "I travel in July.", form: "칠 + 월 + 에 (Sino-Korean number, counter, time particle); 가다 → 가요 (present, polite casual)" } },
    "kv0626": { korean: "사십", note: "Forty — Sino-Korean tens are built by multiplication: 사 (4) + 십 (10). The native equivalent 마흔 is used with counters like 살 for age.", example: { ko: "사십 분 걸려요.", en: "It takes forty minutes.", form: "사십 + 분 (Sino-Korean number plus counter); 걸리다 → 걸려요 (present, polite casual)" } },
    "kv0628": { korean: "육", note: "Six in the Sino-Korean system, as in 유월 (June) — note that the ㄱ drops in the month name. The native six is 여섯.", example: { ko: "육 층에 있어요.", en: "It is on the sixth floor.", form: "육 + 층 (Sino-Korean number plus counter) + 에 (location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0633": { korean: "칠십", note: "Seventy — 칠 (7) + 십 (10) in the Sino-Korean pattern. Its native counterpart is 일흔.", example: { ko: "할머니는 칠십 세예요.", en: "My grandmother is seventy years old.", form: "칠십 + 세 (Sino-Korean number plus the formal age counter); 예요 (present, polite casual)" } },
    "kv0636": { korean: "십", note: "Ten in the Sino-Korean system, and the building block for the tens: 이십, 삼십, 사십. The native ten is 열.", example: { ko: "십 분 후에 만나요.", en: "Let's meet in ten minutes.", form: "십 + 분 (Sino-Korean number plus counter); 만나다 → 만나요 (present, polite casual)" } },
    "kv0640": { korean: "이십", note: "Twenty — 이 (2) + 십 (10). Its native counterpart 스물 is what you use for age with 살: 스무 살.", example: { ko: "이십 분 걸려요.", en: "It takes twenty minutes.", form: "이십 + 분 (Sino-Korean number plus counter); 걸리다 → 걸려요 (present, polite casual)" } },
    "kv0692": { korean: "옷장", note: "A wardrobe or closet, from 옷 (clothes) + 장 (cabinet). The same 장 appears in 책장 (bookshelf) and 냉장고.", example: { ko: "옷장 안에 옷이 많아요.", en: "There are a lot of clothes in the wardrobe.", form: "옷장 + 안 + 에 (position noun plus location particle); 많다 → 많아요 (present, polite casual)" } },
    "kv0727": { korean: "편의점", note: "A convenience store — the 24-hour kind on every corner. From 편의 (convenience) + 점 (shop).", example: { ko: "편의점에서 물을 사요.", en: "I buy water at the convenience store.", form: "편의점 + 에서 (where the action happens); 사다 → 사요 (present, polite casual)" } },
    "kv1000": { korean: "집안", note: "Inside the house, and also 'the household' or family line. Written as one word it leans towards the family sense; 집 안 with a space is plainly the interior.", example: { ko: "집안이 깨끗해요.", en: "The inside of the house is clean.", form: "집안 + 이 (subject particle); 깨끗하다 → 깨끗해요 (present, polite casual)" } },
    "kv1047": { korean: "필통", note: "A pencil case, from 필 (writing brush) + 통 (container). The same 통 appears in 쓰레기통 (bin).", example: { ko: "필통에 연필이 있어요.", en: "There is a pencil in the pencil case.", form: "필통 + 에 (location particle); 있다 → 있어요 (present, polite casual)" } },

    // --------------------------------------------------- Bab 4 (continued)
    "kv0024": { korean: "그리고", note: "'And' joining two whole sentences, placed at the start of the second one. It cannot join two nouns — that job belongs to 하고, 와/과, or 랑: 빵하고 우유, never 빵 그리고 우유 in speech.", example: { ko: "밥을 먹어요. 그리고 커피를 마셔요.", en: "I eat a meal. And then I drink coffee.", form: "그리고 opens the second sentence and never conjugates; 마시다 → 마셔요 (present, polite casual)" } },
    "kv0060": { korean: "친구", note: "A friend. Korean does not use it loosely for acquaintances, and it implies rough equality in age — someone older is 형/오빠/언니/누나, not 친구.", example: { ko: "친구를 만나요.", en: "I meet a friend.", form: "친구 + 를 (object particle); 만나다 → 만나요 (present, polite casual)" } },
    "kv0064": { korean: "만나다", note: "To meet. The person met takes 을/를 (친구를 만나요) or 하고/와 for a mutual meeting — but never 에게. The place takes 에서.", example: { ko: "공원에서 친구를 만나요.", en: "I meet a friend at the park.", form: "공원 + 에서 (where the action happens); 친구 + 를 (object particle); 만나다 → 만나요 (present, polite casual)" } },

    // ------------------------------------------------------------- Bab 8
    "kv0011": { korean: "년", note: "The counter for years, used with Sino-Korean numbers: 이천이십오 년. As a calendar year it needs no space in dates, and 'for N years' is 년 동안.", example: { ko: "이천이십오 년에 한국에 갔어요.", en: "I went to Korea in 2025.", form: "Sino-Korean number + 년 (counter) + 에 (time particle); 가다 → 갔어요 (past, polite casual)" } },
    "kv0038": { korean: "함께", note: "Together — the more formal or written twin of 같이. The companion takes 하고, 와/과, or 랑: 친구와 함께 가요.", example: { ko: "가족과 함께 여행해요.", en: "I travel together with my family.", form: "가족 + 과 (companion particle after a batchim); 함께 modifies the verb; 여행하다 → 여행해요 (present, polite casual)" } },
    "kv0067": { korean: "이번", note: "This time, this coming one. It sits before a time noun with no particle: 이번 주, 이번 달, 이번 주말. Its partners are 지난 (last) and 다음 (next).", example: { ko: "이번 주말에 뭐 해요?", en: "What are you doing this weekend?", form: "이번 + 주말 (no particle between) + 에 (time particle); 하다 → 해요 (present, polite casual, question)" } },
    "kv0168": { korean: "시험", note: "An exam. You 'see' one in Korean: 시험을 봐요, not 시험을 해요. Studying for it is 시험 공부.", example: { ko: "내일 시험을 봐요.", en: "I take an exam tomorrow.", form: "시험 + 을 (object particle); 보다 → 봐요 (present, polite casual — exams take 보다)" } },
    "kv0195": { korean: "언제", note: "When. It goes wherever the time phrase would go and takes no particle in questions: 언제 가요? With 에 it becomes 언제에… only in rare fixed phrases, so leave it bare.", example: { ko: "생일이 언제예요?", en: "When is your birthday?", form: "언제 + 예요 (이다 after a vowel; present, polite casual, question)" } },
    "kv0197": { korean: "수업", note: "A class or lesson. Attending is 수업을 들어요 (literally 'listen to the class'), and it starts and ends with 시작하다 / 끝나다.", example: { ko: "수업이 아홉 시에 시작해요.", en: "Class starts at nine o'clock.", form: "수업 + 이 (subject particle); 아홉 + 시 + 에 (native number, counter, time particle); 시작하다 → 시작해요 (present, polite casual)" } },
    "kv0199": { korean: "층", note: "The counter for floors of a building, used with Sino-Korean numbers: 일 층, 이 층, 삼 층. It is also the noun 'floor' on its own: 몇 층이에요?", example: { ko: "화장실은 이 층에 있어요.", en: "The restroom is on the second floor.", form: "이 + 층 (Sino-Korean number plus counter) + 에 (location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0209": { korean: "오월", note: "May. Month names are the Sino-Korean number plus 월, and May is regular: 오 + 월.", example: { ko: "오월에 생일이에요.", en: "My birthday is in May.", form: "오월 + 에 (time particle); 이에요 (present, polite casual)" } },
    "kv0419": { korean: "구월", note: "September — 구 (9) + 월, formed regularly.", example: { ko: "구월에 학교가 시작해요.", en: "School starts in September.", form: "구월 + 에 (time particle); 시작하다 → 시작해요 (present, polite casual)" } },
    "kv0421": { korean: "유월", note: "June — one of the two irregular months: 육 loses its ㄱ, giving 유월 rather than 육월. The other irregular is 시월 (October).", example: { ko: "유월에 날씨가 더워요.", en: "The weather is hot in June.", form: "유월 + 에 (time particle); 덥다 → 더워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0423": { korean: "삼월", note: "March — 삼 (3) + 월. In Korea the school year starts here, not in September.", example: { ko: "삼월에 학교에 가요.", en: "I go to school in March.", form: "삼월 + 에 (time particle); 가다 → 가요 (present, polite casual)" } },
    "kv0458": { korean: "십이월", note: "December — 십이 (12) + 월, formed regularly.", example: { ko: "십이월에 눈이 와요.", en: "It snows in December.", form: "십이월 + 에 (time particle); 눈 + 이 (subject particle); 오다 → 와요 (present, polite casual — snow 'comes' in Korean)" } },
    "kv0465": { korean: "시월", note: "October — the second irregular month: 십 loses its ㅂ, giving 시월 instead of 십월. (June, 유월, is the other one.)", example: { ko: "시월에 여행을 가요.", en: "I travel in October.", form: "시월 + 에 (time particle); 가다 → 가요 (present, polite casual)" } },
    "kv0478": { korean: "일월", note: "January — 일 (1) + 월. Do not confuse it with 일요일 (Sunday) or 일 (day).", example: { ko: "일월에 아주 추워요.", en: "It is very cold in January.", form: "일월 + 에 (time particle); 춥다 → 추워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0483": { korean: "이월", note: "February — 이 (2) + 월. Careful with the near-twin 이번 달 ('this month').", example: { ko: "이월에 눈이 많이 와요.", en: "It snows a lot in February.", form: "이월 + 에 (time particle); 많이 modifies the verb; 오다 → 와요 (present, polite casual)" } },
    "kv0484": { korean: "일요일", note: "Sunday. Weekday names are a character plus 요일; 일 here is the sun, not the number one. Days take 에: 일요일에 쉬어요.", example: { ko: "일요일에 집에서 쉬어요.", en: "I rest at home on Sunday.", form: "일요일 + 에 (time particle); 쉬다 → 쉬어요 (present, polite casual)" } },
    "kv0497": { korean: "생일", note: "A birthday. Its honorific for elders is 생신. Congratulating someone uses 축하하다: 생일 축하해요.", example: { ko: "생일이 언제예요?", en: "When is your birthday?", form: "생일 + 이 (subject particle); 언제 + 예요 (present, polite casual, question)" } },
    "kv0505": { korean: "십일월", note: "November — 십일 (11) + 월, formed regularly. Only 유월 and 시월 are irregular.", example: { ko: "십일월에 날씨가 흐려요.", en: "The weather is cloudy in November.", form: "십일월 + 에 (time particle); 흐리다 → 흐려요 (present, polite casual)" } },
    "kv0506": { korean: "빵", note: "Bread, and by extension most bakery items. A bakery is 빵집 or 제과점.", example: { ko: "빵을 먹어요.", en: "I eat bread.", form: "빵 + 을 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0509": { korean: "주", note: "A week. It appears mostly in compounds — 이번 주, 다음 주, 지난 주, 주말 — and as the counter 주일 for a span of weeks: 이 주일.", example: { ko: "다음 주에 시험을 봐요.", en: "I take an exam next week.", form: "다음 + 주 + 에 (time noun plus time particle); 보다 → 봐요 (present, polite casual)" } },
    "kv0516": { korean: "토요일", note: "Saturday. With 일요일 it makes up 주말 (the weekend).", example: { ko: "토요일에 친구를 만나요.", en: "I meet a friend on Saturday.", form: "토요일 + 에 (time particle); 만나다 → 만나요 (present, polite casual)" } },
    "kv0537": { korean: "맥주", note: "Beer. Counted by bottle (병) or glass (잔), and drunk with 마시다.", example: { ko: "맥주 한 잔 주세요.", en: "One glass of beer, please.", form: "한 + 잔 (counter phrase); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0558": { korean: "축하하다", note: "To congratulate. What you congratulate someone for takes 을/를: 생일을 축하해요. The set phrase 생일 축하해요 simply drops the particle.", example: { ko: "생일 축하해요!", en: "Happy birthday!", form: "생일 (particle dropped in the set phrase); 축하하다 → 축하해요 (present, polite casual)" } },
    "kv0564": { korean: "월요일", note: "Monday — 월 here is the moon, the same character as in month names.", example: { ko: "월요일에 수업이 있어요.", en: "I have class on Monday.", form: "월요일 + 에 (time particle); 수업 + 이 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0584": { korean: "월", note: "The counter for months of the calendar, always with Sino-Korean numbers: 일월, 이월, 삼월. For a duration of months use 개월 instead: 삼 개월 동안.", example: { ko: "저는 팔월에 태어났어요.", en: "I was born in August.", form: "팔 + 월 (Sino-Korean number plus counter) + 에 (time particle); 태어나다 → 태어났어요 (past, polite casual)" } },
    "kv0590": { korean: "금요일", note: "Friday — 금 is metal/gold in the classical weekday series.", example: { ko: "금요일에 영화를 봐요.", en: "I watch a movie on Friday.", form: "금요일 + 에 (time particle); 보다 → 봐요 (present, polite casual)" } },
    "kv0593": { korean: "수요일", note: "Wednesday — 수 is water in the weekday series.", example: { ko: "수요일에 운동해요.", en: "I exercise on Wednesday.", form: "수요일 + 에 (time particle); 운동하다 → 운동해요 (present, polite casual)" } },
    "kv0596": { korean: "피자", note: "Pizza. Counted by the whole pie with 판 and by the slice with 조각.", example: { ko: "피자를 먹어요.", en: "I eat pizza.", form: "피자 + 를 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0611": { korean: "목요일", note: "Thursday — 목 is wood in the weekday series.", example: { ko: "목요일에 시간이 있어요?", en: "Do you have time on Thursday?", form: "목요일 + 에 (time particle); 있다 → 있어요 (present, polite casual, question)" } },
    "kv0614": { korean: "수영장", note: "A swimming pool. 장 again marks the place for an activity, as in 운동장 and 주차장.", example: { ko: "수영장에서 수영해요.", en: "I swim at the pool.", form: "수영장 + 에서 (where the action happens); 수영하다 → 수영해요 (present, polite casual)" } },
    "kv0622": { korean: "화요일", note: "Tuesday — 화 is fire in the weekday series.", example: { ko: "화요일에 학교에 가요.", en: "I go to school on Tuesday.", form: "화요일 + 에 (time particle); 가다 → 가요 (present, polite casual)" } },
    "kv0656": { korean: "매점", note: "A snack bar or small shop inside a school, hospital, or station — a kiosk rather than a street shop.", example: { ko: "매점이 어디에 있어요?", en: "Where is the snack bar?", form: "매점 + 이 (subject particle); 있다 → 있어요 (present, polite casual, question)" } },
    "kv0662": { korean: "미역국", note: "Seaweed soup — traditionally eaten on birthdays and by new mothers. Superstition says you avoid it before an exam, since 미끄러지다 ('to slip') means failing.", example: { ko: "생일에 미역국을 먹어요.", en: "I eat seaweed soup on my birthday.", form: "미역국 + 을 (object particle); 먹다 → 먹어요 (present, polite casual — soup is 'eaten', not drunk)" } },
    "kv1027": { korean: "축하", note: "Congratulations as a noun. Used as 축하를 하다 or, far more often, the compound verb 축하하다.", example: { ko: "축하 인사를 해요.", en: "I offer congratulations.", form: "축하 + 인사 (noun compound) + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv1028": { korean: "국수", note: "Noodles in broth. 라면 is instant noodles and 면 is the noodle strand itself; a bowl of 국수 is counted with 그릇.", example: { ko: "점심에 국수를 먹어요.", en: "I eat noodles for lunch.", form: "점심 + 에 (time particle); 국수 + 를 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv1035": { korean: "와인", note: "Wine. Counted by glass (잔) or bottle (병).", example: { ko: "와인을 마셔요.", en: "I drink wine.", form: "와인 + 을 (object particle); 마시다 → 마셔요 (present, polite casual)" } },

    // ------------------------------------------------------------- Bab 9
    "kv0012": { korean: "한", note: "'One' in its counter form — 하나 shortens to 한 whenever a counter follows: 한 개, 한 명, 한 시. Using 하나 개 is the classic beginner slip.", example: { ko: "커피 한 잔 주세요.", en: "One cup of coffee, please.", form: "한 + 잔 (native number in counter form plus counter); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0027": { korean: "두", note: "'Two' before a counter — 둘 shortens to 두: 두 개, 두 사람, 두 시. The bare 둘 is only used when counting aloud or standing alone.", example: { ko: "사과 두 개 주세요.", en: "Two apples, please.", form: "두 + 개 (native number in counter form plus counter); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0048": { korean: "하나", note: "One in the native Korean system — used for counting things, people, and hours. It becomes 한 before a counter, and stands as 하나 only alone: 하나, 둘, 셋.", example: { ko: "하나만 주세요.", en: "Just one, please.", form: "하나 + 만 (particle meaning 'only'); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0052": { korean: "시작하다", note: "To start. It works both ways: 수업이 시작해요 (class starts) and 수업을 시작해요 (I start the class). Its opposite is 끝나다.", example: { ko: "수업이 열 시에 시작해요.", en: "Class starts at ten o'clock.", form: "열 + 시 + 에 (native number, hour counter, time particle); 시작하다 → 시작해요 (present, polite casual)" } },
    "kv0074": { korean: "시", note: "The counter for the hour on a clock, and it takes native Korean numbers: 한 시, 두 시, 세 시. Minutes take Sino-Korean numbers with 분 — so 3:20 is 세 시 이십 분, mixing both systems in one phrase.", example: { ko: "세 시에 만나요.", en: "Let's meet at three o'clock.", form: "세 + 시 (native number plus hour counter) + 에 (time particle); 만나다 → 만나요 (present, polite casual)" } },
    "kv0105": { korean: "분", note: "Two jobs: the counter for minutes, used with Sino-Korean numbers (십 분), and the honorific counter for people (세 분 = three people, respectfully). Same shape, opposite number systems.", example: { ko: "십 분 후에 시작해요.", en: "It starts in ten minutes.", form: "십 + 분 (Sino-Korean number plus minute counter); 시작하다 → 시작해요 (present, polite casual)" } },
    "kv0121": { korean: "끝나다", note: "To end — intransitive, so the thing that ends takes 이/가: 수업이 끝나요. To end something yourself, use 끝내다.", example: { ko: "수업이 끝났어요.", en: "Class has ended.", form: "수업 + 이 (subject particle); 끝나다 → 끝났어요 (past, polite casual)" } },
    "kv0128": { korean: "세", note: "'Three' before a counter — 셋 shortens to 세: 세 개, 세 시, 세 명. Do not confuse it with the age counter 세, which is the formal Sino-Korean one.", example: { ko: "책 세 권 있어요.", en: "I have three books.", form: "세 + 권 (native number in counter form plus the book counter); 있다 → 있어요 (present, polite casual)" } },
    "kv0154": { korean: "둘", note: "Two in the native system, used alone or when counting aloud. Before a counter it becomes 두: 두 개.", example: { ko: "하나, 둘, 셋!", en: "One, two, three!", form: "둘 counting aloud — the bare form, since no counter follows" } },
    "kv0161": { korean: "오후", note: "Afternoon and, on a clock, PM. It goes before the time: 오후 세 시. Its partner is 오전.", example: { ko: "오후 세 시에 만나요.", en: "Let's meet at 3 PM.", form: "오후 + 세 시 (time phrase, no particle between) + 에 (time particle); 만나다 → 만나요 (present, polite casual)" } },
    "kv0435": { korean: "오전", note: "Morning, and AM on a clock: 오전 아홉 시. 아침 is the morning as a part of the day and the word for breakfast; 오전 is the clock half.", example: { ko: "오전 아홉 시에 수업이 있어요.", en: "I have class at 9 AM.", form: "오전 + 아홉 시 (time phrase) + 에 (time particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0445": { korean: "매일", note: "Every day. The 매 prefix builds the whole series: 매주, 매달, 매년. As a time adverb it takes no particle.", example: { ko: "매일 한국어를 공부해요.", en: "I study Korean every day.", form: "매일 used adverbially with no particle; 공부하다 → 공부해요 (present, polite casual)" } },
    "kv0468": { korean: "방학", note: "School holidays — the semester break specifically. Time off work is 휴가, and a trip is 여행, so 방학 only applies to students.", example: { ko: "방학에 여행을 가요.", en: "I travel during the school holidays.", form: "방학 + 에 (time particle); 가다 → 가요 (present, polite casual)" } },
    "kv0513": { korean: "점심", note: "Lunch, and midday. 점심을 먹다 is to eat lunch; the three meals are 아침, 점심, 저녁 — the same words as morning, midday, and evening.", example: { ko: "점심을 먹어요.", en: "I eat lunch.", form: "점심 + 을 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0534": { korean: "셋", note: "Three in the native system, used alone or counting aloud. Before a counter it shortens to 세.", example: { ko: "하나, 둘, 셋!", en: "One, two, three!", form: "셋 counting aloud — the bare form, since no counter follows" } },
    "kv0585": { korean: "넷", note: "Four in the native system. Before a counter it shortens to 네: 네 개, 네 시.", example: { ko: "네 시에 끝나요.", en: "It ends at four o'clock.", form: "넷 → 네 before the counter 시 (hour) + 에 (time particle); 끝나다 → 끝나요 (present, polite casual)" } },
    "kv0589": { korean: "다섯", note: "Five in the native system. Unlike 하나–넷 it keeps its shape before a counter: 다섯 개, 다섯 시.", example: { ko: "다섯 시에 만나요.", en: "Let's meet at five o'clock.", form: "다섯 + 시 (native number plus hour counter) + 에 (time particle); 만나다 → 만나요 (present, polite casual)" } },
    "kv0602": { korean: "열", note: "Ten in the native system — 열 시, 열 개. It is also the noun for a fever (열이 나요), and the stem of 열다 (to open). Three separate words, one shape.", example: { ko: "열 시에 자요.", en: "I sleep at ten o'clock.", form: "열 + 시 (native number plus hour counter) + 에 (time particle); 자다 → 자요 (present, polite casual)" } },
    "kv0606": { korean: "스물", note: "Twenty in the native system — the one used for age with 살. It shortens to 스무 before a counter: 스무 살, never 스물 살.", example: { ko: "저는 스무 살이에요.", en: "I am twenty years old.", form: "스물 → 스무 before the counter 살; 이에요 (present, polite casual)" } },
    "kv0615": { korean: "일본어", note: "The Japanese language — country plus 어, like 한국어 and 중국어. The colloquial alternative is 일본말.", example: { ko: "일본어를 배워요.", en: "I learn Japanese.", form: "일본어 + 를 (object particle); 배우다 → 배워요 (present, polite casual)" } },
    "kv0617": { korean: "아홉", note: "Nine in the native system, used with counters like 시 and 개: 아홉 시.", example: { ko: "아홉 시에 시작해요.", en: "It starts at nine o'clock.", form: "아홉 + 시 (native number plus hour counter) + 에 (time particle); 시작하다 → 시작해요 (present, polite casual)" } },
    "kv0627": { korean: "여섯", note: "Six in the native system: 여섯 시, 여섯 개. Its Sino-Korean counterpart is 육.", example: { ko: "여섯 시에 저녁을 먹어요.", en: "I eat dinner at six o'clock.", form: "여섯 + 시 (native number plus hour counter) + 에 (time particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0629": { korean: "일곱", note: "Seven in the native system: 일곱 시, 일곱 개. Its Sino-Korean counterpart is 칠.", example: { ko: "일곱 시에 일어나요.", en: "I get up at seven o'clock.", form: "일곱 + 시 (native number plus hour counter) + 에 (time particle); 일어나다 → 일어나요 (present, polite casual)" } },
    "kv0630": { korean: "삼십", note: "Thirty in the Sino-Korean system — for minutes, money, and page numbers. The native thirty, 서른, is what you use for age with 살.", example: { ko: "삼십 분 걸려요.", en: "It takes thirty minutes.", form: "삼십 + 분 (Sino-Korean number plus minute counter); 걸리다 → 걸려요 (present, polite casual)" } },
    "kv0631": { korean: "오십", note: "Fifty — 오 (5) + 십 (10). Its native counterpart is 쉰.", example: { ko: "오십 분 후에 끝나요.", en: "It ends in fifty minutes.", form: "오십 + 분 (Sino-Korean number plus minute counter); 끝나다 → 끝나요 (present, polite casual)" } },
    "kv0638": { korean: "여덟", note: "Eight in the native system, pronounced [여덜] — the ㅂ is silent before a consonant: 여덟 시 sounds like [여덜 씨].", example: { ko: "여덟 시에 학교에 가요.", en: "I go to school at eight o'clock.", form: "여덟 + 시 (native number plus hour counter) + 에 (time particle); 가다 → 가요 (present, polite casual)" } },
    "kv0671": { korean: "생일 파티", note: "A birthday party. Korean stacks the nouns with no particle between them, and holding one is 파티를 해요.", example: { ko: "토요일에 생일 파티를 해요.", en: "I'm having a birthday party on Saturday.", form: "생일 + 파티 (noun compound) + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0698": { korean: "이를 닦다", note: "To brush your teeth — literally 'to polish the teeth'. 이 is a tooth (the honorific is 치아), and 닦다 also covers wiping and polishing anything else: 창문을 닦다.", example: { ko: "아침에 이를 닦아요.", en: "I brush my teeth in the morning.", form: "이 + 를 (object particle); 닦다 → 닦아요 (present, polite casual)" } },
    "kv1029": { korean: "설거지", note: "Washing the dishes. It appears almost only as 설거지를 하다 — there is no verb 설거지하다 in careful writing, though people say it.", example: { ko: "저녁 후에 설거지를 해요.", en: "I wash the dishes after dinner.", form: "설거지 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv1030": { korean: "유학생", note: "A student studying abroad — from 유학 (studying overseas) + 학생. Used for foreign students in Korea and Koreans studying abroad alike.", example: { ko: "저는 유학생이에요.", en: "I am an international student.", form: "유학생 + 이에요 (이다 after a batchim; present, polite casual)" } },

    // ------------------------------------------------------------ Bab 10
    "kv0005": { korean: "그", note: "'That' before a noun — the thing near the listener or already mentioned: 그 책. As a pronoun on its own it means 'he', mostly in writing; in speech people say 그 사람 or the person's name.", example: { ko: "그 책이 재미있어요.", en: "That book is interesting.", form: "그 + 책 (determiner before a noun, no particle between); 재미있다 → 재미있어요 (present, polite casual)" } },
    "kv0108": { korean: "아침", note: "Morning, and also breakfast — 아침을 먹어요 means eating breakfast, not eating a morning. Same double duty as 점심 and 저녁.", example: { ko: "아침에 아침을 먹어요.", en: "I eat breakfast in the morning.", form: "아침 + 에 (time particle) and 아침 + 을 (object particle) — the same noun in both roles; 먹다 → 먹어요 (present, polite casual)" } },
    "kv0143": { korean: "바다", note: "The sea. Going there takes 에 and swimming there takes 에서. A lake is 호수 and a river 강.", example: { ko: "여름에 바다에 가요.", en: "I go to the sea in summer.", form: "바다 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv0424": { korean: "그렇지만", note: "'But' or 'however', opening the second sentence. 하지만 is its everyday twin, while -지만 attaches inside a single sentence: 비싸지만 좋아요.", example: { ko: "비싸요. 그렇지만 좋아요.", en: "It is expensive. However, it is good.", form: "그렇지만 opens the second sentence and never conjugates; 좋다 → 좋아요 (present, polite casual)" } },
    "kv0489": { korean: "않다", note: "The long negation. It attaches as -지 않다 to a verb or adjective stem: 가지 않아요, 좋지 않아요. The short negation 안 goes in front of the verb instead and means the same thing, with 안 being more conversational.", example: { ko: "저는 커피를 마시지 않아요.", en: "I do not drink coffee.", form: "마시다 + -지 않다 → 마시지 않아요 (long negation; present, polite casual)" } },
    "kv0494": { korean: "주말", note: "The weekend — Saturday and Sunday. It takes 에: 주말에 쉬어요. Weekdays are 평일.", example: { ko: "주말에 등산을 해요.", en: "I go hiking at the weekend.", form: "주말 + 에 (time particle); 하다 → 해요 (present, polite casual)" } },
    "kv0507": { korean: "어제", note: "Yesterday. Like 오늘 and 내일 it takes no 에, and it normally pairs with a past-tense verb.", example: { ko: "어제 영화를 봤어요.", en: "I watched a movie yesterday.", form: "어제 used adverbially with no particle; 보다 → 봤어요 (past, polite casual)" } },
    "kv0511": { korean: "김치", note: "Kimchi. Making it is 김치를 담그다, a special verb for fermented foods — not 만들다.", example: { ko: "김치가 매워요.", en: "Kimchi is spicy.", form: "김치 + 가 (subject particle); 맵다 → 매워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0528": { korean: "싫어하다", note: "To dislike — an action verb, so the disliked thing takes 을/를: 저는 운동을 싫어해요. Its adjective partner 싫다 puts that thing in 이/가 instead.", example: { ko: "동생은 운동을 싫어해요.", en: "My younger sibling dislikes exercise.", form: "운동 + 을 (object particle); 싫어하다 → 싫어해요 (present, polite casual)" } },
    "kv0618": { korean: "장미", note: "A rose. Flowers are counted with 송이: 장미 한 송이. Giving flowers is 꽃을 주다 or 선물하다.", example: { ko: "장미가 예뻐요.", en: "The rose is pretty.", form: "장미 + 가 (subject particle); 예쁘다 → 예뻐요 (ㅡ-irregular; present, polite casual)" } },
    "kv0719": { korean: "컴퓨터실", note: "A computer lab. The 실 suffix marks a room inside a larger building, as in 교실 and 사무실.", example: { ko: "컴퓨터실에서 공부해요.", en: "I study in the computer lab.", form: "컴퓨터실 + 에서 (where the action happens); 공부하다 → 공부해요 (present, polite casual)" } },
    "kv0721": { korean: "케이팝", note: "K-pop. Music is listened to with 듣다, never 보다 or 읽다: 케이팝을 들어요.", example: { ko: "케이팝을 들어요.", en: "I listen to K-pop.", form: "케이팝 + 을 (object particle); 듣다 → 들어요 (ㄷ-irregular: ㄷ becomes ㄹ before a vowel; present, polite casual)" } },
    "kv0739": { korean: "한국 영화", note: "A Korean film. Two nouns stacked with a space and no particle — the standard way Korean builds this kind of phrase, like 한국 음식 and 한국 사람.", example: { ko: "한국 영화를 좋아해요.", en: "I like Korean films.", form: "한국 + 영화 (noun compound) + 를 (object particle); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "kv0744": { korean: "휴게실", note: "A lounge or break room — 휴게 (rest) + 실 (room). Resting there takes 에서: 휴게실에서 쉬어요.", example: { ko: "휴게실에서 쉬어요.", en: "I rest in the lounge.", form: "휴게실 + 에서 (where the action happens); 쉬다 → 쉬어요 (present, polite casual)" } },
    "kv0993": { korean: "지", note: "A dependent noun counting time since something happened, always in the pattern -(으)ㄴ 지: 한국에 온 지 일 년 됐어요. It cannot stand alone, and it is unrelated to the question ending -지요.", example: { ko: "한국에 온 지 일 년 됐어요.", en: "It has been a year since I came to Korea.", form: "오다 + -(으)ㄴ 지 → 온 지 (time-elapsed pattern); 되다 → 됐어요 (past, polite casual)" } },
    "kv1001": { korean: "드라마", note: "A TV drama or series — the standard word for Korean serials, not just soap operas. Watched with 보다.", example: { ko: "한국 드라마를 봐요.", en: "I watch Korean dramas.", form: "드라마 + 를 (object particle); 보다 → 봐요 (present, polite casual)" } },
    "kv1014": { korean: "매년", note: "Every year. Part of the 매 series with 매일, 매주, 매달, and like them it takes no particle.", example: { ko: "매년 한국에 가요.", en: "I go to Korea every year.", form: "매년 used adverbially with no particle; 가다 → 가요 (present, polite casual)" } },

    // ------------------------------------------------------------ Bab 11
    "kv0002": { korean: "있다", note: "To exist, to be somewhere, or to have. The thing that exists takes 이/가: 책이 있어요 covers both 'there is a book' and 'I have a book'. Its honorific for people is 계시다, and its opposite is 없다.", example: { ko: "가방에 책이 있어요.", en: "There is a book in the bag.", form: "책 + 이 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0021": { korean: "받다", note: "To receive. The giver takes 한테서 or 에게서: 친구한테서 선물을 받았어요. Its counterpart is 주다.", example: { ko: "친구한테서 선물을 받았어요.", en: "I received a present from my friend.", form: "친구 + 한테서 (source particle); 받다 → 받았어요 (past, polite casual)" } },
    "kv0039": { korean: "많이", note: "'A lot' — the adverb form of 많다, placed before the verb: 많이 먹어요. Do not use 많다 itself to modify a verb; the -이 form is what does that job.", example: { ko: "물을 많이 마셔요.", en: "I drink a lot of water.", form: "많이 modifies the verb (adverb form of 많다); 마시다 → 마셔요 (present, polite casual)" } },
    "kv0043": { korean: "어머니", note: "Mother — the respectful, slightly formal word. 엄마 is 'mum' and used at home. Talking about your own mother to others, 어머니 is the safe choice.", example: { ko: "어머니는 선생님이에요.", en: "My mother is a teacher.", form: "어머니 + 는 (topic particle); 이에요 (present, polite casual)" } },
    "kv0044": { korean: "뭐", note: "What — the spoken form of 무엇. It takes particles like any noun: 뭐를 (often shortened to 뭘) 해요? Before a noun use the determiner 무슨 instead.", example: { ko: "뭐 해요?", en: "What are you doing?", form: "뭐 with the object particle dropped, as usual in speech; 하다 → 해요 (present, polite casual, question)" } },
    "kv0046": { korean: "누구", note: "Who. With the subject particle it contracts to 누가, never 누구가: 누가 왔어요? Elsewhere it behaves like a normal noun — 누구를, 누구한테.", example: { ko: "그 사람이 누구예요?", en: "Who is that person?", form: "누구 + 예요 (이다 after a vowel; present, polite casual, question)" } },
    "kv0054": { korean: "그래서", note: "'So' or 'therefore', opening a sentence that gives the result. Inside one sentence the same link is -아서/어서: 비가 와서 안 갔어요.", example: { ko: "비가 와요. 그래서 집에 있어요.", en: "It is raining. So I am staying home.", form: "그래서 opens the second sentence and never conjugates; 있다 → 있어요 (present, polite casual)" } },
    "kv0056": { korean: "돈", note: "Money. Earning is 돈을 벌다 and spending is 돈을 쓰다. The currency is 원.", example: { ko: "돈이 없어요.", en: "I don't have money.", form: "돈 + 이 (subject particle); 없다 → 없어요 (present, polite casual)" } },
    "kv0059": { korean: "모두", note: "All, everyone — it works as an adverb before the verb (모두 왔어요) and as a pronoun on its own (모두가 좋아해요). 다 is its more casual equivalent.", example: { ko: "가족이 모두 다섯 명이에요.", en: "There are five people in my family altogether.", form: "모두 used adverbially; 다섯 + 명 (native number plus the people counter); 이에요 (present, polite casual)" } },
    "kv0061": { korean: "아버지", note: "Father — the respectful word, with 아빠 as the informal 'dad'. Someone else's father is 아버님.", example: { ko: "아버지는 회사원이에요.", en: "My father is an office worker.", form: "아버지 + 는 (topic particle); 이에요 (present, polite casual)" } },
    "kv0082": { korean: "이제", note: "'Now' with the sense of a change — from now on, as opposed to before. 지금 is the neutral clock-time 'now', so 이제 갈게요 means 'I'll be off now (having stayed until now)'.", example: { ko: "이제 집에 가요.", en: "I'm going home now.", form: "이제 used adverbially with no particle; 가다 → 가요 (present, polite casual)" } },
    "kv0085": { korean: "일어나다", note: "To get up — out of bed or from a chair — and also 'to happen' for events. Intransitive, so no 을/를.", example: { ko: "저는 일곱 시에 일어나요.", en: "I get up at seven o'clock.", form: "일곱 시 + 에 (time particle); 일어나다 → 일어나요 (present, polite casual)" } },
    "kv0097": { korean: "아주", note: "Very — placed before an adjective or adverb: 아주 좋아요. 너무 originally meant 'too much' and is now used the same way in casual speech, while 아주 stays neutral.", example: { ko: "한국 음식이 아주 맛있어요.", en: "Korean food is very delicious.", form: "아주 modifies the predicate; 맛있다 → 맛있어요 (present, polite casual)" } },
    "kv0127": { korean: "가족", note: "Family. Counted with 명 for members: 우리 가족은 네 명이에요. Note that Koreans say 우리 가족, not 제 가족.", example: { ko: "우리 가족은 네 명이에요.", en: "There are four people in my family.", form: "가족 + 은 (topic particle); 네 + 명 (native number in counter form plus the people counter); 이에요 (present, polite casual)" } },
    "kv0131": { korean: "나이", note: "Age. Asking politely you say 나이가 어떻게 되세요?; for an elder use the honorific noun 연세. Age itself is counted with 살 and native numbers.", example: { ko: "나이가 어떻게 되세요?", en: "How old are you?", form: "나이 + 가 (subject particle); 되다 + -세요 → 되세요 (honorific present, polite casual, question)" } },
    "kv0141": { korean: "꽃", note: "A flower, pronounced [꼳] alone but [꼬치] before a vowel particle. Counted with 송이, and blooming is 꽃이 피다.", example: { ko: "봄에 꽃이 펴요.", en: "Flowers bloom in spring.", form: "꽃 + 이 (subject particle); 피다 → 펴요 (present, polite casual)" } },
    "kv0145": { korean: "언니", note: "Older sister — but only when the speaker is female. A male speaker says 누나. Korean sibling words depend on the speaker's gender, not just the sibling's.", example: { ko: "언니는 대학생이에요.", en: "My older sister is a university student.", form: "언니 + 는 (topic particle); 이에요 (present, polite casual)" } },
    "kv0150": { korean: "할머니", note: "Grandmother, and also a polite way to address any elderly woman. Verbs about her normally take the honorific -(으)시-: 할머니께서 오세요.", example: { ko: "할머니께서 오세요.", en: "My grandmother is coming.", form: "할머니 + 께서 (honorific subject particle); 오다 + -시- + -어요 → 오세요 (honorific present, polite casual)" } },
    "kv0160": { korean: "동생", note: "A younger sibling of either gender. Specify with 남동생 (younger brother) or 여동생 (younger sister). Unlike the older-sibling words, 동생 does not change with the speaker's gender.", example: { ko: "동생이 두 명 있어요.", en: "I have two younger siblings.", form: "동생 + 이 (subject particle); 두 + 명 (native number in counter form plus the people counter); 있다 → 있어요 (present, polite casual)" } },
    "kv0175": { korean: "할아버지", note: "Grandfather, and a respectful way to address an elderly man. Like 할머니 he takes honorific verb forms.", example: { ko: "할아버지께서 신문을 읽으세요.", en: "My grandfather is reading the newspaper.", form: "할아버지 + 께서 (honorific subject particle); 읽다 + -(으)시- → 읽으세요 (honorific present, polite casual)" } },
    "kv0179": { korean: "형", note: "Older brother — only when the speaker is male. A female speaker says 오빠. It is also used between male friends for a slightly older man.", example: { ko: "형이 대학교에 다녀요.", en: "My older brother attends university.", form: "형 + 이 (subject particle); 다니다 → 다녀요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "kv0189": { korean: "닦다", note: "To wipe, polish, or brush. It covers teeth (이를 닦다), shoes, and windows — anything cleaned by rubbing. Washing with water is 씻다.", example: { ko: "이를 닦아요.", en: "I brush my teeth.", form: "이 + 를 (object particle); 닦다 → 닦아요 (present, polite casual)" } },
    "kv0203": { korean: "씻다", note: "To wash with water — hands, face, fruit. Hair takes 감다, dishes take 설거지를 하다, and clothes take 빨래하다. Korean splits washing by what is being washed.", example: { ko: "손을 씻어요.", en: "I wash my hands.", form: "손 + 을 (object particle); 씻다 → 씻어요 (present, polite casual)" } },
    "kv0211": { korean: "오빠", note: "Older brother — only when the speaker is female. A male speaker says 형. It is also how a woman addresses a slightly older man she is close to.", example: { ko: "오빠가 요리해요.", en: "My older brother cooks.", form: "오빠 + 가 (subject particle); 요리하다 → 요리해요 (present, polite casual)" } },
    "kv0425": { korean: "누나", note: "Older sister — only when the speaker is male. A female speaker says 언니.", example: { ko: "누나가 간호사예요.", en: "My older sister is a nurse.", form: "누나 + 가 (subject particle); 예요 (present, polite casual)" } },
    "kv0428": { korean: "계시다", note: "The honorific of 있다 for people you respect: 할아버지가 집에 계세요. Never use it for objects — a book still 있어요, no matter whose it is.", example: { ko: "할아버지께서 집에 계세요.", en: "My grandfather is at home.", form: "할아버지 + 께서 (honorific subject particle); 계시다 + -어요 → 계세요 (honorific present, polite casual)" } },
    "kv0462": { korean: "드리다", note: "The humble form of 주다 — giving to someone above you: 선생님께 드려요. The recipient takes 께 rather than 한테.", example: { ko: "선생님께 선물을 드려요.", en: "I give a present to my teacher.", form: "선생님 + 께 (honorific recipient particle); 드리다 → 드려요 (humble present, polite casual)" } },
    "kv0490": { korean: "공무원", note: "A civil servant. The 원 suffix marks members of an organisation, as in 회사원 and 은행원.", example: { ko: "아버지는 공무원이에요.", en: "My father is a civil servant.", form: "공무원 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "kv0521": { korean: "치마", note: "A skirt. Worn with 입다 like other body clothing, and counted with 벌.", example: { ko: "치마를 입어요.", en: "I wear a skirt.", form: "치마 + 를 (object particle); 입다 → 입어요 (present, polite casual)" } },
    "kv0581": { korean: "여동생", note: "A younger sister — 여 (female) + 동생. Unlike 언니 and 누나, this word is the same whatever the speaker's gender.", example: { ko: "여동생이 학생이에요.", en: "My younger sister is a student.", form: "여동생 + 이 (subject particle); 이에요 (present, polite casual)" } },
    "kv0599": { korean: "남동생", note: "A younger brother — 남 (male) + 동생, and again independent of the speaker's gender.", example: { ko: "남동생이 축구를 좋아해요.", en: "My younger brother likes soccer.", form: "남동생 + 이 (subject particle); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "kv0619": { korean: "비빔밥", note: "Bibimbap — rice mixed with vegetables, from 비비다 (to mix) + 밥. Counted with 그릇, and you 비벼서 먹어요 (mix it, then eat).", example: { ko: "점심에 비빔밥을 먹어요.", en: "I eat bibimbap for lunch.", form: "비빔밥 + 을 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0650": { korean: "드시다", note: "The honorific of both 먹다 and 마시다: 할머니가 진지를 드세요. Offering food you say 드세요 ('please eat'), never 먹으세요 to someone senior.", example: { ko: "많이 드세요.", en: "Please eat plenty.", form: "드시다 + -어요 → 드세요 (honorific present used as a polite invitation)" } },
    "kv0663": { korean: "미용사", note: "A hairdresser. The 사 suffix again marks a trained professional, and the workplace is 미용실.", example: { ko: "언니는 미용사예요.", en: "My older sister is a hairdresser.", form: "미용사 + 예요 (이다 after a vowel; present, polite casual)" } },
    "kv0713": { korean: "진지", note: "The honorific noun for a meal, replacing 밥 when the eater deserves respect: 할아버지께서 진지를 드세요. It pairs with 드시다, never with 먹다.", example: { ko: "할아버지께서 진지를 드세요.", en: "My grandfather is eating his meal.", form: "진지 + 를 (object particle); 드시다 → 드세요 (honorific present, polite casual)" } },
    "kv1007": { korean: "고모", note: "Your father's sister. Korean splits aunts by side of the family: 고모 is paternal, 이모 maternal. There is no single word for 'aunt'.", example: { ko: "고모가 부산에 살아요.", en: "My paternal aunt lives in Busan.", form: "고모 + 가 (subject particle); 살다 → 살아요 (present, polite casual)" } },
    "kv1010": { korean: "감다", note: "To wash your hair (머리를 감다) and to close your eyes (눈을 감다) — one verb, two fixed pairings. Hair is never 씻다, and eyes are never 닫다.", example: { ko: "머리를 감아요.", en: "I wash my hair.", form: "머리 + 를 (object particle); 감다 → 감아요 (present, polite casual)" } },
    "kv1020": { korean: "이모", note: "Your mother's sister. It is also the friendly way to address a middle-aged woman running a restaurant.", example: { ko: "이모가 요리를 잘해요.", en: "My maternal aunt cooks well.", form: "이모 + 가 (subject particle); 잘하다 → 잘해요 (present, polite casual)" } },
    "kv1021": { korean: "삼촌", note: "Your father's brother — strictly the unmarried one, though it is used loosely. The mother's brother is 외삼촌, where 외 marks the maternal side.", example: { ko: "삼촌이 서울에 살아요.", en: "My uncle lives in Seoul.", form: "삼촌 + 이 (subject particle); 살다 → 살아요 (present, polite casual)" } },
    "kv1025": { korean: "주무시다", note: "The honorific of 자다: 할머니께서 주무세요. The bedtime greeting 안녕히 주무세요 ('sleep well') uses it.", example: { ko: "안녕히 주무세요.", en: "Good night (sleep well).", form: "주무시다 + -어요 → 주무세요 (honorific present used as a polite farewell)" } },
    "kv1031": { korean: "외삼촌", note: "Your mother's brother. The 외 prefix marks the maternal line throughout the family words: 외할머니, 외할아버지, 외삼촌.", example: { ko: "외삼촌이 의사예요.", en: "My maternal uncle is a doctor.", form: "외삼촌 + 이 (subject particle); 예요 (present, polite casual)" } },
    "kv1040": { korean: "생신", note: "The honorific noun for a birthday, used for grandparents, parents, and teachers: 할머니 생신이에요. For friends use 생일.", example: { ko: "오늘은 할머니 생신이에요.", en: "Today is my grandmother's birthday.", form: "할머니 + 생신 (possession by juxtaposition, no particle); 이에요 (present, polite casual)" } },
    "kv1042": { korean: "연세", note: "The honorific noun for age. Asking an elder you say 연세가 어떻게 되세요?, never 나이가 몇 살이에요?", example: { ko: "연세가 어떻게 되세요?", en: "How old are you? (respectful)", form: "연세 + 가 (subject particle); 되다 + -세요 → 되세요 (honorific present, polite casual, question)" } },
    "kv1045": { korean: "성함", note: "The honorific noun for a name. 성함이 어떻게 되세요? is the respectful version of 이름이 뭐예요?", example: { ko: "성함이 어떻게 되세요?", en: "May I ask your name?", form: "성함 + 이 (subject particle); 되다 + -세요 → 되세요 (honorific present, polite casual, question)" } },

    // ------------------------------------------------------------ Bab 12
    "kv0003": { korean: "수", note: "A dependent noun meaning ability or possibility, used only in the pattern -(으)ㄹ 수 있다 / 없다: 갈 수 있어요 (I can go). It never appears alone and takes no particle of its own.", example: { ko: "저는 한국어를 할 수 있어요.", en: "I can speak Korean.", form: "하다 + -(으)ㄹ 수 있다 → 할 수 있어요 (ability pattern; present, polite casual)" } },
    "kv0006": { korean: "없다", note: "To not exist, or to not have — the opposite of 있다, and a single word rather than a negated 있다. The thing missing takes 이/가: 돈이 없어요. Its honorific is 안 계시다.", example: { ko: "시간이 없어요.", en: "I don't have time.", form: "시간 + 이 (subject particle); 없다 → 없어요 (present, polite casual)" } },
    "kv0026": { korean: "만들다", note: "To make. A ㄹ-stem, so the ㄹ drops before ㄴ, ㅂ, ㅅ endings: 만드는, 만듭니다. Food, objects, and plans can all be 만들다, but kimchi takes 담그다.", example: { ko: "케이크를 만들어요.", en: "I make a cake.", form: "케이크 + 를 (object particle); 만들다 → 만들어요 (present, polite casual)" } },
    "kv0037": { korean: "좀", note: "The shortened 조금, with a second life as a softener in requests: 좀 주세요, 좀 도와주세요. Dropping it makes a request sound blunt.", example: { ko: "물 좀 주세요.", en: "Some water, please.", form: "좀 softens the request; 주다 + -세요 → 주세요 (polite request)" } },
    "kv0062": { korean: "왜", note: "Why. It goes before the verb and takes no particle: 왜 안 왔어요? The answer usually comes back with 그래서 or -아서/어서.", example: { ko: "왜 학교에 안 가요?", en: "Why aren't you going to school?", form: "왜 modifies the whole clause, no particle; 안 + 가다 → 안 가요 (short negation; present, polite casual, question)" } },
    "kv0065": { korean: "쓰다", note: "Three verbs share this shape: to write, to use, and to wear on the head (모자를 쓰다) or face (안경을 쓰다). There is also the adjective 쓰다 (to taste bitter). All are ㅡ-irregular: 써요.", example: { ko: "편지를 써요.", en: "I write a letter.", form: "편지 + 를 (object particle); 쓰다 → 써요 (ㅡ-irregular: ㅡ drops before -어요; present, polite casual)" } },
    "kv0080": { korean: "못", note: "'Cannot' — inability, placed directly before the verb: 못 가요. It differs from 안 (choosing not to) — 안 가요 means I'm not going, 못 가요 means I can't. The longer form is -지 못하다.", example: { ko: "저는 수영을 못 해요.", en: "I can't swim.", form: "못 + 하다 → 못 해요 (inability negation; present, polite casual)" } },
    "kv0083": { korean: "물론", note: "'Of course' — usually standing alone as an answer, or opening a sentence. The fuller form 물론이에요 works as a complete reply.", example: { ko: "물론이에요.", en: "Of course.", form: "물론 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "kv0089": { korean: "너무", note: "Originally 'too much', in the sense of excess: 너무 비싸요 (too expensive). In casual speech it has drifted to plain 'very', so 너무 좋아요 is now simply 'I love it'. In writing keep the excess sense.", example: { ko: "이 옷은 너무 비싸요.", en: "These clothes are too expensive.", form: "너무 modifies the predicate; 비싸다 → 비싸요 (present, polite casual)" } },
    "kv0117": { korean: "치다", note: "To hit or strike — and the sports verb for anything struck: 테니스를 치다, 골프를 치다, 피아노를 치다 (the keys are struck too).", example: { ko: "피아노를 쳐요.", en: "I play the piano.", form: "피아노 + 를 (object particle); 치다 → 쳐요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "kv0119": { korean: "술", note: "Alcohol of any kind. Drinking is 술을 마시다, and 술집 is a bar. Note that pouring for someone older is done with two hands.", example: { ko: "저는 술을 안 마셔요.", en: "I don't drink alcohol.", form: "술 + 을 (object particle); 안 + 마시다 → 안 마셔요 (short negation; present, polite casual)" } },
    "kv0126": { korean: "요즘", note: "These days, lately. It covers an ongoing recent stretch, unlike 최근 (a specific recent point) and takes no particle: 요즘 바빠요.", example: { ko: "요즘 아주 바빠요.", en: "I'm very busy these days.", form: "요즘 used adverbially with no particle; 바쁘다 → 바빠요 (ㅡ-irregular; present, polite casual)" } },
    "kv0148": { korean: "기분", note: "Mood or how you feel emotionally. 기분이 좋아요 is 'I'm in a good mood'; physical condition is 몸이 좋다 or 컨디션.", example: { ko: "오늘 기분이 좋아요.", en: "I'm in a good mood today.", form: "기분 + 이 (subject particle); 좋다 → 좋아요 (present, polite casual)" } },
    "kv0156": { korean: "아프다", note: "To hurt or be ill. The body part that hurts is the subject: 머리가 아파요. A ㅡ-irregular, and for someone senior the honorific is 편찮으시다.", example: { ko: "머리가 아파요.", en: "I have a headache.", form: "머리 + 가 (subject particle); 아프다 → 아파요 (ㅡ-irregular; present, polite casual)" } },
    "kv0158": { korean: "고향", note: "Hometown — where you are from, which may not be where you live. 고향이 어디예요? is a standard getting-to-know-you question.", example: { ko: "고향이 어디예요?", en: "Where is your hometown?", form: "고향 + 이 (subject particle); 어디 + 예요 (present, polite casual, question)" } },
    "kv0191": { korean: "바쁘다", note: "To be busy. A ㅡ-irregular: 바빠요. What keeps you busy takes 때문에 or -느라고, not an object particle.", example: { ko: "요즘 바빠요.", en: "I'm busy these days.", form: "바쁘다 → 바빠요 (ㅡ-irregular: ㅡ drops, stem vowel ㅏ takes -아요; present, polite casual)" } },
    "kv0192": { korean: "나쁘다", note: "To be bad — the opposite of 좋다. A ㅡ-irregular: 나빠요. For a person doing wrong, 나쁜 사람 is strong language.", example: { ko: "날씨가 나빠요.", en: "The weather is bad.", form: "나쁘다 → 나빠요 (ㅡ-irregular; present, polite casual)" } },
    "kv0416": { korean: "예쁘다", note: "To be pretty. A ㅡ-irregular: 예뻐요. It describes appearance; for a beautiful scene 아름답다 is the stronger word, and for a man 잘생기다.", example: { ko: "꽃이 예뻐요.", en: "The flower is pretty.", form: "예쁘다 → 예뻐요 (ㅡ-irregular: ㅡ drops, stem vowel ㅕ takes -어요; present, polite casual)" } },
    "kv0437": { korean: "약속", note: "A promise, and also an appointment or plans with someone. 약속이 있어요 means 'I have plans', which is how Koreans decline an invitation.", example: { ko: "오늘 약속이 있어요.", en: "I have plans today.", form: "약속 + 이 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0444": { korean: "내일", note: "Tomorrow. Like 오늘 and 어제 it takes no 에, and it pairs with a present or future form — Korean often uses the plain present for near-future plans.", example: { ko: "내일 시험을 봐요.", en: "I have an exam tomorrow.", form: "내일 used adverbially with no particle; 보다 → 봐요 (present form covering a near-future plan; polite casual)" } },
    "kv0466": { korean: "어서", note: "'Quickly' or 'go ahead' — urging someone on. Its most common home is the shop greeting 어서 오세요 ('welcome, come in').", example: { ko: "어서 오세요.", en: "Welcome (please come in).", form: "어서 modifies the verb; 오다 + -세요 → 오세요 (honorific request, polite casual)" } },
    "kv0514": { korean: "슬프다", note: "To be sad. A ㅡ-irregular: 슬퍼요. It describes the feeling; making someone sad is 슬프게 하다.", example: { ko: "그 영화가 슬퍼요.", en: "That movie is sad.", form: "슬프다 → 슬퍼요 (ㅡ-irregular; present, polite casual)" } },
    "kv0529": { korean: "피곤하다", note: "To be tired. A 하다 adjective: 피곤해요. For being sleepy specifically use 졸리다.", example: { ko: "오늘 아주 피곤해요.", en: "I'm very tired today.", form: "피곤하다 → 피곤해요 (하다 contracts to 해요; present, polite casual)" } },
    "kv0548": { korean: "운전", note: "Driving. The verb is 운전하다, and a driver is 운전사 or 기사. The car being driven takes 을/를: 차를 운전해요.", example: { ko: "운전을 배워요.", en: "I'm learning to drive.", form: "운전 + 을 (object particle); 배우다 → 배워요 (present, polite casual)" } },
    "kv0557": { korean: "피아노", note: "A piano. Played with 치다 — keys are struck — while wind instruments take 불다 and string instruments 켜다.", example: { ko: "피아노를 칠 수 있어요.", en: "I can play the piano.", form: "치다 + -(으)ㄹ 수 있다 → 칠 수 있어요 (ability pattern; present, polite casual)" } },
    "kv0567": { korean: "외국어", note: "A foreign language — 외국 (foreign country) + 어 (language). A foreigner is 외국인 or 외국 사람.", example: { ko: "외국어를 할 수 있어요?", en: "Can you speak a foreign language?", form: "외국어 + 를 (object particle); 하다 + -(으)ㄹ 수 있다 → 할 수 있어요 (ability pattern; question)" } },
    "kv0576": { korean: "고프다", note: "Hungry — but it never stands alone: the fixed phrase is 배가 고프다, literally 'the stomach is hungry'. A ㅡ-irregular: 배가 고파요. Full is 배가 부르다.", example: { ko: "배가 고파요.", en: "I'm hungry.", form: "배 + 가 (subject particle — the stomach is the subject); 고프다 → 고파요 (ㅡ-irregular; present, polite casual)" } },
    "kv0594": { korean: "운전하다", note: "To drive. The vehicle takes 을/를: 차를 운전해요. The road travelled takes 로/으로.", example: { ko: "저는 차를 운전해요.", en: "I drive a car.", form: "차 + 를 (object particle); 운전하다 → 운전해요 (present, polite casual)" } },
    "kv0605": { korean: "배구", note: "Volleyball. A body sport, so it takes 하다: 배구를 해요.", example: { ko: "친구들하고 배구를 해요.", en: "I play volleyball with friends.", form: "배구 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0668": { korean: "부산", note: "Busan, Korea's second city and main port, on the southeast coast. Place names take 에 for destination and 에서 for where an action happens.", example: { ko: "부산에 가고 싶어요.", en: "I want to go to Busan.", form: "부산 + 에 (destination particle); 가다 + -고 싶다 → 가고 싶어요 (desire pattern; present, polite casual)" } },
    "kv0720": { korean: "케이크", note: "Cake. Counted whole with 개 and by the slice with 조각. Birthday cake is 생일 케이크.", example: { ko: "생일에 케이크를 먹어요.", en: "I eat cake on my birthday.", form: "케이크 + 를 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0728": { korean: "프랑스어", note: "The French language — country plus 어, the same pattern as 한국어 and 일본어.", example: { ko: "프랑스어를 배워요.", en: "I learn French.", form: "프랑스어 + 를 (object particle); 배우다 → 배워요 (present, polite casual)" } },
    "kv1005": { korean: "기쁘다", note: "To be glad or delighted. A ㅡ-irregular: 기뻐요. 행복하다 is the deeper 'happy', while 기쁘다 is the reaction to a specific piece of good news.", example: { ko: "만나서 기뻐요.", en: "I'm glad to meet you.", form: "만나다 + -아서 → 만나서 (reason link); 기쁘다 → 기뻐요 (ㅡ-irregular; present, polite casual)" } },

    // ------------------------------------------------------------ Bab 13
    "kv0042": { korean: "나다", note: "A verb of something coming out or arising: 열이 나다 (run a fever), 소리가 나다 (make a sound), 화가 나다 (get angry). 'To be born' is the compound 태어나다.", example: { ko: "열이 나요.", en: "I have a fever.", form: "열 + 이 (subject particle — the fever is what arises); 나다 → 나요 (present, polite casual)" } },
    "kv0096": { korean: "보내다", note: "To send — letters, emails, people — and also to spend time: 주말을 잘 보냈어요. The recipient takes 한테 or 에게.", example: { ko: "친구한테 이메일을 보내요.", en: "I send an email to my friend.", form: "친구 + 한테 (recipient particle); 보내다 → 보내요 (present, polite casual)" } },
    "kv0109": { korean: "아름답다", note: "Beautiful — scenery, music, a moment. Stronger and more literary than 예쁘다, which is about looks. A ㅂ-irregular: 아름다워요.", example: { ko: "경치가 아름다워요.", en: "The scenery is beautiful.", form: "경치 + 가 (subject particle); 아름답다 → 아름다워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0146": { korean: "불", note: "Fire, and also a light or lamp: 불을 켜다 (turn the light on), 불을 끄다 (turn it off). Note the homophone 불 in 불고기 and the unrelated verb 불다 (to blow).", example: { ko: "불을 켜요.", en: "I turn on the light.", form: "불 + 을 (object particle); 켜다 → 켜요 (present, polite casual)" } },
    "kv0149": { korean: "옷", note: "Clothes — always this one word, singular in form. Counted with 벌, worn with 입다, and bought at a 옷 가게.", example: { ko: "옷을 사요.", en: "I buy clothes.", form: "옷 + 을 (object particle); 사다 → 사요 (present, polite casual)" } },
    "kv0155": { korean: "살", note: "The counter for years of age, used with native Korean numbers: 스무 살, 서른 살. The formal Sino-Korean equivalent is 세 (삼십 세), used on documents. Note the homonyms 살 (flesh) and 살다 (to live).", example: { ko: "저는 스무 살이에요.", en: "I am twenty years old.", form: "스물 → 스무 + 살 (native number plus the age counter); 이에요 (present, polite casual)" } },
    "kv0162": { korean: "달", note: "A month as a span of time, and also the moon. Counted with native numbers: 한 달, 두 달. Calendar months use 월 with Sino-Korean numbers instead — 삼월 is March, 세 달 is three months.", example: { ko: "한국에서 세 달 살았어요.", en: "I lived in Korea for three months.", form: "세 + 달 (native number plus the month-span counter); 살다 → 살았어요 (past, polite casual)" } },
    "kv0204": { korean: "편지", note: "A letter. Written with 쓰다 and sent with 보내다 or 부치다; the recipient takes 한테 or 에게.", example: { ko: "부모님께 편지를 써요.", en: "I write a letter to my parents.", form: "부모님 + 께 (honorific recipient particle); 쓰다 → 써요 (ㅡ-irregular; present, polite casual)" } },
    "kv0208": { korean: "여행", note: "A trip. The verb is 여행하다 or 여행을 가다; the destination takes 에 or 로/으로: 부산에 여행을 가요.", example: { ko: "여름에 여행을 가요.", en: "I take a trip in summer.", form: "여행 + 을 (object particle); 가다 → 가요 (present, polite casual)" } },
    "kv0427": { korean: "부모님", note: "Parents. The 님 is built in, so the word is already respectful — 부모 alone sounds clinical. Verbs about them take honorific forms and the particle 께.", example: { ko: "부모님께서 한국에 계세요.", en: "My parents are in Korea.", form: "부모님 + 께서 (honorific subject particle); 계시다 → 계세요 (honorific present, polite casual)" } },
    "kv0480": { korean: "선물", note: "A gift. Giving is 선물을 주다 or the verb 선물하다; receiving is 선물을 받다. To someone senior, use 드리다 instead of 주다.", example: { ko: "친구한테 선물을 줘요.", en: "I give a present to my friend.", form: "친구 + 한테 (recipient particle); 주다 → 줘요 (ㅜ + 어 contracts to 워; present, polite casual)" } },
    "kv0495": { korean: "내년", note: "Next year. The set is 작년 (last year), 올해 (this year), 내년 — note that 'this year' breaks the pattern with a native word.", example: { ko: "내년에 한국에 갈 거예요.", en: "I will go to Korea next year.", form: "내년 + 에 (time particle); 가다 + -(으)ㄹ 거예요 → 갈 거예요 (future, polite casual)" } },
    "kv0648": { korean: "다음 주", note: "Next week — 다음 plus 주, written with a space and no particle between them. Its partners are 이번 주 and 지난주 (which is written as one word).", example: { ko: "다음 주에 시험이 있어요.", en: "There is an exam next week.", form: "다음 주 + 에 (time particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0657": { korean: "머리를 감다", note: "To wash your hair. Hair takes the special verb 감다, never 씻다 — 씻다 is for hands, face, and objects. 머리 also means 'head', so context does the work.", example: { ko: "아침에 머리를 감아요.", en: "I wash my hair in the morning.", form: "머리 + 를 (object particle); 감다 → 감아요 (present, polite casual)" } },
    "kv0670": { korean: "산책하다", note: "To take a walk, for pleasure. Walking as movement is 걷다, so a stroll in the park is 산책해요 but walking to school is 걸어서 가요.", example: { ko: "공원에서 산책해요.", en: "I take a walk in the park.", form: "공원 + 에서 (where the action happens); 산책하다 → 산책해요 (present, polite casual)" } },
    "kv0673": { korean: "서울", note: "Seoul, the capital. One of the few Korean place names that is native rather than Sino-Korean, which is why it has no Chinese-character spelling.", example: { ko: "서울에서 살아요.", en: "I live in Seoul.", form: "서울 + 에서 (where the action happens — 살다 takes 에서 or 에); 살다 → 살아요 (present, polite casual)" } },
    "kv0699": { korean: "이메일", note: "Email. Sent with 보내다 and received with 받다; 메일 alone is just as common.", example: { ko: "이메일을 보냈어요.", en: "I sent an email.", form: "이메일 + 을 (object particle); 보내다 → 보냈어요 (past, polite casual)" } },
    "kv0700": { korean: "이번 달", note: "This month — 이번 plus 달, the time-span word. Compare 이번 주 (this week) and 이번 주말 (this weekend).", example: { ko: "이번 달에 바빠요.", en: "I'm busy this month.", form: "이번 달 + 에 (time particle); 바쁘다 → 바빠요 (ㅡ-irregular; present, polite casual)" } },
    "kv0990": { korean: "줄", note: "A dependent noun for knowing how to do something, in the pattern -(으)ㄹ 줄 알다/모르다: 수영할 줄 알아요 (I know how to swim). Distinct from -(으)ㄹ 수 있다, which is about being able to right now. Also a separate noun meaning a line or rope.", example: { ko: "저는 수영할 줄 알아요.", en: "I know how to swim.", form: "수영하다 + -(으)ㄹ 줄 알다 → 수영할 줄 알아요 (know-how pattern; present, polite casual)" } },
    "kv0998": { korean: "놀이", note: "Play or a game — the noun form of 놀다. It mostly lives in compounds: 놀이공원, 놀이터 (playground), 물놀이.", example: { ko: "아이들이 놀이를 해요.", en: "The children play a game.", form: "놀이 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv1016": { korean: "구경하다", note: "To look around, sightsee, or browse — watching for enjoyment without buying or joining in. Shop assistants expect 구경하고 있어요 ('just looking').", example: { ko: "시장을 구경해요.", en: "I look around the market.", form: "시장 + 을 (object particle); 구경하다 → 구경해요 (present, polite casual)" } },

    // ------------------------------------------------------------ Bab 14
    "kv0129": { korean: "차", note: "Tea, and also a car — two words in one shape (녹차 vs 차를 타다). Tea is counted by the cup with 잔 and drunk with 마시다.", example: { ko: "차를 마셔요.", en: "I drink tea.", form: "차 + 를 (object particle); 마시다 → 마셔요 (present, polite casual)" } },
    "kv0471": { korean: "숙제", note: "Homework. You 'do' it with 하다: 숙제를 해요. Turning it in is 숙제를 내다.", example: { ko: "숙제를 해요.", en: "I do my homework.", form: "숙제 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0525": { korean: "잠깐", note: "'For a moment' — a short pause. As an interjection 잠깐만요 means 'hold on a second'. 잠시 is its more formal twin.", example: { ko: "잠깐 쉴까요?", en: "Shall we rest for a moment?", form: "잠깐 modifies the verb; 쉬다 + -(으)ㄹ까요 → 쉴까요 (suggestion, polite casual)" } },
    "kv0706": { korean: "제주도", note: "Jeju Island, off the south coast — Korea's main holiday destination. The 도 suffix means island, as in 울릉도.", example: { ko: "제주도에 가고 싶어요.", en: "I want to go to Jeju Island.", form: "제주도 + 에 (destination particle); 가다 + -고 싶다 → 가고 싶어요 (desire pattern; present, polite casual)" } },
    "kv0740": { korean: "한국 요리", note: "Korean cuisine. Two nouns with a space between and no particle — 한국 음식 means the same thing, with 요리 leaning towards prepared dishes.", example: { ko: "한국 요리를 만들어요.", en: "I make Korean food.", form: "한국 + 요리 (noun compound) + 를 (object particle); 만들다 → 만들어요 (present, polite casual)" } },
    "kv0741": { korean: "한라산", note: "Hallasan, the volcano at the centre of Jeju Island and the highest mountain in South Korea. Mountain names attach 산 directly with no space.", example: { ko: "한라산에 올라가요.", en: "I climb Hallasan.", form: "한라산 + 에 (destination particle); 올라가다 → 올라가요 (present, polite casual)" } },

    // ------------------------------------------------------------ Bab 15
    "kv0030": { korean: "원", note: "The won, Korea's currency, counted with Sino-Korean numbers: 오천 원, 만 원. Prices are grouped in units of 만 (10,000), so 30,000 is 삼만 원.", example: { ko: "이 책은 만 원이에요.", en: "This book is ten thousand won.", form: "만 + 원 (Sino-Korean number plus currency counter); 이에요 (present, polite casual)" } },
    "kv0041": { korean: "주다", note: "To give. The recipient takes 한테 or 에게; for someone senior, switch the whole verb to 드리다. Attached to another verb as -아/어 주다 it means doing something for someone: 도와주다.", example: { ko: "친구한테 책을 줘요.", en: "I give a book to my friend.", form: "친구 + 한테 (recipient particle); 주다 → 줘요 (ㅜ + 어 contracts to 워; present, polite casual)" } },
    "kv0058": { korean: "여기", note: "Here. The set is 여기 (here), 거기 (there, near you), 저기 (over there). 여기요! is also how you call a waiter.", example: { ko: "여기에서 기다려요.", en: "I wait here.", form: "여기 + 에서 (where the action happens); 기다리다 → 기다려요 (present, polite casual)" } },
    "kv0138": { korean: "그럼", note: "'Then' or 'in that case', opening a reply that follows from what was just said. It is the shortened 그러면, and doubles as 'of course' in answers.", example: { ko: "그럼 내일 만나요.", en: "Then let's meet tomorrow.", form: "그럼 opens the sentence and never conjugates; 만나다 → 만나요 (present used as a suggestion; polite casual)" } },
    "kv0153": { korean: "빨리", note: "Quickly — the adverb of 빠르다. It urges action: 빨리 오세요. The famous 빨리빨리 doubles it for emphasis. Its opposite is 천천히.", example: { ko: "빨리 오세요.", en: "Please come quickly.", form: "빨리 modifies the verb; 오다 + -세요 → 오세요 (honorific request, polite casual)" } },
    "kv0171": { korean: "열심히", note: "'Hard' or 'diligently' — the standard adverb for effort: 열심히 공부해요. Note the -히 ending shared by 조용히 and 안녕히.", example: { ko: "열심히 공부해요.", en: "I study hard.", form: "열심히 modifies the verb (-히 adverb); 공부하다 → 공부해요 (present, polite casual)" } },
    "kv0181": { korean: "버스", note: "A bus. Vehicles are boarded with 타다 and the vehicle takes 을/를: 버스를 타요. Getting off is 내리다 with 에서.", example: { ko: "버스를 타요.", en: "I take the bus.", form: "버스 + 를 (object particle); 타다 → 타요 (present, polite casual)" } },
    "kv0194": { korean: "잔", note: "The counter for cups and glasses of a drink: 커피 한 잔, 물 두 잔. It counts servings, not the physical cup — that is 컵.", example: { ko: "커피 두 잔 주세요.", en: "Two cups of coffee, please.", form: "두 + 잔 (native number in counter form plus the cup counter); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0200": { korean: "장", note: "The counter for flat things: sheets of paper, tickets, photos, pizza slices. 종이 한 장, 표 두 장.", example: { ko: "종이 한 장 주세요.", en: "One sheet of paper, please.", form: "한 + 장 (native number plus the flat-object counter); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0429": { korean: "마리", note: "The counter for animals of any size: 개 한 마리, 고양이 두 마리, 물고기 세 마리. People take 명 and never 마리.", example: { ko: "고양이 두 마리가 있어요.", en: "There are two cats.", form: "두 + 마리 (native number plus the animal counter) + 가 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0449": { korean: "병", note: "Two words in one shape: an illness (병에 걸리다 = to fall ill) and the counter for bottles (맥주 한 병). The counter sense is the one that follows a number.", example: { ko: "물 한 병 주세요.", en: "One bottle of water, please.", form: "한 + 병 (native number plus the bottle counter); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0459": { korean: "종이", note: "Paper. Counted with 장 for sheets. Do not confuse it with 공책 (a notebook) or 서류 (documents).", example: { ko: "종이에 이름을 써요.", en: "I write my name on the paper.", form: "종이 + 에 (surface particle); 쓰다 → 써요 (ㅡ-irregular; present, polite casual)" } },
    "kv0476": { korean: "권", note: "The counter for books and bound volumes: 책 한 권, 만화책 세 권. Magazines and notebooks use it too.", example: { ko: "책 세 권을 샀어요.", en: "I bought three books.", form: "세 + 권 (native number plus the book counter) + 을 (object particle); 사다 → 샀어요 (past, polite casual)" } },
    "kv0481": { korean: "아주머니", note: "A polite way to address a middle-aged woman you don't know — a shopkeeper, a restaurant owner. 아줌마 is its casual, and sometimes rude, short form. The male equivalent is 아저씨.", example: { ko: "아주머니, 이거 얼마예요?", en: "Ma'am, how much is this?", form: "아주머니 used as direct address, no particle; 얼마 + 예요 (present, polite casual, question)" } },
    "kv0500": { korean: "고양이", note: "A cat. Counted with 마리, and its cry is 야옹.", example: { ko: "고양이가 귀여워요.", en: "The cat is cute.", form: "고양이 + 가 (subject particle); 귀엽다 → 귀여워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0517": { korean: "백", note: "A hundred, Sino-Korean. Note that Korean says 백 rather than 일백 for exactly 100, but 이백, 삼백 for the rest. The homonym 백 also means bag.", example: { ko: "백 명이 왔어요.", en: "A hundred people came.", form: "백 + 명 (Sino-Korean number plus the people counter) + 이 (subject particle); 오다 → 왔어요 (past, polite casual)" } },
    "kv0535": { korean: "생선", note: "Fish as food — the kind you buy and cook. A living fish is 물고기. Counted with 마리 either way.", example: { ko: "생선을 구워요.", en: "I grill the fish.", form: "생선 + 을 (object particle); 굽다 → 구워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0604": { korean: "마흔", note: "Forty in the native system — the one used for age with 살: 마흔 살. Its Sino-Korean counterpart 사십 handles minutes and money.", example: { ko: "아버지는 마흔 살이에요.", en: "My father is forty years old.", form: "마흔 + 살 (native number plus the age counter); 이에요 (present, polite casual)" } },
    "kv0616": { korean: "서른", note: "Thirty in the native system, used for age: 서른 살. The Sino-Korean 삼십 covers everything else.", example: { ko: "저는 서른 살이에요.", en: "I am thirty years old.", form: "서른 + 살 (native number plus the age counter); 이에요 (present, polite casual)" } },
    "kv0620": { korean: "여든", note: "Eighty in the native system, used for age: 여든 살. Sino-Korean 팔십 covers other counting.", example: { ko: "할아버지는 여든 살이에요.", en: "My grandfather is eighty years old.", form: "여든 + 살 (native number plus the age counter); 이에요 (present, polite casual)" } },
    "kv0621": { korean: "일흔", note: "Seventy in the native system, used for age: 일흔 살. Its Sino-Korean partner is 칠십.", example: { ko: "할머니는 일흔 살이에요.", en: "My grandmother is seventy years old.", form: "일흔 + 살 (native number plus the age counter); 이에요 (present, polite casual)" } },
    "kv0634": { korean: "예순", note: "Sixty in the native system, used for age: 예순 살. Sino-Korean 육십 is used elsewhere.", example: { ko: "예순 살이 되셨어요.", en: "He/she turned sixty.", form: "예순 + 살 (native number plus the age counter) + 이 (subject particle); 되다 + -시- → 되셨어요 (honorific past, polite casual)" } },
    "kv0637": { korean: "쉰", note: "Fifty in the native system, used for age: 쉰 살. Careful with the look-alike 쉬다 (to rest) — 쉰 is also its noun-modifying form.", example: { ko: "어머니는 쉰 살이에요.", en: "My mother is fifty years old.", form: "쉰 + 살 (native number plus the age counter); 이에요 (present, polite casual)" } },
    "kv0639": { korean: "아흔", note: "Ninety in the native system, used for age: 아흔 살. Native numbers stop at 아흔아홉 (99) — a hundred is only 백.", example: { ko: "아흔 살까지 살고 싶어요.", en: "I want to live to ninety.", form: "아흔 + 살 (native number plus the age counter) + 까지 (limit particle); 살다 + -고 싶다 → 살고 싶어요 (desire pattern)" } },
    "kv0646": { korean: "그루", note: "The counter for trees and standing plants: 나무 한 그루, 소나무 세 그루. Flowers take 송이 instead.", example: { ko: "나무 두 그루가 있어요.", en: "There are two trees.", form: "두 + 그루 (native number plus the tree counter) + 가 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0665": { korean: "벌", note: "The counter for sets of clothing: 옷 한 벌, 바지 두 벌. A 벌 is the whole garment or outfit, not a piece of fabric. The homonym 벌 also means a bee or a punishment.", example: { ko: "옷 한 벌을 샀어요.", en: "I bought a set of clothes.", form: "한 + 벌 (native number plus the clothing counter) + 을 (object particle); 사다 → 샀어요 (past, polite casual)" } },
    "kv0722": { korean: "켤레", note: "The counter for pairs — shoes, socks, gloves: 신발 한 켤레, 양말 두 켤레. Anything that comes in twos worn on the body.", example: { ko: "신발 한 켤레를 샀어요.", en: "I bought a pair of shoes.", form: "한 + 켤레 (native number plus the pair counter) + 를 (object particle); 사다 → 샀어요 (past, polite casual)" } },
    "kv0726": { korean: "판", note: "The counter for whole flat rounds — a pizza, a board game, a round of a match: 피자 한 판. Individual slices take 조각.", example: { ko: "피자 한 판을 시켰어요.", en: "I ordered a whole pizza.", form: "한 + 판 (native number plus the round counter) + 을 (object particle); 시키다 → 시켰어요 (past, polite casual)" } },
    "kv0729": { korean: "한 권", note: "'One volume' — 한 (one) plus the book counter 권. Korean counter phrases go noun + number + counter: 책 한 권, with no particle between the number and the counter.", example: { ko: "책 한 권을 읽었어요.", en: "I read one book.", form: "책 + 한 권 (noun, then number plus counter) + 을 (object particle); 읽다 → 읽었어요 (past, polite casual)" } },
    "kv0730": { korean: "한 그루", note: "'One tree' — 한 plus the plant counter 그루. Used for anything rooted and standing.", example: { ko: "정원에 나무 한 그루가 있어요.", en: "There is one tree in the garden.", form: "나무 + 한 그루 (noun, then number plus counter) + 가 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0731": { korean: "한 마리", note: "'One animal' — 한 plus 마리, which counts every animal from a fish to an elephant. Never used for people.", example: { ko: "개 한 마리를 키워요.", en: "I keep one dog.", form: "개 + 한 마리 (noun, then number plus counter) + 를 (object particle); 키우다 → 키워요 (present, polite casual)" } },
    "kv0732": { korean: "한 벌", note: "'One set of clothes' — 한 plus 벌. A suit, a dress, or a pair of trousers each count as 한 벌.", example: { ko: "옷 한 벌이 필요해요.", en: "I need one outfit.", form: "옷 + 한 벌 (noun, then number plus counter) + 이 (subject particle); 필요하다 → 필요해요 (present, polite casual)" } },
    "kv0733": { korean: "한 병", note: "'One bottle' — 한 plus 병. Used for drinks sold by the bottle: 맥주 한 병, 물 한 병.", example: { ko: "맥주 한 병 주세요.", en: "One bottle of beer, please.", form: "맥주 + 한 병 (noun, then number plus counter); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0734": { korean: "한 잔", note: "'One cup/glass' — 한 plus 잔. Counts the serving: 커피 한 잔, 물 한 잔, 술 한 잔.", example: { ko: "커피 한 잔 마셔요.", en: "I drink one cup of coffee.", form: "커피 + 한 잔 (noun, then number plus counter, particle usually dropped); 마시다 → 마셔요 (present, polite casual)" } },
    "kv0735": { korean: "한 장", note: "'One sheet' — 한 plus 장, for flat things: paper, tickets, photos, cards.", example: { ko: "표 한 장 주세요.", en: "One ticket, please.", form: "표 + 한 장 (noun, then number plus counter); 주다 + -세요 → 주세요 (polite request)" } },
    "kv0736": { korean: "한 켤레", note: "'One pair' — 한 plus 켤레, for shoes, socks, and gloves.", example: { ko: "양말 한 켤레를 사요.", en: "I buy one pair of socks.", form: "양말 + 한 켤레 (noun, then number plus counter) + 를 (object particle); 사다 → 사요 (present, polite casual)" } },
    "kv0737": { korean: "한 판", note: "'One whole round' — 한 plus 판, for a whole pizza or one round of a game.", example: { ko: "피자 한 판을 먹었어요.", en: "I ate a whole pizza.", form: "피자 + 한 판 (noun, then number plus counter) + 을 (object particle); 먹다 → 먹었어요 (past, polite casual)" } },
    "kv0994": { korean: "사고", note: "An accident. You 'meet' one in Korean: 사고가 나다 or 사고를 당하다. Note the homograph 사고 meaning thought (사고방식).", example: { ko: "교통사고가 났어요.", en: "There was a traffic accident.", form: "사고 + 가 (subject particle); 나다 → 났어요 (past, polite casual — accidents 'arise')" } },
    "kv0995": { korean: "가격", note: "Price — the formal word used on labels and in writing. In conversation people ask 얼마예요? instead, and 값 is the everyday noun.", example: { ko: "가격이 비싸요.", en: "The price is high.", form: "가격 + 이 (subject particle); 비싸다 → 비싸요 (present, polite casual)" } },
    "kv1002": { korean: "길이", note: "Length — the noun form of 길다, built with the -이 suffix that also gives 높이 (height) and 깊이 (depth). Do not confuse it with 길 (a road) plus the subject particle.", example: { ko: "길이가 짧아요.", en: "The length is short.", form: "길이 + 가 (subject particle); 짧다 → 짧아요 (present, polite casual)" } },
    "kv1008": { korean: "조용히", note: "Quietly — the adverb of 조용하다, with the same -히 ending as 열심히 and 안녕히. 'Be quiet' as a request is 조용히 하세요.", example: { ko: "도서관에서 조용히 해요.", en: "I stay quiet in the library.", form: "조용히 modifies the verb (-히 adverb); 하다 → 해요 (present, polite casual)" } },

    // ------------------------------------------------------------ Bab 16
    "kv0034": { korean: "개", note: "A dog — and, in a different word with the same shape, the general-purpose counter for objects: 사과 두 개. When a number stands in front, it is the counter; when a particle follows, it is the animal.", example: { ko: "개 한 마리를 키워요.", en: "I keep one dog.", form: "개 + 한 마리 (the animal, counted with 마리) + 를 (object particle); 키우다 → 키워요 (present, polite casual)" } },
    "kv0040": { korean: "시간", note: "Time in general (시간이 없어요) and the counter for hours of duration: 두 시간 = two hours. Keep it apart from 시, which marks the hour on the clock — 두 시 is 2 o'clock, 두 시간 is two hours long.", example: { ko: "두 시간 걸려요.", en: "It takes two hours.", form: "두 + 시간 (native number plus the duration counter); 걸리다 → 걸려요 (present, polite casual)" } },
    "kv0100": { korean: "얼마나", note: "'How much' or 'how long' — placed before an adjective or verb: 얼마나 걸려요?, 얼마나 멀어요? Asking a price uses the plain 얼마 instead: 얼마예요?", example: { ko: "얼마나 걸려요?", en: "How long does it take?", form: "얼마나 modifies the predicate; 걸리다 → 걸려요 (present, polite casual, question)" } },
    "kv0430": { korean: "비행기", note: "An airplane. Boarded with 타다 like any vehicle, and the airport is 공항.", example: { ko: "비행기를 타요.", en: "I take the plane.", form: "비행기 + 를 (object particle); 타다 → 타요 (present, polite casual)" } },
    "kv0438": { korean: "자전거", note: "A bicycle. Riding it is 자전거를 타다 — the same 타다 as for buses and planes.", example: { ko: "자전거를 타고 학교에 가요.", en: "I go to school by bicycle.", form: "타다 + -고 → 타고 (sequential link, 'having boarded'); 가다 → 가요 (present, polite casual)" } },
    "kv0482": { korean: "지하철", note: "The subway, literally 'underground iron'. Boarded with 타다, and the station is 역.", example: { ko: "지하철을 타요.", en: "I take the subway.", form: "지하철 + 을 (object particle); 타다 → 타요 (present, polite casual)" } },
    "kv0487": { korean: "택시", note: "A taxi. Hailing one is 택시를 잡다 and riding it is 택시를 타다.", example: { ko: "택시를 타고 가요.", en: "I go by taxi.", form: "타다 + -고 → 타고 (sequential link); 가다 → 가요 (present, polite casual)" } },
    "kv0519": { korean: "공항", note: "An airport. Going there takes 에 and meeting someone there takes 에서.", example: { ko: "공항에서 친구를 기다려요.", en: "I wait for a friend at the airport.", form: "공항 + 에서 (where the action happens); 기다리다 → 기다려요 (present, polite casual)" } },
    "kv0539": { korean: "기차", note: "A train — the long-distance kind. The high-speed service is KTX and the subway is 지하철. Boarded with 타다.", example: { ko: "기차로 부산에 가요.", en: "I go to Busan by train.", form: "기차 + 로 (means-of-transport particle after a vowel); 가다 → 가요 (present, polite casual)" } },
    "kv0551": { korean: "역", note: "A train or subway station: 서울역, 강남역. A bus stop is 정류장 and a bus terminal is 터미널.", example: { ko: "역에서 만나요.", en: "Let's meet at the station.", form: "역 + 에서 (where the action happens); 만나다 → 만나요 (present used as a suggestion; polite casual)" } },
    "kv0562": { korean: "시끄럽다", note: "Noisy. A ㅂ-irregular: 시끄러워요. Its opposite is 조용하다, and '(be) quiet!' as a command is 조용히 해요.", example: { ko: "교실이 시끄러워요.", en: "The classroom is noisy.", form: "교실 + 이 (subject particle); 시끄럽다 → 시끄러워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0579": { korean: "정류장", note: "A bus stop — 버스 정류장 in full. Again the 장 suffix for a designated place.", example: { ko: "정류장에서 버스를 기다려요.", en: "I wait for the bus at the stop.", form: "정류장 + 에서 (where the action happens); 기다리다 → 기다려요 (present, polite casual)" } },
    "kv0684": { korean: "여객선 터미널", note: "A passenger ferry terminal — 여객선 (passenger ship) plus 터미널, written with a space as two nouns.", example: { ko: "여객선 터미널에 가요.", en: "I go to the ferry terminal.", form: "여객선 터미널 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv0701": { korean: "인도네시아", note: "Indonesia. Nationality 인도네시아 사람, language 인도네시아어. Not to be confused with 인도 (India).", example: { ko: "인도네시아에서 왔어요.", en: "I came from Indonesia.", form: "인도네시아 + 에서 (origin particle); 오다 → 왔어요 (past, polite casual)" } },
    "kv0992": { korean: "걸리다", note: "To take time — 한 시간 걸려요 — and also to be caught or to catch an illness: 감기에 걸렸어요. In the time sense it is intransitive, so the duration simply sits before it with no particle.", example: { ko: "학교까지 삼십 분 걸려요.", en: "It takes thirty minutes to school.", form: "학교 + 까지 (limit particle); duration with no particle; 걸리다 → 걸려요 (present, polite casual)" } },
    "kv1033": { korean: "터미널", note: "A terminal — usually the intercity bus terminal (버스 터미널). Larger than a 정류장, which is a roadside stop.", example: { ko: "터미널에서 버스를 타요.", en: "I take the bus at the terminal.", form: "터미널 + 에서 (where the action happens); 타다 → 타요 (present, polite casual)" } },

    // ------------------------------------------------------------ Bab 17
    "kv0032": { korean: "다시", note: "Again. Placed before the verb: 다시 말해 주세요 ('say it again'). 또 also means again, but leans towards a repeat you didn't ask for.", example: { ko: "다시 말해 주세요.", en: "Please say it again.", form: "다시 modifies the verb; 말하다 + -아/어 주다 + -세요 → 말해 주세요 (request for a favour; polite)" } },
    "kv0068": { korean: "길", note: "A road or way, and by extension directions: 길을 물어요 (ask the way), 길을 잃다 (get lost). Note the unrelated adjective 길다 (to be long).", example: { ko: "길을 건너요.", en: "I cross the road.", form: "길 + 을 (object particle); 건너다 → 건너요 (present, polite casual)" } },
    "kv0095": { korean: "타다", note: "To ride or board — buses, trains, planes, bicycles, and also skis and skates. The vehicle takes 을/를, never 에: 버스를 타요. Getting off is 내리다 with 에서.", example: { ko: "지하철을 타요.", en: "I take the subway.", form: "지하철 + 을 (object particle); 타다 → 타요 (identical ㅏ merges; present, polite casual)" } },
    "kv0101": { korean: "열다", note: "To open — doors, windows, shops, a meeting. Its opposite is 닫다. A ㄹ-stem, so the ㄹ drops in 여는 and 엽니다. A book is opened with 펴다 instead.", example: { ko: "창문을 열어요.", en: "I open the window.", form: "창문 + 을 (object particle); 열다 → 열어요 (present, polite casual)" } },
    "kv0104": { korean: "기다리다", note: "To wait. What you wait for takes 을/를, not 에: 친구를 기다려요, never 친구에게 기다려요.", example: { ko: "친구를 기다려요.", en: "I wait for my friend.", form: "친구 + 를 (object particle); 기다리다 → 기다려요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "kv0111": { korean: "정말", note: "Really, truly. It works as an intensifier before a predicate (정말 맛있어요) and as a one-word reaction: 정말요? ('really?'). 진짜 is its casual twin.", example: { ko: "정말 맛있어요.", en: "It's really delicious.", form: "정말 modifies the predicate; 맛있다 → 맛있어요 (present, polite casual)" } },
    "kv0130": { korean: "놀다", note: "To play, or to hang out — adults use it too: 친구하고 놀아요 means spending time together, not playing a game. A ㄹ-stem: 노는, 놉니다. A specific game takes 하다.", example: { ko: "친구하고 놀아요.", en: "I hang out with a friend.", form: "친구 + 하고 (companion particle); 놀다 → 놀아요 (present, polite casual)" } },
    "kv0178": { korean: "올해", note: "This year — a native word that breaks the 작년 / 내년 pattern around it. It takes no particle: 올해 스무 살이에요.", example: { ko: "올해 한국에 왔어요.", en: "I came to Korea this year.", form: "올해 used adverbially with no particle; 오다 → 왔어요 (past, polite casual)" } },
    "kv0184": { korean: "해", note: "A year, and also the sun. As a year it appears in 올해 and in counting: 삼 년 uses 년, while 해 is more literary — 해가 바뀌다 (the year turns).", example: { ko: "해가 떠요.", en: "The sun rises.", form: "해 + 가 (subject particle); 뜨다 → 떠요 (ㅡ-irregular; present, polite casual)" } },
    "kv0196": { korean: "손님", note: "A customer or guest — the 님 makes it respectful, which is why shops address you as 손님. Literally 'guest', so it covers visitors to your home too.", example: { ko: "손님이 오셨어요.", en: "A guest has arrived.", form: "손님 + 이 (subject particle); 오다 + -시- → 오셨어요 (honorific past, polite casual)" } },
    "kv0440": { korean: "피우다", note: "To smoke (담배를 피우다) and, for flowers, to bloom (꽃을 피우다). 'No smoking' is 금연 or 담배를 피우지 마세요.", example: { ko: "여기에서 담배를 피우지 마세요.", en: "Please don't smoke here.", form: "피우다 + -지 말다 + -세요 → 피우지 마세요 (prohibition; polite request)" } },
    "kv0486": { korean: "왼쪽", note: "The left side. The 쪽 suffix means 'side' or 'direction': 오른쪽, 이쪽, 저쪽. Turning left is 왼쪽으로 가세요.", example: { ko: "왼쪽으로 가세요.", en: "Please go to the left.", form: "왼쪽 + 으로 (direction particle after a batchim); 가다 + -세요 → 가세요 (polite request)" } },
    "kv0491": { korean: "오른쪽", note: "The right side — the partner of 왼쪽. Direction takes 으로: 오른쪽으로 도세요.", example: { ko: "오른쪽에 은행이 있어요.", en: "There is a bank on the right.", form: "오른쪽 + 에 (location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0492": { korean: "지도", note: "A map. Looking at one is 지도를 보다. Note the homograph 지도 meaning guidance (지도하다 = to instruct).", example: { ko: "지도를 봐요.", en: "I look at the map.", form: "지도 + 를 (object particle); 보다 → 봐요 (present, polite casual)" } },
    "kv0510": { korean: "도와주다", note: "To help — 돕다 plus -아 주다 ('do for someone'), which is why the ㅂ turns into 와. The person helped takes 을/를: 친구를 도와줘요. 'Please help me' is 도와주세요.", example: { ko: "친구를 도와줘요.", en: "I help my friend.", form: "친구 + 를 (object particle); 도와주다 → 도와줘요 (ㅜ + 어 contracts to 워; present, polite casual)" } },
    "kv0533": { korean: "죄송하다", note: "To be sorry — the formal, more apologetic word, used with strangers and seniors. 미안하다 is for friends and equals. A 하다 adjective: 죄송해요, 죄송합니다.", example: { ko: "정말 죄송해요.", en: "I'm really sorry.", form: "죄송하다 → 죄송해요 (하다 contracts to 해요; present, polite casual)" } },
    "kv0570": { korean: "똑바로", note: "Straight ahead, or 'properly'. Giving directions it means keep going without turning: 똑바로 가세요. 직진하다 is the more formal driving term.", example: { ko: "똑바로 가세요.", en: "Please go straight ahead.", form: "똑바로 modifies the verb; 가다 + -세요 → 가세요 (polite request)" } },
    "kv0598": { korean: "횡단보도", note: "A pedestrian crossing. Crossing it uses 건너다 with 을/를: 횡단보도를 건너요.", example: { ko: "횡단보도를 건너요.", en: "I cross at the crosswalk.", form: "횡단보도 + 를 (object particle); 건너다 → 건너요 (present, polite casual)" } },
    "kv0642": { korean: "경주", note: "Gyeongju, the ancient Silla capital in the southeast — a city of tombs and temples, and a standard school-trip destination.", example: { ko: "경주에 여행을 가요.", en: "I take a trip to Gyeongju.", form: "경주 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv0695": { korean: "우회전", note: "A right turn — 우 (right) + 회전 (rotation), the word on road signs. The verb is 우회전하다; in speech people say 오른쪽으로 가세요.", example: { ko: "여기에서 우회전하세요.", en: "Please turn right here.", form: "여기 + 에서 (where the action happens); 우회전하다 + -세요 → 우회전하세요 (polite request)" } },
    "kv0707": { korean: "좌회전", note: "A left turn — 좌 (left) + 회전. Its partner is 우회전; note that the sign words use 좌/우, while everyday speech uses 왼쪽/오른쪽.", example: { ko: "다음 신호에서 좌회전하세요.", en: "Please turn left at the next light.", form: "신호 + 에서 (where the action happens); 좌회전하다 + -세요 → 좌회전하세요 (polite request)" } },

    // -------------------------------------------------- Bab 17 (continued)
    "kv0712": { korean: "직진", note: "Going straight ahead — the road-sign word, with 직진하다 as the verb. In everyday directions people say 똑바로 가세요.", example: { ko: "여기에서 직진하세요.", en: "Please go straight from here.", form: "여기 + 에서 (starting point); 직진하다 + -세요 → 직진하세요 (polite request)" } },
    "kv0723": { korean: "타고 가다", note: "'To go by (some transport)' — 타다 with the -고 link, literally 'board and go'. The vehicle takes 을/를: 버스를 타고 가요. The alternative is the particle 로/으로: 버스로 가요.", example: { ko: "버스를 타고 가요.", en: "I go by bus.", form: "타다 + -고 → 타고 (sequential link); 가다 → 가요 (present, polite casual)" } },
    "kv1003": { korean: "기사", note: "A news article — and, as a separate word, a driver addressed politely (기사님). Context separates them completely.", example: { ko: "신문 기사를 읽어요.", en: "I read a newspaper article.", form: "신문 + 기사 (noun compound) + 를 (object particle); 읽다 → 읽어요 (present, polite casual)" } },
    "kv1038": { korean: "스키장", note: "A ski resort — 스키 plus the place suffix 장, like 운동장 and 수영장.", example: { ko: "겨울에 스키장에 가요.", en: "I go to the ski resort in winter.", form: "스키장 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },

    // ------------------------------------------------------------ Bab 18
    "kv0047": { korean: "여러", note: "'Several' or 'various' — a determiner that must be followed by a noun, with no particle between: 여러 사람, 여러 나라. It cannot stand alone the way 많이 can.", example: { ko: "여러 나라에 갔어요.", en: "I went to several countries.", form: "여러 + 나라 (determiner before a noun) + 에 (destination particle); 가다 → 갔어요 (past, polite casual)" } },
    "kv0055": { korean: "번", note: "The counter for the number of times (native numbers: 한 번, 두 번) and for numbered items like bus routes and addresses (Sino-Korean: 이 번 버스). Which number system you use depends on which sense you mean.", example: { ko: "한국에 두 번 갔어요.", en: "I have been to Korea twice.", form: "두 + 번 (native number plus the times counter); 가다 → 갔어요 (past, polite casual)" } },
    "kv0069": { korean: "생활", note: "Life in the sense of daily living — 한국 생활, 학교 생활. Life as opposed to death is 삶 or 인생, so 생활 is about how you live day to day.", example: { ko: "한국 생활이 재미있어요.", en: "Life in Korea is interesting.", form: "한국 + 생활 (noun compound) + 이 (subject particle); 재미있다 → 재미있어요 (present, polite casual)" } },
    "kv0118": { korean: "혼자", note: "Alone, by oneself. It works as an adverb before the verb (혼자 살아요) and as a noun (혼자가 좋아요). Its opposite is 같이 or 함께.", example: { ko: "저는 혼자 살아요.", en: "I live alone.", form: "혼자 modifies the verb; 살다 → 살아요 (present, polite casual)" } },
    "kv0166": { korean: "그러면", note: "'Then' or 'in that case' — opening a sentence that follows from what was just said. It shortens to 그럼 in speech.", example: { ko: "그러면 내일 만나요.", en: "In that case, let's meet tomorrow.", form: "그러면 opens the sentence and never conjugates; 만나다 → 만나요 (present used as a suggestion; polite casual)" } },
    "kv0187": { korean: "자동차", note: "A car — the full, slightly formal word. 차 is what people actually say, though 차 also means tea. Driven with 운전하다 and boarded with 타다.", example: { ko: "자동차를 운전해요.", en: "I drive a car.", form: "자동차 + 를 (object particle); 운전하다 → 운전해요 (present, polite casual)" } },
    "kv0201": { korean: "식사", note: "A meal, in the formal sense — 식사하셨어요? is the polite version of 밥 먹었어요? The verb is 식사하다.", example: { ko: "식사하셨어요?", en: "Have you eaten? (polite)", form: "식사하다 + -시- + -었- → 식사하셨어요 (honorific past, polite casual, question)" } },
    "kv0418": { korean: "쓰레기", note: "Garbage. Throwing it away is 쓰레기를 버리다, and the bin is 쓰레기통. Korea sorts waste strictly: 분리수거.", example: { ko: "쓰레기를 버려요.", en: "I throw out the garbage.", form: "쓰레기 + 를 (object particle); 버리다 → 버려요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "kv0432": { korean: "일찍", note: "Early — before the expected time: 일찍 일어나요. Its opposite is 늦게. Note that 빨리 means fast, not early.", example: { ko: "아침에 일찍 일어나요.", en: "I get up early in the morning.", form: "일찍 modifies the verb; 일어나다 → 일어나요 (present, polite casual)" } },
    "kv0439": { korean: "목", note: "The neck, and also the throat: 목이 아파요 covers both a stiff neck and a sore throat. 목소리 is the voice.", example: { ko: "목이 아파요.", en: "My throat hurts.", form: "목 + 이 (subject particle); 아프다 → 아파요 (ㅡ-irregular; present, polite casual)" } },
    "kv0441": { korean: "교통", note: "Traffic and transport in general: 교통이 복잡해요 (the traffic is heavy), 대중교통 (public transport), 교통사고 (a traffic accident).", example: { ko: "교통이 복잡해요.", en: "The traffic is heavy.", form: "교통 + 이 (subject particle); 복잡하다 → 복잡해요 (하다 contracts to 해요; present, polite casual)" } },
    "kv0455": { korean: "복잡하다", note: "Complicated, and also crowded or congested — 길이 복잡해요 means the street is busy, not that it is confusing. A 하다 adjective: 복잡해요.", example: { ko: "지하철이 복잡해요.", en: "The subway is crowded.", form: "지하철 + 이 (subject particle); 복잡하다 → 복잡해요 (present, polite casual)" } },
    "kv0470": { korean: "서두르다", note: "To hurry. A 르-irregular: the 르 doubles the ㄹ before a vowel ending, giving 서둘러요. 'Don't rush' is 서두르지 마세요.", example: { ko: "빨리 서둘러요.", en: "Hurry up.", form: "서두르다 → 서둘러요 (르-irregular: ㄹ doubles before -어요; present, polite casual)" } },
    "kv0499": { korean: "출발하다", note: "To depart. The starting point takes 에서 and the time takes 에: 아홉 시에 출발해요. Its opposite is 도착하다.", example: { ko: "기차가 아홉 시에 출발해요.", en: "The train departs at nine o'clock.", form: "아홉 시 + 에 (time particle); 출발하다 → 출발해요 (present, polite casual)" } },
    "kv0502": { korean: "약", note: "Medicine. It is 'eaten' in Korean: 약을 먹어요, never 마시다. The pharmacy is 약국. As a prefix 약 also means 'approximately' (약 30분).", example: { ko: "약을 먹어요.", en: "I take medicine.", form: "약 + 을 (object particle); 먹다 → 먹어요 (present, polite casual — medicine takes 먹다)" } },
    "kv0508": { korean: "위험하다", note: "Dangerous. A 하다 adjective: 위험해요. Its opposite is 안전하다, and 위험! on a sign means 'danger'.", example: { ko: "밤에 혼자 가면 위험해요.", en: "It's dangerous to go alone at night.", form: "가다 + -(으)면 → 가면 (conditional link); 위험하다 → 위험해요 (present, polite casual)" } },
    "kv0526": { korean: "요즈음", note: "These days — the full form of 요즘, slightly more written. Both take no particle: 요즈음 바빠요.", example: { ko: "요즈음 날씨가 좋아요.", en: "The weather is nice these days.", form: "요즈음 used adverbially with no particle; 좋다 → 좋아요 (present, polite casual)" } },
    "kv0536": { korean: "유학", note: "Studying abroad. The verb is 유학하다 or 유학을 가다, and a student doing it is a 유학생.", example: { ko: "한국에 유학을 가요.", en: "I go to Korea to study abroad.", form: "유학 + 을 (object particle); 가다 → 가요 (present, polite casual)" } },
    "kv0545": { korean: "감기", note: "A cold. You 'get caught by' one: 감기에 걸렸어요, with 에 — never 감기를 잡다. The related verb 걸리다 is the same one used for time taken.", example: { ko: "감기에 걸렸어요.", en: "I caught a cold.", form: "감기 + 에 (particle marking what caught you); 걸리다 → 걸렸어요 (past, polite casual)" } },
    "kv0559": { korean: "찬물", note: "Cold water — 차다 (to be cold) in its noun-modifying form 찬, plus 물. Hot water is 뜨거운 물 or 따뜻한 물.", example: { ko: "찬물을 마셔요.", en: "I drink cold water.", form: "찬 (modifying form of 차다) + 물, then 을 (object particle); 마시다 → 마셔요 (present, polite casual)" } },
    "kv0610": { korean: "다이어트", note: "A diet, in the weight-loss sense. The verb is 다이어트하다 or 다이어트를 하다 — it means slimming, not one's general eating habits (식습관).", example: { ko: "요즘 다이어트를 해요.", en: "I'm on a diet these days.", form: "다이어트 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0632": { korean: "주차하다", note: "To park a vehicle. The place takes 에: 주차장에 주차해요. 'No parking' is 주차 금지.", example: { ko: "여기에 주차하지 마세요.", en: "Please don't park here.", form: "여기 + 에 (location particle); 주차하다 + -지 말다 + -세요 → 주차하지 마세요 (prohibition; polite request)" } },
    "kv0652": { korean: "등산화", note: "Hiking boots — 등산 plus the footwear suffix 화, as in 운동화 and 구두. Put on with 신다.", example: { ko: "등산화를 신어요.", en: "I put on hiking boots.", form: "등산화 + 를 (object particle); 신다 → 신어요 (present, polite casual)" } },
    "kv0667": { korean: "보름", note: "Fifteen days, or half a month — and by extension the full moon (보름달). It belongs to the native day-counting series alongside 하루, 이틀, 사흘.", example: { ko: "보름 동안 여행했어요.", en: "I travelled for fifteen days.", form: "보름 + 동안 (duration particle); 여행하다 → 여행했어요 (past, polite casual)" } },
    "kv0678": { korean: "아침 식사", note: "Breakfast, in the formal register — two nouns with a space. Everyday speech just says 아침.", example: { ko: "아침 식사를 해요.", en: "I have breakfast.", form: "아침 식사 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0679": { korean: "아흐레", note: "Nine days, in the native day-counting series: 하루, 이틀, 사흘, 나흘, 닷새, 엿새, 이레, 여드레, 아흐레, 열흘. These are separate words, not number plus counter.", example: { ko: "아흐레 동안 쉬었어요.", en: "I rested for nine days.", form: "아흐레 + 동안 (duration particle); 쉬다 → 쉬었어요 (past, polite casual)" } },
    "kv0685": { korean: "여드레", note: "Eight days, from the native day series. Do not confuse it with 여덟 (the number eight) — 여드레 already means 'eight days' with no counter.", example: { ko: "여드레 동안 한국에 있었어요.", en: "I was in Korea for eight days.", form: "여드레 + 동안 (duration particle); 있다 → 있었어요 (past, polite casual)" } },
    "kv0686": { korean: "엿새", note: "Six days, from the native day series. Its 새 ending is shared with 닷새 (five days).", example: { ko: "엿새 후에 만나요.", en: "Let's meet in six days.", form: "엿새 + 후 + 에 (time phrase); 만나다 → 만나요 (present used as a suggestion; polite casual)" } },
    "kv0697": { korean: "이레", note: "Seven days, from the native day series. In everyday speech people say 일주일 instead, using the Sino-Korean week word.", example: { ko: "이레 동안 공부했어요.", en: "I studied for seven days.", form: "이레 + 동안 (duration particle); 공부하다 → 공부했어요 (past, polite casual)" } },
    "kv0989": { korean: "가지", note: "A dependent noun counting kinds or varieties: 두 가지 방법 (two methods), 여러 가지 (various kinds). It is also, separately, the vegetable aubergine.", example: { ko: "여러 가지 음식을 먹었어요.", en: "I ate various kinds of food.", form: "여러 + 가지 (determiner plus the kind counter); 먹다 → 먹었어요 (past, polite casual)" } },
    "kv0991": { korean: "하루", note: "One day, and 'a day' in general: 하루 종일 (all day long). It heads the native day series and is not 일 (the Sino-Korean day).", example: { ko: "하루 종일 일했어요.", en: "I worked all day long.", form: "하루 종일 (fixed phrase, no particle); 일하다 → 일했어요 (past, polite casual)" } },
    "kv0996": { korean: "새벽", note: "Dawn, or the small hours — roughly midnight to sunrise. 새벽 세 시 is 3 AM, a time Koreans call 새벽 rather than 오전.", example: { ko: "새벽에 일어났어요.", en: "I got up at dawn.", form: "새벽 + 에 (time particle); 일어나다 → 일어났어요 (past, polite casual)" } },
    "kv1012": { korean: "이틀", note: "Two days, from the native day series — not 이 일. 'The second day of the month' is 이일, a completely different word.", example: { ko: "이틀 동안 비가 왔어요.", en: "It rained for two days.", form: "이틀 + 동안 (duration particle); 오다 → 왔어요 (past, polite casual)" } },
    "kv1015": { korean: "사흘", note: "Three days, from the native day series. Note the 흘 ending shared with 나흘 and 열흘.", example: { ko: "사흘 후에 출발해요.", en: "I depart in three days.", form: "사흘 + 후 + 에 (time phrase); 출발하다 → 출발해요 (present, polite casual)" } },
    "kv1023": { korean: "열흘", note: "Ten days, closing the native day series. Beyond ten, Korean switches to Sino-Korean numbers with 일: 십오 일.", example: { ko: "열흘 동안 여행했어요.", en: "I travelled for ten days.", form: "열흘 + 동안 (duration particle); 여행하다 → 여행했어요 (past, polite casual)" } },
    "kv1036": { korean: "치과", note: "A dental clinic, pronounced [치꽈]. The 과 suffix marks medical departments: 내과, 안과, 소아과.", example: { ko: "치과에 가요.", en: "I go to the dentist.", form: "치과 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv1039": { korean: "나흘", note: "Four days, from the native day series. Not to be confused with 사일, which is the fourth day of the month.", example: { ko: "나흘 동안 아팠어요.", en: "I was sick for four days.", form: "나흘 + 동안 (duration particle); 아프다 → 아팠어요 (ㅡ-irregular; past, polite casual)" } },
    "kv1041": { korean: "닷새", note: "Five days, from the native day series, sharing its 새 ending with 엿새.", example: { ko: "닷새 후에 시험이 있어요.", en: "There is an exam in five days.", form: "닷새 + 후 + 에 (time phrase); 있다 → 있어요 (present, polite casual)" } },

    // ------------------------------------------------------------ Bab 19
    "kv0053": { korean: "어느", note: "'Which' — a determiner picking from a known set, always before a noun: 어느 나라, 어느 것. Compare 무슨 (what kind of) and 어떤 (what sort, describing).", example: { ko: "어느 나라에서 왔어요?", en: "Which country are you from?", form: "어느 + 나라 (determiner before a noun) + 에서 (origin particle); 오다 → 왔어요 (past, polite casual, question)" } },
    "kv0057": { korean: "그런데", note: "'But' or 'by the way' — it both contrasts and changes the subject, which is why it opens so many sentences. 하지만 only contrasts.", example: { ko: "비싸요. 그런데 아주 좋아요.", en: "It's expensive. But it's very good.", form: "그런데 opens the sentence and never conjugates; 좋다 → 좋아요 (present, polite casual)" } },
    "kv0072": { korean: "처음", note: "The first time, or the beginning. As a noun it takes particles (처음이에요), and as an adverb it stands alone: 처음 만났어요. The greeting 처음 뵙겠습니다 uses it.", example: { ko: "한국은 처음이에요.", en: "This is my first time in Korea.", form: "처음 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "kv0102": { korean: "머리", note: "The head, and also the hair on it — 머리가 길어요 means your hair is long, not your head. Washing it takes 감다, cutting it 자르다.", example: { ko: "머리가 아파요.", en: "I have a headache.", form: "머리 + 가 (subject particle); 아프다 → 아파요 (ㅡ-irregular; present, polite casual)" } },
    "kv0163": { korean: "참", note: "'Truly' — an intensifier much like 정말, with a slightly warmer, older feel: 참 좋아요. It also works as an interjection when something comes back to you: 참, 그런데…", example: { ko: "참 맛있어요.", en: "It's truly delicious.", form: "참 modifies the predicate; 맛있다 → 맛있어요 (present, polite casual)" } },
    "kv0183": { korean: "아마", note: "Probably. It usually pairs with a guessing ending like -(으)ㄹ 거예요 or -겠-: 아마 올 거예요. On its own with a plain statement it sounds unfinished.", example: { ko: "아마 내일 올 거예요.", en: "He/she will probably come tomorrow.", form: "아마 modifies the clause; 오다 + -(으)ㄹ 거예요 → 올 거예요 (supposition/future, polite casual)" } },
    "kv0578": { korean: "여행하다", note: "To travel. The place takes 을/를 or 에서: 한국을 여행해요. 여행을 가다 is just as common for taking a trip.", example: { ko: "한국을 여행해요.", en: "I travel around Korea.", form: "한국 + 을 (object particle); 여행하다 → 여행해요 (present, polite casual)" } },
    "kv0651": { korean: "등록하다", note: "To register or enrol — for a class, a course, or a service. What you register for takes 을/를: 수업을 등록해요.", example: { ko: "한국어 수업을 등록했어요.", en: "I registered for the Korean class.", form: "수업 + 을 (object particle); 등록하다 → 등록했어요 (past, polite casual)" } },
    "kv0672": { korean: "샤워하다", note: "To take a shower. 목욕하다 is a bath in a tub, and 씻다 is washing generally.", example: { ko: "아침에 샤워해요.", en: "I shower in the morning.", form: "아침 + 에 (time particle); 샤워하다 → 샤워해요 (present, polite casual)" } },
    "kv0675": { korean: "수업하다", note: "To hold or conduct a class — what the teacher does. The student's side is 수업을 듣다 ('listen to the class').", example: { ko: "선생님이 수업해요.", en: "The teacher holds the class.", form: "선생님 + 이 (subject particle); 수업하다 → 수업해요 (present, polite casual)" } },
    "kv0677": { korean: "심심하다", note: "To be bored — the feeling of having nothing to do. Distinct from 재미없다, which says the thing itself is boring: 저는 심심해요 vs 이 영화는 재미없어요.", example: { ko: "오늘 심심해요.", en: "I'm bored today.", form: "심심하다 → 심심해요 (하다 contracts to 해요; present, polite casual)" } },
    "kv0680": { korean: "안과", note: "An eye clinic. The 과 suffix marks medical departments, as in 치과 and 내과.", example: { ko: "안과에 가요.", en: "I go to the eye clinic.", form: "안과 + 에 (destination particle); 가다 → 가요 (present, polite casual)" } },
    "kv0689": { korean: "오전반", note: "The morning class or section — 오전 plus 반 (class group). Its partners are 오후반 and 주말반.", example: { ko: "저는 오전반이에요.", en: "I'm in the morning class.", form: "오전반 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "kv0691": { korean: "오후반", note: "The afternoon class — 오후 plus 반. Note that 반 also means 'half' (한 시 반 = 1:30).", example: { ko: "오후반에서 공부해요.", en: "I study in the afternoon class.", form: "오후반 + 에서 (where the action happens); 공부하다 → 공부해요 (present, polite casual)" } },
    "kv0709": { korean: "주말반", note: "The weekend class — 주말 plus 반, for courses that meet on Saturdays or Sundays.", example: { ko: "주말반을 등록했어요.", en: "I registered for the weekend class.", form: "주말반 + 을 (object particle); 등록하다 → 등록했어요 (past, polite casual)" } },
    "kv0711": { korean: "중급반", note: "The intermediate class. Levels run 초급 (beginner), 중급 (intermediate), 고급 (advanced), each plus 반.", example: { ko: "중급반에서 공부해요.", en: "I study in the intermediate class.", form: "중급반 + 에서 (where the action happens); 공부하다 → 공부해요 (present, polite casual)" } },
    "kv0714": { korean: "쯤", note: "'About' or 'approximately' — a particle attached directly to the end of a number or time with no space: 세 시쯤, 만 원쯤. It goes after the amount, unlike English 'about', which goes before.", example: { ko: "세 시쯤 만나요.", en: "Let's meet around three o'clock.", form: "세 시 + 쯤 (approximation particle, attached with no space); 만나다 → 만나요 (present used as a suggestion)" } },
    "kv0715": { korean: "체육관", note: "A gymnasium — 체육 (physical education) plus the building suffix 관, as in 도서관 and 영화관.", example: { ko: "체육관에서 운동해요.", en: "I exercise at the gym.", form: "체육관 + 에서 (where the action happens); 운동하다 → 운동해요 (present, polite casual)" } },
    "kv0716": { korean: "초급반", note: "The beginner class — 초급 plus 반, the first rung of 초급 / 중급 / 고급.", example: { ko: "초급반에서 한국어를 배워요.", en: "I learn Korean in the beginner class.", form: "초급반 + 에서 (where the action happens); 배우다 → 배워요 (present, polite casual)" } },
    "kv0997": { korean: "무섭다", note: "Scary, and also 'afraid' — one word covers both: 개가 무서워요 can mean the dog is scary or that you are scared of it. A ㅂ-irregular: 무서워요.", example: { ko: "그 영화가 무서워요.", en: "That movie is scary.", form: "영화 + 가 (subject particle); 무섭다 → 무서워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0999": { korean: "직원", note: "An employee or staff member. The 원 suffix again marks organisation members, as in 회사원 and 공무원.", example: { ko: "직원이 친절해요.", en: "The staff are kind.", form: "직원 + 이 (subject particle); 친절하다 → 친절해요 (present, polite casual)" } },

    // ------------------------------------------------------------ Bab 20
    "kv0218": { korean: "말", note: "Speech, words, or a language (한국말) — and, as a separate word, a horse. The speech sense pairs with 하다: 말을 해요.", example: { ko: "한국말을 배워요.", en: "I learn the Korean language.", form: "한국말 + 을 (object particle); 배우다 → 배워요 (present, polite casual)" } },
    "kv0226": { korean: "문제", note: "A problem, and also a question on a test — 시험 문제. 질문 is a question you ask someone, while 문제 is one to be solved.", example: { ko: "문제가 어려워요.", en: "The problem is difficult.", form: "문제 + 가 (subject particle); 어렵다 → 어려워요 (ㅂ-irregular; present, polite casual)" } },
    "kv0227": { korean: "살다", note: "To live, or to reside. The place takes 에 or 에서: 서울에서 살아요. A ㄹ-stem, so the ㄹ drops in 사는 and 삽니다.", example: { ko: "서울에서 살아요.", en: "I live in Seoul.", form: "서울 + 에서 (where you live); 살다 → 살아요 (present, polite casual)" } },
    "kv0237": { korean: "듣다", note: "To listen or hear — music, a lecture, someone's words. A ㄷ-irregular: the ㄷ becomes ㄹ before a vowel ending, giving 들어요.", example: { ko: "음악을 들어요.", en: "I listen to music.", form: "음악 + 을 (object particle); 듣다 → 들어요 (ㄷ-irregular; present, polite casual)" } },
    "kv0249": { korean: "무엇", note: "What — the full, formal form of 뭐, used in writing and careful speech: 무엇을 하십니까? In conversation it always shortens.", example: { ko: "무엇을 좋아해요?", en: "What do you like?", form: "무엇 + 을 (object particle); 좋아하다 → 좋아해요 (present, polite casual, question)" } },
    "kv0292": { korean: "묻다", note: "To ask a question — a ㄷ-irregular in this sense: 물어요. The person asked takes 한테 or 에게. Its homograph 묻다 ('to bury') is regular: 묻어요.", example: { ko: "선생님한테 물어요.", en: "I ask the teacher.", form: "선생님 + 한테 (recipient particle); 묻다 → 물어요 (ㄷ-irregular; present, polite casual)" } },
    "kv0293": { korean: "거기", note: "There — the place near the listener, or one already mentioned. The set runs 여기 / 거기 / 저기, matching 이 / 그 / 저.", example: { ko: "거기에서 만나요.", en: "Let's meet there.", form: "거기 + 에서 (where the action happens); 만나다 → 만나요 (present used as a suggestion; polite casual)" } },
    "kv0294": { korean: "아들", note: "A son. Its pair is 딸. Note that Korean also uses 아들 for one's own grown son, with no separate word for 'boy' in the family sense (that is 남자아이).", example: { ko: "아들이 학생이에요.", en: "My son is a student.", form: "아들 + 이 (subject particle); 이에요 (present, polite casual)" } },
    "kv0300": { korean: "그래", note: "'Yeah' or 'that's right' — the casual 반말 agreement, used with friends and juniors. Its polite forms are 네, 그래요, and 맞아요.", example: { ko: "그래, 내일 만나자.", en: "Yeah, let's meet tomorrow.", form: "그래 is a casual reply word; 만나다 + -자 → 만나자 (casual suggestion, 반말)" } },
    "kv0324": { korean: "문", note: "A door. Opened with 열다 and closed with 닫다. Also the second half of 창문 (window).", example: { ko: "문을 닫아 주세요.", en: "Please close the door.", form: "문 + 을 (object particle); 닫다 + -아 주다 + -세요 → 닫아 주세요 (request for a favour; polite)" } },
    "kv0333": { korean: "선생", note: "Teacher, without the honorific — and for that reason it is almost never used alone when addressing someone. In practice you always say 선생님.", example: { ko: "그분은 선생님이에요.", en: "That person is a teacher.", form: "선생 + 님 (honorific suffix) + 이에요 (present, polite casual)" } },
    "kv0338": { korean: "걷다", note: "To walk. A ㄷ-irregular: 걸어요. 'To go on foot' is 걸어서 가요 — the -아서/어서 form of this verb, not 걷고 가다.", example: { ko: "학교까지 걸어서 가요.", en: "I walk to school.", form: "걷다 + -어서 → 걸어서 (ㄷ-irregular plus the means link); 가다 → 가요 (present, polite casual)" } },
    "kv0345": { korean: "음악", note: "Music. Listened to with 듣다, never 보다: 음악을 들어요.", example: { ko: "음악을 들어요.", en: "I listen to music.", form: "음악 + 을 (object particle); 듣다 → 들어요 (ㄷ-irregular; present, polite casual)" } },
    "kv0357": { korean: "딸", note: "A daughter — the pair of 아들. Note the homograph 딸 in 딸기 (strawberry), which is unrelated.", example: { ko: "딸이 두 명 있어요.", en: "I have two daughters.", form: "딸 + 이 (subject particle); 두 + 명 (native number plus the people counter); 있다 → 있어요 (present, polite casual)" } },
    "kv0366": { korean: "부모", note: "Parents, without the honorific. Like 선생 it is rarely used bare — in normal speech you say 부모님.", example: { ko: "부모님께서 오세요.", en: "My parents are coming.", form: "부모 + 님 (honorific suffix) + 께서 (honorific subject particle); 오다 + -시- → 오세요 (honorific present)" } },
    "kv0379": { korean: "다리", note: "A leg, and also a bridge — two words with the same shape. 다리가 아파요 is a sore leg; 다리를 건너요 is crossing a bridge.", example: { ko: "다리가 아파요.", en: "My leg hurts.", form: "다리 + 가 (subject particle); 아프다 → 아파요 (ㅡ-irregular; present, polite casual)" } },
    "kv0396": { korean: "반", note: "Half — used for clock times: 한 시 반 = half past one. It is also a class group (오전반), and 절반 is 'half' as a portion.", example: { ko: "두 시 반에 만나요.", en: "Let's meet at half past two.", form: "두 시 + 반 + 에 (time phrase plus time particle); 만나다 → 만나요 (present used as a suggestion)" } },
    "kv0755": { korean: "준비", note: "Preparation. Used as 준비를 하다 or the verb 준비하다; 'ready' is 준비가 됐어요.", example: { ko: "여행 준비를 해요.", en: "I prepare for the trip.", form: "준비 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0759": { korean: "준비하다", note: "To prepare. What you prepare takes 을/를 (저녁을 준비해요); what you prepare for takes 을/를 too, or the phrase -을/를 위해.", example: { ko: "저녁을 준비해요.", en: "I prepare dinner.", form: "저녁 + 을 (object particle); 준비하다 → 준비해요 (present, polite casual)" } },
    "kv0761": { korean: "사장", note: "A company president or boss. Addressing them you must add the honorific: 사장님. The bare 사장 only appears in third-person description.", example: { ko: "사장님이 오셨어요.", en: "The boss has arrived.", form: "사장 + 님 (honorific suffix) + 이 (subject particle); 오다 + -시- → 오셨어요 (honorific past)" } },
    "kv0787": { korean: "떡", note: "Tteok — chewy rice cake, eaten as a snack and at celebrations. Counted with 개, and the base of 떡볶이 and 떡국.", example: { ko: "떡을 먹어요.", en: "I eat rice cake.", form: "떡 + 을 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv0816": { korean: "지하", note: "Underground. It names basement floors — 지하 일 층 (B1) — and is the first half of 지하철.", example: { ko: "지하 일 층에 있어요.", en: "It's on basement level one.", form: "지하 + 일 층 + 에 (floor phrase plus location particle); 있다 → 있어요 (present, polite casual)" } },
    "kv0842": { korean: "설탕", note: "Sugar. Salt is 소금 — the two sit together in recipes, so keep them apart.", example: { ko: "설탕을 넣어요.", en: "I add sugar.", form: "설탕 + 을 (object particle); 넣다 → 넣어요 (present, polite casual)" } },
    "kv0863": { korean: "안경", note: "Glasses. Worn with 쓰다, the same verb as hats — never 입다 or 신다. Sunglasses are 선글라스.", example: { ko: "안경을 써요.", en: "I wear glasses.", form: "안경 + 을 (object particle); 쓰다 → 써요 (ㅡ-irregular; present, polite casual)" } },
    "kv0888": { korean: "전화번호", note: "A phone number — 전화 plus 번호. Read digit by digit with Sino-Korean numbers, and 공 is used for zero rather than 영.", example: { ko: "전화번호가 뭐예요?", en: "What is your phone number?", form: "전화번호 + 가 (subject particle); 뭐 + 예요 (present, polite casual, question)" } },
    "kv0897": { korean: "여권", note: "A passport, pronounced [여꿘]. Do not confuse it with 여행 (travel) or 표 (a ticket).", example: { ko: "여권이 필요해요.", en: "I need a passport.", form: "여권 + 이 (subject particle — 필요하다 marks what is needed with 이/가); 필요하다 → 필요해요 (present, polite casual)" } },
    "kv0899": { korean: "번호", note: "A number in the identifying sense — a phone number, a seat number, a house number. Quantity is 수 or 숫자, not 번호.", example: { ko: "번호가 몇 번이에요?", en: "What is the number?", form: "번호 + 가 (subject particle); 몇 + 번 (determiner plus counter); 이에요 (present, polite casual, question)" } },
    "kv0908": { korean: "파티", note: "A party. Held with 하다 (파티를 해요) and invited to with 초대하다.", example: { ko: "생일 파티를 해요.", en: "I'm having a birthday party.", form: "파티 + 를 (object particle); 하다 → 해요 (present, polite casual)" } },
    "kv0916": { korean: "춤추다", note: "To dance — 춤 and 추다 written as one word. The split form 춤을 추다 means exactly the same thing and is more common in careful writing.", example: { ko: "친구하고 춤춰요.", en: "I dance with a friend.", form: "친구 + 하고 (companion particle); 춤추다 → 춤춰요 (ㅜ + 어 contracts to 워; present, polite casual)" } },
    "kv0918": { korean: "초대하다", note: "To invite. The guest takes 을/를 and the event takes 에: 친구를 파티에 초대해요.", example: { ko: "친구를 파티에 초대해요.", en: "I invite a friend to the party.", form: "친구 + 를 (object particle); 파티 + 에 (event particle); 초대하다 → 초대해요 (present, polite casual)" } },
    "kv0940": { korean: "초대", note: "An invitation. Used as 초대를 하다 or the verb 초대하다; receiving one is 초대를 받다.", example: { ko: "초대를 받았어요.", en: "I received an invitation.", form: "초대 + 를 (object particle); 받다 → 받았어요 (past, polite casual)" } },
    "kv1070": { korean: "세계", note: "The world, as in the whole globe: 세계 여행, 전 세계. 세상 is the world as human society, so 세계 is the geographic one.", example: { ko: "세계 여행을 하고 싶어요.", en: "I want to travel the world.", form: "세계 여행 + 을 (object particle); 하다 + -고 싶다 → 하고 싶어요 (desire pattern; present, polite casual)" } },
    "kv1249": { korean: "들어서다", note: "To step into or enter — 들다 (to enter) plus 서다 (to stand). The place takes 에: 방에 들어서요. The everyday verb is 들어가다.", example: { ko: "교실에 들어서요.", en: "I step into the classroom.", form: "교실 + 에 (destination particle); 들어서다 → 들어서요 (present, polite casual)" } },
    "kv1348": { korean: "원하다", note: "To want something — it takes a noun object with 을/를: 돈을 원해요. To want to *do* something, use the verb ending -고 싶다 instead: 가고 싶어요.", example: { ko: "저는 새 가방을 원해요.", en: "I want a new bag.", form: "가방 + 을 (object particle); 원하다 → 원해요 (present, polite casual — for a noun, unlike -고 싶다 for a verb)" } },
    "kv1529": { korean: "알맞다", note: "To be suitable or fitting — the word used in exercise instructions: 알맞은 것을 고르세요 ('choose the right one'). Its modifying form is 알맞은.", example: { ko: "알맞은 답을 고르세요.", en: "Choose the correct answer.", form: "알맞다 → 알맞은 (noun-modifying form); 고르다 + -세요 → 고르세요 (polite request)" } },
    "kv1548": { korean: "그리", note: "'That much' or 'so' — nearly always in a negative sentence: 그리 어렵지 않아요 ('not that difficult'). In a plain positive statement it sounds wrong.", example: { ko: "그리 어렵지 않아요.", en: "It's not that difficult.", form: "그리 modifies the predicate; 어렵다 + -지 않다 → 어렵지 않아요 (long negation; present, polite casual)" } },
    "kv1612": { korean: "어떻게", note: "How — the adverb form of 어떻다, placed before the verb: 어떻게 가요? It also softens polite questions: 성함이 어떻게 되세요?", example: { ko: "학교에 어떻게 가요?", en: "How do you get to school?", form: "어떻게 modifies the verb (adverb form of 어떻다); 가다 → 가요 (present, polite casual, question)" } },
    "kv1627": { korean: "용돈", note: "Pocket money or an allowance. Parents 용돈을 주다 and children 용돈을 받다.", example: { ko: "부모님한테서 용돈을 받아요.", en: "I get an allowance from my parents.", form: "부모님 + 한테서 (source particle); 받다 → 받아요 (present, polite casual)" } },
    "kv1628": { korean: "쌀국수", note: "Rice noodles — the Korean name for Vietnamese pho, from 쌀 (uncooked rice) + 국수 (noodles). Counted by the bowl with 그릇.", example: { ko: "쌀국수를 먹어요.", en: "I eat rice noodles.", form: "쌀국수 + 를 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv1629": { korean: "설거지하다", note: "To wash the dishes. In careful writing the noun form 설거지를 하다 is preferred, but the compound verb is common in speech.", example: { ko: "저녁 후에 설거지해요.", en: "I wash the dishes after dinner.", form: "저녁 + 후 + 에 (time phrase); 설거지하다 → 설거지해요 (present, polite casual)" } },
    "kv1630": { korean: "팝콘", note: "Popcorn. Bought by the bucket at the cinema and counted with 개 or 통.", example: { ko: "영화관에서 팝콘을 먹어요.", en: "I eat popcorn at the cinema.", form: "영화관 + 에서 (where the action happens); 먹다 → 먹어요 (present, polite casual)" } },
    "kv1631": { korean: "사장님", note: "The honorific for a company boss or shop owner — 사장 plus 님. This is the form you actually use when speaking to or about them.", example: { ko: "사장님께서 말씀하셨어요.", en: "The boss spoke.", form: "사장님 + 께서 (honorific subject particle); 말씀하다 + -시- → 말씀하셨어요 (honorific past, polite casual)" } },
    "kv1632": { korean: "어학당", note: "A language institute — the university-attached Korean programmes foreign students enrol in. 당 marks a hall or institution.", example: { ko: "어학당에서 한국어를 배워요.", en: "I learn Korean at the language institute.", form: "어학당 + 에서 (where the action happens); 배우다 → 배워요 (present, polite casual)" } },
    "kv1633": { korean: "세계 여행", note: "A trip around the world — 세계 plus 여행, two nouns with a space and no particle between them.", example: { ko: "세계 여행을 가고 싶어요.", en: "I want to take a trip around the world.", form: "세계 여행 + 을 (object particle); 가다 + -고 싶다 → 가고 싶어요 (desire pattern)" } },
    "kv1634": { korean: "여비", note: "Travel expenses — 여 (travel) + 비 (cost). The same 비 appears in 학비 (tuition) and 교통비 (transport costs).", example: { ko: "여비를 모아요.", en: "I save up travel money.", form: "여비 + 를 (object particle); 모으다 → 모아요 (ㅡ-irregular; present, polite casual)" } },
    "kv1635": { korean: "고향 친구", note: "A friend from your hometown — 고향 plus 친구, two nouns with a space. Korean builds this kind of relationship phrase by simple juxtaposition.", example: { ko: "고향 친구를 만나요.", en: "I meet a friend from my hometown.", form: "고향 친구 + 를 (object particle); 만나다 → 만나요 (present, polite casual)" } },
    "kv1636": { korean: "베트남 음악", note: "Vietnamese music — country plus noun with a space, the same pattern as 한국 음식 and 한국 영화. Listened to with 듣다.", example: { ko: "베트남 음악을 들어요.", en: "I listen to Vietnamese music.", form: "베트남 음악 + 을 (object particle); 듣다 → 들어요 (ㄷ-irregular; present, polite casual)" } },
    "kv1637": { korean: "한 통", note: "'One carton' — 한 plus the counter 통, for containers and tubs: 우유 한 통, 아이스크림 한 통. The same 통 as in 필통.", example: { ko: "우유 한 통을 샀어요.", en: "I bought one carton of milk.", form: "우유 + 한 통 (noun, then number plus counter) + 을 (object particle); 사다 → 샀어요 (past, polite casual)" } },
    "kv1638": { korean: "춤을 추다", note: "To dance — the split form of 춤추다, and the more standard one in writing. 춤 is the only object 추다 ever takes.", example: { ko: "파티에서 춤을 춰요.", en: "I dance at the party.", form: "춤 + 을 (object particle); 추다 → 춰요 (ㅜ + 어 contracts to 워; present, polite casual)" } },
    "kv1639": { korean: "고추장", note: "Gochujang — fermented red chilli paste, the base of 떡볶이 and 비빔밥. The 장 here means a fermented paste, as in 된장 and 간장.", example: { ko: "고추장을 넣어요.", en: "I add gochujang.", form: "고추장 + 을 (object particle); 넣다 → 넣어요 (present, polite casual)" } },
    "kv1640": { korean: "양파", note: "An onion — literally 'Western 파', since 파 is the spring onion Korea already had. Counted with 개.", example: { ko: "양파를 썰어요.", en: "I slice the onion.", form: "양파 + 를 (object particle); 썰다 → 썰어요 (present, polite casual)" } },
    "kv1641": { korean: "어묵", note: "Fish cake — the sheets and skewers sold at street stalls. Also called 오뎅 from Japanese, though 어묵 is the standard word.", example: { ko: "어묵을 먹어요.", en: "I eat fish cake.", form: "어묵 + 을 (object particle); 먹다 → 먹어요 (present, polite casual)" } },
    "kv1642": { korean: "고추가루", note: "Chilli powder. The standard spelling is 고춧가루, with the linking ㅅ — this form appears in the source worksheet, so both are listed here.", example: { ko: "고춧가루를 조금 넣어요.", en: "I add a little chilli powder.", form: "고추가루 (source spelling) → 고춧가루 in the sentence + 를 (object particle); 넣다 → 넣어요 (present, polite casual)" } },
    "kv1643": { korean: "양배추", note: "Cabbage — again with the 양 prefix marking a Western import, as in 양파. Korean napa cabbage is 배추.", example: { ko: "양배추를 사요.", en: "I buy cabbage.", form: "양배추 + 를 (object particle); 사다 → 사요 (present, polite casual)" } },
    "kv1644": { korean: "수영복", note: "A swimsuit — 수영 plus the clothing suffix 복, as in 교복 (school uniform) and 한복. Worn with 입다.", example: { ko: "수영복을 입어요.", en: "I wear a swimsuit.", form: "수영복 + 을 (object particle); 입다 → 입어요 (present, polite casual)" } },
    "kv1645": { korean: "수영 모자", note: "A swimming cap — 수영 plus 모자, two nouns with a space. Like any hat it is worn with 쓰다, not 입다.", example: { ko: "수영 모자를 써요.", en: "I wear a swimming cap.", form: "수영 모자 + 를 (object particle); 쓰다 → 써요 (ㅡ-irregular; present, polite casual — headwear takes 쓰다)" } },
    "kv1646": { korean: "물안경", note: "Swimming goggles — 물 (water) plus 안경 (glasses). Like glasses they are worn with 쓰다.", example: { ko: "물안경을 써요.", en: "I wear swimming goggles.", form: "물안경 + 을 (object particle); 쓰다 → 써요 (present, polite casual)" } },
    "kv1647": { korean: "떡볶이 떡", note: "The cylindrical rice cakes used for tteokbokki — 떡볶이 plus 떡, naming the ingredient by the dish it belongs to.", example: { ko: "떡볶이 떡을 사요.", en: "I buy tteokbokki rice cakes.", form: "떡볶이 떡 + 을 (object particle); 사다 → 사요 (present, polite casual)" } },
    "kv1757": { korean: "고춧가루", note: "Red chilli powder — the standard spelling, with the linking ㅅ between 고추 and 가루 (powder). Essential to kimchi.", example: { ko: "김치에 고춧가루를 넣어요.", en: "I put chilli powder in the kimchi.", form: "김치 + 에 (target particle); 고춧가루 + 를 (object particle); 넣다 → 넣어요 (present, polite casual)" } },
    "kv1768": { korean: "떡볶이", note: "Tteokbokki — rice cakes in a sweet-spicy gochujang sauce, from 떡 + 볶다 (to stir-fry). Counted by the portion with 인분.", example: { ko: "떡볶이가 매워요.", en: "The tteokbokki is spicy.", form: "떡볶이 + 가 (subject particle); 맵다 → 매워요 (ㅂ-irregular; present, polite casual)" } },
    "kv1789": { korean: "수업 시간", note: "Class time — 수업 plus 시간, two nouns with a space. It means the period during which class runs, so 수업 시간에 means 'during class'.", example: { ko: "수업 시간에 질문했어요.", en: "I asked a question during class.", form: "수업 시간 + 에 (time particle); 질문하다 → 질문했어요 (past, polite casual)" } },
    "kv1832": { korean: "컴퓨터하다", note: "To use the computer — a colloquial noun-plus-하다 verb, the same pattern that gives 공부하다 and 운동하다. In careful writing 컴퓨터를 사용하다 is better.", example: { ko: "저녁에 컴퓨터해요.", en: "I use the computer in the evening.", form: "저녁 + 에 (time particle); 컴퓨터하다 → 컴퓨터해요 (present, polite casual)" } },

    "kv0690": { korean: "오토바이", note: "A motorcycle or scooter — from the Japanese rendering of 'auto bike', not from English 'motorcycle'. Ridden with 타다 like any vehicle.", example: { ko: "오토바이를 타요.", en: "I ride a motorcycle.", form: "오토바이 + 를 (object particle); 타다 → 타요 (present, polite casual)" } },
    "kv0693": { korean: "외식", note: "Eating out — 외 (outside) + 식 (meal). The verb is 외식하다, and it means the occasion of dining out rather than the food itself.", example: { ko: "주말에 외식해요.", en: "We eat out at the weekend.", form: "주말 + 에 (time particle); 외식하다 → 외식해요 (present, polite casual)" } },

    // =========================================================================
    // TOPIK vocabulary references. Keyed by the Korean headword rather than a
    // shared-vocab id, since several of these entries (particle-slot patterns,
    // collocations) exist only in the TOPIK word lists.
    // =========================================================================

    // ------------------------------------------------------------- TOPIK I
    "항상": { korean: "항상", note: "Always — a frequency adverb placed before the verb. The frequency set runs 항상 > 자주 > 보통 > 가끔 > 거의 안 > 전혀 안. 언제나 is its close synonym.", example: { ko: "저는 항상 아침을 먹어요.", en: "I always eat breakfast.", form: "항상 modifies the verb; 먹다 → 먹어요 (present, polite casual)" } },
    "자주": { korean: "자주", note: "Often. It describes how frequently something recurs, so it pairs with the present tense for habits: 자주 만나요. For 'many times' as a count, use 여러 번.", example: { ko: "친구를 자주 만나요.", en: "I meet my friend often.", form: "자주 modifies the verb; 만나다 → 만나요 (present, polite casual)" } },
    "가끔": { korean: "가끔", note: "Sometimes, occasionally — less often than 자주. 가끔씩 adds a touch of casualness without changing the meaning.", example: { ko: "가끔 영화를 봐요.", en: "I sometimes watch a movie.", form: "가끔 modifies the verb; 보다 → 봐요 (present, polite casual)" } },
    "보통": { korean: "보통", note: "Usually. It is a noun by origin, so it can also mean 'the ordinary' (보통 사람 = an average person), but its everyday job is the frequency adverb sitting before the verb.", example: { ko: "보통 일곱 시에 일어나요.", en: "I usually get up at seven.", form: "보통 modifies the clause; 일곱 시 + 에 (time particle); 일어나다 → 일어나요 (present, polite casual)" } },
    "천천히": { korean: "천천히", note: "Slowly — the -히 adverb from 천천하다. It is the polite thing to ask of a fast speaker: 천천히 말해 주세요. Its opposite is 빨리.", example: { ko: "천천히 말해 주세요.", en: "Please speak slowly.", form: "천천히 modifies the verb; 말하다 + -아/어 주다 + -세요 → 말해 주세요 (request for a favour; polite)" } },
    "잘": { korean: "잘", note: "Well — both skill (잘해요 = I do it well) and wellbeing (잘 지내요 = I'm doing fine). Its negative is 잘 못해요, and 못 alone means cannot at all.", example: { ko: "한국어를 잘해요.", en: "I speak Korean well.", form: "잘 + 하다 written together as 잘하다 → 잘해요 (present, polite casual)" } },
    "말하다": { korean: "말하다", note: "To speak or say. The listener takes 한테 or 에게, and the content takes -고: 간다고 말했어요. Its honorific is 말씀하시다.", example: { ko: "친구한테 말했어요.", en: "I told my friend.", form: "친구 + 한테 (recipient particle); 말하다 → 말했어요 (past, polite casual)" } },
    "서다": { korean: "서다", note: "To stand, and also 'to stop' for vehicles (버스가 섰어요). Its opposite for people is 앉다. The causative 세우다 means to stand something up or bring it to a halt.", example: { ko: "여기에 서 주세요.", en: "Please stand here.", form: "여기 + 에 (location particle); 서다 + -아/어 주다 + -세요 → 서 주세요 (identical ㅓ merges; polite request)" } },
    "빠르다": { korean: "빠르다", note: "Fast. A 르-irregular: the ㄹ doubles before a vowel ending, giving 빨라요. Its adverb form is 빨리, and its opposite is 느리다.", example: { ko: "기차가 빨라요.", en: "The train is fast.", form: "기차 + 가 (subject particle); 빠르다 → 빨라요 (르-irregular; present, polite casual)" } },
    "느리다": { korean: "느리다", note: "Slow — the opposite of 빠르다. Its adverb is 느리게 or 천천히. Careful with 늘리다 (to increase), which differs by one vowel.", example: { ko: "인터넷이 느려요.", en: "The internet is slow.", form: "인터넷 + 이 (subject particle); 느리다 → 느려요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "어디": { korean: "어디", note: "Where. It takes the particle the sentence needs: 어디에 가요? (destination), 어디에서 만나요? (where an action happens), 어디예요? (identity). Choosing 에 vs 에서 is the usual sticking point.", example: { ko: "어디에서 만나요?", en: "Where shall we meet?", form: "어디 + 에서 (where the action happens); 만나다 → 만나요 (present, polite casual, question)" } },
    "고기": { korean: "고기", note: "Meat. The animal names it: 소고기 (beef), 돼지고기 (pork), 닭고기 (chicken). Note that 물고기 is a live fish, while fish as food is 생선.", example: { ko: "고기를 구워요.", en: "I grill the meat.", form: "고기 + 를 (object particle); 굽다 → 구워요 (ㅂ-irregular; present, polite casual)" } },
    "라면": { korean: "라면", note: "Instant noodles. You 'boil' them rather than cook them: 라면을 끓여요. Counted by the packet with 개 or by the bowl with 그릇.", example: { ko: "라면을 끓여요.", en: "I make instant noodles.", form: "라면 + 을 (object particle); 끓이다 → 끓여요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "카드": { korean: "카드", note: "A card — a bank card, a greeting card, or a membership card. Paying by card is 카드로 계산해요, with the means particle 로.", example: { ko: "카드로 계산할게요.", en: "I'll pay by card.", form: "카드 + 로 (means particle after a vowel); 계산하다 + -(으)ㄹ게요 → 계산할게요 (speaker's intention, polite casual)" } },
    "현금": { korean: "현금", note: "Cash — the counterpart of 카드 at the till. Paying in cash takes 로/으로: 현금으로 계산해요.", example: { ko: "현금으로 계산해요.", en: "I pay in cash.", form: "현금 + 으로 (means particle after a batchim); 계산하다 → 계산해요 (present, polite casual)" } },
    "얼마": { korean: "얼마", note: "How much — for price above all: 얼마예요? For duration or degree use 얼마나 instead, which is the adverb form: 얼마나 걸려요?", example: { ko: "이거 얼마예요?", en: "How much is this?", form: "얼마 + 예요 (이다 after a vowel; present, polite casual, question)" } },
    "빨간색": { korean: "빨간색", note: "Red. Colour nouns are built from the adjective's modifying form plus 색: 빨갛다 → 빨간 + 색. Before a noun you can drop 색: 빨간 가방.", example: { ko: "빨간색 가방을 샀어요.", en: "I bought a red bag.", form: "빨간색 + 가방 (noun compound, no particle) + 을 (object particle); 사다 → 샀어요 (past, polite casual)" } },
    "파란색": { korean: "파란색", note: "Blue, from 파랗다 → 파란 + 색. Korean traditionally lets 파랗다 cover green things too, which is why traffic lights are 파란불.", example: { ko: "파란색을 좋아해요.", en: "I like blue.", form: "파란색 + 을 (object particle); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "노란색": { korean: "노란색", note: "Yellow, from 노랗다 → 노란 + 색. The same ㅎ-irregular pattern as 빨갛다 and 파랗다.", example: { ko: "노란색 꽃이 예뻐요.", en: "The yellow flower is pretty.", form: "노란색 + 꽃 (noun compound) + 이 (subject particle); 예쁘다 → 예뻐요 (ㅡ-irregular; present, polite casual)" } },
    "초록색": { korean: "초록색", note: "Green. Unlike 빨간색 and 파란색 it is built on the Sino-Korean root 초록 rather than an adjective, so there is no 초록 + 은 modifying form — say 초록색 나무.", example: { ko: "초록색 나무가 많아요.", en: "There are many green trees.", form: "초록색 + 나무 (noun compound) + 가 (subject particle); 많다 → 많아요 (present, polite casual)" } },
    "검은색": { korean: "검은색", note: "Black, from 검다 → 검은 + 색. The loanword 블랙 appears in fashion and coffee, but 검은색 is the standard word.", example: { ko: "검은색 바지를 입어요.", en: "I wear black trousers.", form: "검은색 + 바지 (noun compound) + 를 (object particle); 입다 → 입어요 (present, polite casual)" } },
    "흰색": { korean: "흰색", note: "White, from 희다 → 흰 + 색. 하얀색 means the same thing and is more common in speech.", example: { ko: "흰색 옷을 좋아해요.", en: "I like white clothes.", form: "흰색 + 옷 (noun compound) + 을 (object particle); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "비": { korean: "비", note: "Rain. It 'comes' rather than falls: 비가 와요, or 비가 내려요 in more written style. Never 비가 떨어져요.", example: { ko: "비가 와요.", en: "It's raining.", form: "비 + 가 (subject particle); 오다 → 와요 (present, polite casual — rain 'comes' in Korean)" } },
    "눈": { korean: "눈", note: "Snow, and also an eye — distinguished in speech by pitch, in writing by context. Snow, like rain, 'comes': 눈이 와요. Eyes take 감다 for closing.", example: { ko: "눈이 와요.", en: "It's snowing.", form: "눈 + 이 (subject particle); 오다 → 와요 (present, polite casual)" } },
    "바람": { korean: "바람", note: "Wind. It takes the verb 불다: 바람이 불어요, never 바람이 와요. The homograph 바람 also means a wish (바라다) or an affair.", example: { ko: "바람이 불어요.", en: "The wind is blowing.", form: "바람 + 이 (subject particle); 불다 → 불어요 (present, polite casual)" } },
    "카페": { korean: "카페", note: "A café. 커피숍 means the same; 카페 is the more current word and also names online communities (네이버 카페).", example: { ko: "카페에서 공부해요.", en: "I study at the café.", form: "카페 + 에서 (where the action happens); 공부하다 → 공부해요 (present, polite casual)" } },
    "저녁": { korean: "저녁", note: "Evening, and also dinner — the same double duty as 아침 and 점심. 저녁을 먹어요 is eating dinner; 저녁에 is in the evening.", example: { ko: "저녁에 저녁을 먹어요.", en: "I eat dinner in the evening.", form: "저녁 + 에 (time particle) and 저녁 + 을 (object particle) — one noun, both roles; 먹다 → 먹어요 (present, polite casual)" } },
    "밤": { korean: "밤", note: "Night — the late hours after 저녁. It is also the word for a chestnut, distinguished by context. 밤에 covers 'at night'.", example: { ko: "밤에 잠이 안 와요.", en: "I can't sleep at night.", form: "밤 + 에 (time particle); 잠 + 이 (subject particle); 안 + 오다 → 안 와요 (short negation; present, polite casual)" } },
    "이": { korean: "이", note: "Two in the Sino-Korean system — for dates, money, and phone numbers: 이월, 이백 원. Also the determiner 이 ('this'), the noun 이 (tooth), and the subject particle. Position decides which one you are looking at.", example: { ko: "이월에 시험이 있어요.", en: "There is an exam in February.", form: "이 + 월 (Sino-Korean number plus counter) + 에 (time particle); 있다 → 있어요 (present, polite casual)" } },
    "미안합니다": { korean: "미안합니다", note: "'Sorry' in the formal style — lighter than 죄송합니다, and the right weight among equals. Its casual form is 미안해 for friends.", example: { ko: "늦어서 미안합니다.", en: "I'm sorry for being late.", form: "늦다 + -어서 → 늦어서 (reason link); 미안하다 → 미안합니다 (present, formal polite)" } },
    "맞아요": { korean: "맞아요", note: "'That's right' — agreeing with what was said. From 맞다 (to be correct). To disagree, say 아니에요 or 틀려요.", example: { ko: "네, 맞아요.", en: "Yes, that's right.", form: "맞다 → 맞아요 (present, polite casual)" } },
    "아니에요": { korean: "아니에요", note: "'It's not' — the polite present of 아니다, used to correct a statement (학생이 아니에요) and, on its own, to wave off thanks or praise.", example: { ko: "저는 학생이 아니에요.", en: "I am not a student.", form: "학생 + 이 (the thing being denied takes 이/가); 아니다 → 아니에요 (present, polite casual)" } },
    "처음 뵙겠습니다": { korean: "처음 뵙겠습니다", note: "'How do you do' — the most formal first-meeting greeting, from 뵙다, the humble form of 만나다. Used in business introductions; among peers 반갑습니다 is enough.", example: { ko: "처음 뵙겠습니다. 김민수입니다.", en: "How do you do. I'm Kim Minsu.", form: "뵙다 + -겠- + -습니다 → 뵙겠습니다 (humble, formal polite; -겠- softens it into a polite formula)" } },
    "반갑습니다": { korean: "반갑습니다", note: "'Nice to meet you' in the formal style, from the ㅂ-irregular 반갑다. Its polite casual form is 반가워요, and the fuller greeting is 만나서 반갑습니다.", example: { ko: "만나서 반갑습니다.", en: "Nice to meet you.", form: "만나다 + -아서 → 만나서 (reason link); 반갑다 → 반갑습니다 (present, formal polite)" } },
    "성": { korean: "성", note: "A family name. Korean order is family name first: 김민수 has 성 김 and 이름 민수. The honorific for the whole name is 성함.", example: { ko: "성이 뭐예요?", en: "What is your family name?", form: "성 + 이 (subject particle); 뭐 + 예요 (present, polite casual, question)" } },
    "국적": { korean: "국적", note: "Nationality — the formal word on documents. In conversation people ask 어느 나라 사람이에요? instead.", example: { ko: "국적이 어떻게 되세요?", en: "What is your nationality?", form: "국적 + 이 (subject particle); 되다 + -세요 → 되세요 (honorific present, polite casual, question)" } },
    "남자": { korean: "남자", note: "A man or boy. As with 여자, 남자 친구 written as one unit means boyfriend, while a male friend is 남자 사람 친구. The formal word is 남성.", example: { ko: "저 남자는 제 오빠예요.", en: "That man is my older brother.", form: "남자 + 는 (topic particle); 예요 (present, polite casual)" } },

    // --------------------------------------------------- TOPIK II level 3
    "경험": { korean: "경험", note: "Experience — something lived through. The verb is 경험하다, and 'to gain experience' is 경험을 쌓다 ('to stack up experience'), not 얻다.", example: { ko: "좋은 경험을 했어요.", en: "I had a good experience.", form: "경험 + 을 (object particle); 하다 → 했어요 (past, polite casual)" } },
    "문화": { korean: "문화", note: "Culture. Very productive in compounds: 문화 차이 (cultural difference), 전통 문화, 대중문화. Note that 문화 is society-wide, while 문명 is civilisation.", example: { ko: "한국 문화를 배워요.", en: "I learn about Korean culture.", form: "한국 문화 + 를 (object particle); 배우다 → 배워요 (present, polite casual)" } },
    "사회": { korean: "사회", note: "Society. It heads a large family of TOPIK II compounds: 사회 문제, 사회생활, 사회적. The adjective form is 사회적이다.", example: { ko: "사회 문제가 심각해요.", en: "The social problem is serious.", form: "사회 문제 (noun compound) + 가 (subject particle); 심각하다 → 심각해요 (present, polite casual)" } },
    "경제": { korean: "경제", note: "The economy. Compounds: 경제 성장, 경제적 (economical), 경제학 (economics). Do not confuse it with 경쟁 (competition).", example: { ko: "경제가 발전했어요.", en: "The economy has developed.", form: "경제 + 가 (subject particle); 발전하다 → 발전했어요 (past, polite casual)" } },
    "환경": { korean: "환경", note: "The environment — both the natural one (환경 보호) and one's surroundings (가정 환경). 환경 문제 and 환경 오염 are standard TOPIK collocations.", example: { ko: "환경을 보호해야 해요.", en: "We must protect the environment.", form: "환경 + 을 (object particle); 보호하다 + -아야 하다 → 보호해야 해요 (obligation; present, polite casual)" } },
    "건강": { korean: "건강", note: "Health. As an adjective it is 건강하다 ('to be healthy'), which describes people, not things — food that is good for you is 건강에 좋다.", example: { ko: "건강이 제일 중요해요.", en: "Health is the most important thing.", form: "건강 + 이 (subject particle); 중요하다 → 중요해요 (present, polite casual)" } },
    "습관": { korean: "습관", note: "A habit. Forming one is 습관을 기르다 or 습관이 되다; a bad habit is 나쁜 습관. Eating habits specifically are 식습관.", example: { ko: "좋은 습관을 길러요.", en: "I build good habits.", form: "습관 + 을 (object particle); 기르다 → 길러요 (르-irregular; present, polite casual)" } },
    "계획": { korean: "계획", note: "A plan. Making one is 계획을 세우다 ('to erect a plan'), not 만들다 — this collocation is tested often.", example: { ko: "여행 계획을 세워요.", en: "I make a travel plan.", form: "계획 + 을 (object particle); 세우다 → 세워요 (ㅜ + 어 contracts to 워; present, polite casual)" } },
    "목적": { korean: "목적", note: "A purpose — the reason something is done. 목표 is a goal you aim at, so a trip has a 목적 while a learner has a 목표.", example: { ko: "여행의 목적이 뭐예요?", en: "What is the purpose of the trip?", form: "여행 + 의 (possessive particle); 목적 + 이 (subject particle); 뭐 + 예요 (question, polite casual)" } },
    "기회": { korean: "기회", note: "An opportunity. It comes and is seized: 기회가 있다, 기회를 잡다. 'If I get the chance' is 기회가 있으면.", example: { ko: "좋은 기회가 있어요.", en: "There is a good opportunity.", form: "기회 + 가 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "방법": { korean: "방법", note: "A method or way of doing something. 'How' as a question is 어떻게, but 'a way to do it' is 방법: 좋은 방법이 있어요?", example: { ko: "좋은 방법이 있어요?", en: "Is there a good method?", form: "방법 + 이 (subject particle); 있다 → 있어요 (present, polite casual, question)" } },
    "결과": { korean: "결과", note: "A result. It 'appears' rather than comes out: 결과가 나오다 or 결과가 나타나다. '(As) a result' is 그 결과 or -(으)ㄴ 결과.", example: { ko: "시험 결과가 나왔어요.", en: "The exam results came out.", form: "시험 결과 (noun compound) + 가 (subject particle); 나오다 → 나왔어요 (past, polite casual)" } },
    "이유": { korean: "이유", note: "A reason. 'The reason is that…' is -기 때문이에요 or 이유는 -기 때문이에요. 원인 is a cause in the scientific sense, while 이유 is the reason a person gives.", example: { ko: "이유가 뭐예요?", en: "What is the reason?", form: "이유 + 가 (subject particle); 뭐 + 예요 (present, polite casual, question)" } },
    "해결": { korean: "해결", note: "A solution or resolution. The verb is 해결하다, and the problem solved takes 을/를: 문제를 해결해요. 해결책 is the concrete solution.", example: { ko: "문제 해결이 어려워요.", en: "Solving the problem is difficult.", form: "문제 해결 (noun compound) + 이 (subject particle); 어렵다 → 어려워요 (ㅂ-irregular; present, polite casual)" } },
    "관계": { korean: "관계", note: "A relationship or connection. The other party takes 와/과: 친구와의 관계. '(It) has nothing to do with' is 관계가 없다.", example: { ko: "두 사람의 관계가 좋아요.", en: "The relationship between the two is good.", form: "사람 + 의 (possessive particle); 관계 + 가 (subject particle); 좋다 → 좋아요 (present, polite casual)" } },
    "책임": { korean: "책임", note: "Responsibility. You 'carry' it: 책임을 지다. 책임감 is the sense of responsibility a person has, so a job has 책임 and a person has 책임감.", example: { ko: "책임을 져야 해요.", en: "You have to take responsibility.", form: "책임 + 을 (object particle); 지다 + -어야 하다 → 져야 해요 (obligation; present, polite casual)" } },
    "실수": { korean: "실수", note: "A mistake — an accidental slip. The verb is 실수하다, and 'by mistake' is 실수로. A wrong answer on a test is 틀리다, not 실수.", example: { ko: "실수를 했어요.", en: "I made a mistake.", form: "실수 + 를 (object particle); 하다 → 했어요 (past, polite casual)" } },
    "과제": { korean: "과제", note: "An assignment, and also a task or challenge in formal writing (사회적 과제). For school homework 숙제 is the everyday word.", example: { ko: "과제를 제출했어요.", en: "I submitted the assignment.", form: "과제 + 를 (object particle); 제출하다 → 제출했어요 (past, polite casual)" } },
    "성적": { korean: "성적", note: "Grades or academic results. 성적이 좋다 / 나쁘다 is how you describe them; 점수 is the numeric score on one test.", example: { ko: "성적이 올랐어요.", en: "My grades went up.", form: "성적 + 이 (subject particle); 오르다 → 올랐어요 (르-irregular; past, polite casual)" } },
    "발표": { korean: "발표", note: "A presentation, and also an announcement of results. The verb is 발표하다: 결과를 발표해요.", example: { ko: "내일 발표를 해요.", en: "I give a presentation tomorrow.", form: "발표 + 를 (object particle); 하다 → 해요 (present covering a near-future plan; polite casual)" } },
    "연구": { korean: "연구", note: "Research. 연구하다 is to research and 연구를 수행하다 ('to carry out research') is the formal collocation used in academic writing.", example: { ko: "연구를 시작했어요.", en: "I started the research.", form: "연구 + 를 (object particle); 시작하다 → 시작했어요 (past, polite casual)" } },
    "졸업": { korean: "졸업", note: "Graduation. The school graduated from takes 을/를, not 에서: 대학교를 졸업했어요. Its opposite is 입학.", example: { ko: "대학교를 졸업했어요.", en: "I graduated from university.", form: "대학교 + 를 (object particle — 졸업하다 takes 을/를, not 에서); 졸업하다 → 졸업했어요 (past, polite casual)" } },
    "장학금": { korean: "장학금", note: "A scholarship. You receive one with 받다 and apply for it with 신청하다. The 금 suffix marks sums of money, as in 요금 and 벌금.", example: { ko: "장학금을 받았어요.", en: "I received a scholarship.", form: "장학금 + 을 (object particle); 받다 → 받았어요 (past, polite casual)" } },
    "회의": { korean: "회의", note: "A meeting, pronounced [회이]. It is held with 하다 and attended with 참석하다: 회의에 참석해요, where the meeting takes 에.", example: { ko: "회의에 참석해요.", en: "I attend the meeting.", form: "회의 + 에 (event particle); 참석하다 → 참석해요 (present, polite casual)" } },
    "업무": { korean: "업무", note: "Work in the sense of duties and tasks — the formal office word. 일 is the everyday equivalent, and 직업 is the occupation itself.", example: { ko: "업무가 많아요.", en: "I have a lot of work.", form: "업무 + 가 (subject particle); 많다 → 많아요 (present, polite casual)" } },
    "월급": { korean: "월급", note: "A monthly salary — 월 (month) + 급 (pay). It is received with 받다. An hourly wage is 시급 and an annual salary 연봉.", example: { ko: "월급을 받았어요.", en: "I received my salary.", form: "월급 + 을 (object particle); 받다 → 받았어요 (past, polite casual)" } },
    "출근": { korean: "출근", note: "Going to work. The verb 출근하다 is intransitive, so the workplace takes 에 and never 을/를. Its opposite is 퇴근.", example: { ko: "여덟 시에 출근해요.", en: "I go to work at eight.", form: "여덟 시 + 에 (time particle); 출근하다 → 출근해요 (present, polite casual)" } },
    "퇴근": { korean: "퇴근", note: "Leaving work for the day — the counterpart of 출근. 퇴근 후에 means 'after work', and 퇴근 시간 is knocking-off time.", example: { ko: "여섯 시에 퇴근해요.", en: "I leave work at six.", form: "여섯 시 + 에 (time particle); 퇴근하다 → 퇴근해요 (present, polite casual)" } },
    "이사": { korean: "이사", note: "Moving house. The verb 이사하다 takes 로/으로 for where you move to: 서울로 이사해요. The homograph 이사 also means a company director.", example: { ko: "다음 달에 이사해요.", en: "I move house next month.", form: "다음 달 + 에 (time particle); 이사하다 → 이사해요 (present, polite casual)" } },
    "계절": { korean: "계절", note: "A season. Korea's four are 봄, 여름, 가을, 겨울, and asking a favourite uses 무슨: 무슨 계절을 좋아해요?", example: { ko: "무슨 계절을 좋아해요?", en: "Which season do you like?", form: "무슨 + 계절 (determiner before a noun) + 을 (object particle); 좋아하다 → 좋아해요 (question, polite casual)" } },
    "취미": { korean: "취미", note: "A hobby. Asking about one is 취미가 뭐예요?, and the answer usually uses the -는 것 noun form: 취미는 책을 읽는 거예요.", example: { ko: "취미가 뭐예요?", en: "What is your hobby?", form: "취미 + 가 (subject particle); 뭐 + 예요 (present, polite casual, question)" } },
    "신청하다": { korean: "신청하다", note: "To apply for or sign up for. What you apply for takes 을/를: 장학금을 신청해요. Applying to an institution takes 에: 대학원에 지원하다 uses 지원하다 instead.", example: { ko: "수업을 신청했어요.", en: "I registered for the class.", form: "수업 + 을 (object particle); 신청하다 → 신청했어요 (past, polite casual)" } },
    "이용하다": { korean: "이용하다", note: "To use a service or facility — public transport, a library, a website. For using a physical tool, 사용하다 is the natural verb.", example: { ko: "지하철을 이용해요.", en: "I use the subway.", form: "지하철 + 을 (object particle); 이용하다 → 이용해요 (present, polite casual)" } },
    "참석하다": { korean: "참석하다", note: "To attend an event — a meeting, a wedding, a ceremony. The event takes 에, never 을/를. 참여하다 is broader: taking part in an activity.", example: { ko: "결혼식에 참석했어요.", en: "I attended the wedding.", form: "결혼식 + 에 (event particle); 참석하다 → 참석했어요 (past, polite casual)" } },
    "선택하다": { korean: "선택하다", note: "To choose or select from options. What you pick takes 을/를. 고르다 means the same in everyday speech; 선택하다 is the formal one.", example: { ko: "하나를 선택하세요.", en: "Please choose one.", form: "하나 + 를 (object particle); 선택하다 + -세요 → 선택하세요 (polite request)" } },
    "결정하다": { korean: "결정하다", note: "To decide. The decision takes 을/를 (날짜를 결정해요), or use -기로 하다 for deciding to do something: 가기로 했어요.", example: { ko: "날짜를 결정했어요.", en: "I decided on the date.", form: "날짜 + 를 (object particle); 결정하다 → 결정했어요 (past, polite casual)" } },
    "설명하다": { korean: "설명하다", note: "To explain. The thing explained takes 을/를 and the listener takes 한테 or 에게: 학생한테 문법을 설명해요.", example: { ko: "선생님이 문법을 설명해요.", en: "The teacher explains the grammar.", form: "문법 + 을 (object particle); 설명하다 → 설명해요 (present, polite casual)" } },
    "증가하다": { korean: "증가하다", note: "To increase — intransitive, so the thing rising takes 이/가: 인구가 증가해요. To increase something yourself, use 늘리다 or 증가시키다. Its opposite is 감소하다.", example: { ko: "인구가 증가했어요.", en: "The population increased.", form: "인구 + 가 (subject particle — 증가하다 is intransitive); 증가하다 → 증가했어요 (past, polite casual)" } },
    "감소하다": { korean: "감소하다", note: "To decrease — also intransitive, with 이/가: 사용이 감소해요. To reduce something, use 줄이다 or 감소시키다.", example: { ko: "학생 수가 감소했어요.", en: "The number of students decreased.", form: "수 + 가 (subject particle — 감소하다 is intransitive); 감소하다 → 감소했어요 (past, polite casual)" } },
    "발전하다": { korean: "발전하다", note: "To develop or advance — intransitive, with 이/가: 기술이 발전해요. To develop something, use 발전시키다, the causative.", example: { ko: "기술이 빠르게 발전해요.", en: "Technology develops quickly.", form: "기술 + 이 (subject particle); 빠르다 → 빠르게 (adverb form); 발전하다 → 발전해요 (present, polite casual)" } },
    "성공하다": { korean: "성공하다", note: "To succeed. What you succeed at takes 에: 사업에 성공했어요. Its opposite is 실패하다, which works the same way.", example: { ko: "사업에 성공했어요.", en: "I succeeded in business.", form: "사업 + 에 (target particle); 성공하다 → 성공했어요 (past, polite casual)" } },

    // --------------------------------------------------- TOPIK II level 4
    "변화": { korean: "변화", note: "Change as a noun. It happens on its own — 변화가 생기다, 변화하다 — while changing something yourself is 바꾸다 and something changing is 바뀌다.", example: { ko: "큰 변화가 생겼어요.", en: "A big change occurred.", form: "변화 + 가 (subject particle); 생기다 → 생겼어요 (past, polite casual)" } },
    "전통": { korean: "전통", note: "Tradition. Mostly used before another noun: 전통 문화, 전통 음식, 전통 시장. The adjective form is 전통적이다.", example: { ko: "전통 문화를 배워요.", en: "I learn about traditional culture.", form: "전통 문화 (noun compound) + 를 (object particle); 배우다 → 배워요 (present, polite casual)" } },
    "관심": { korean: "관심", note: "Interest in something. The fixed pattern is ~에 관심이 있다 — the topic takes 에, not 을/를. 'To take an interest' is 관심을 가지다.", example: { ko: "한국 역사에 관심이 있어요.", en: "I am interested in Korean history.", form: "역사 + 에 (target particle); 관심 + 이 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "영향": { korean: "영향", note: "Influence. Two set patterns: ~에 영향을 주다 (to influence) and ~에 영향을 미치다, the more formal one used in writing. Receiving influence is ~의 영향을 받다.", example: { ko: "날씨가 건강에 영향을 줘요.", en: "Weather influences health.", form: "건강 + 에 (target particle); 영향 + 을 (object particle); 주다 → 줘요 (present, polite casual)" } },
    "교육": { korean: "교육", note: "Education. The verb 교육하다 means to educate someone; receiving education is 교육을 받다. Compounds: 교육 제도, 교육 과정.", example: { ko: "교육이 중요해요.", en: "Education is important.", form: "교육 + 이 (subject particle); 중요하다 → 중요해요 (present, polite casual)" } },
    "지식": { korean: "지식", note: "Knowledge — what you know. It is acquired with 쌓다 or 얻다: 지식을 쌓아요. 정보 is information and 상식 is common sense.", example: { ko: "지식을 쌓아요.", en: "I build up knowledge.", form: "지식 + 을 (object particle); 쌓다 → 쌓아요 (present, polite casual)" } },
    "전공": { korean: "전공", note: "An academic major. The verb 전공하다 takes 을/를: 경제학을 전공해요. Asking is 전공이 뭐예요?", example: { ko: "한국어를 전공해요.", en: "I major in Korean.", form: "한국어 + 를 (object particle); 전공하다 → 전공해요 (present, polite casual)" } },
    "강의": { korean: "강의", note: "A lecture — the university word, where school class is 수업. Attending is 강의를 듣다 ('to listen to the lecture').", example: { ko: "강의를 들어요.", en: "I attend the lecture.", form: "강의 + 를 (object particle); 듣다 → 들어요 (ㄷ-irregular; present, polite casual)" } },
    "실력": { korean: "실력", note: "Ability or skill level — what you can actually do. It improves with 늘다 or 향상되다: 실력이 늘었어요. 능력 is capability in general.", example: { ko: "한국어 실력이 늘었어요.", en: "My Korean has improved.", form: "실력 + 이 (subject particle); 늘다 → 늘었어요 (past, polite casual)" } },
    "직업": { korean: "직업", note: "An occupation — what you do for a living. 직업이 뭐예요? is the standard question. 일 is the work itself and 회사 the employer.", example: { ko: "직업이 뭐예요?", en: "What is your occupation?", form: "직업 + 이 (subject particle); 뭐 + 예요 (present, polite casual, question)" } },
    "취업": { korean: "취업", note: "Getting a job. 취업하다 is to become employed and the company takes 에: 회사에 취업했어요. Its opposite is 실업 (unemployment).", example: { ko: "회사에 취업했어요.", en: "I got a job at a company.", form: "회사 + 에 (target particle); 취업하다 → 취업했어요 (past, polite casual)" } },
    "면접": { korean: "면접", note: "A job interview. You 'see' one, like an exam: 면접을 보다, not 면접을 하다 from the candidate's side.", example: { ko: "내일 면접을 봐요.", en: "I have an interview tomorrow.", form: "면접 + 을 (object particle); 보다 → 봐요 (present covering a near-future plan; polite casual — interviews take 보다)" } },
    "소비": { korean: "소비", note: "Consumption — spending as an economic activity. The verb is 소비하다, a consumer is 소비자, and its opposite here is 저축.", example: { ko: "소비가 증가했어요.", en: "Consumption increased.", form: "소비 + 가 (subject particle); 증가하다 → 증가했어요 (past, polite casual)" } },
    "저축": { korean: "저축", note: "Saving money. The verb is 저축하다 and the collocation is 돈을 저축하다. 절약 is economising by not spending.", example: { ko: "매달 돈을 저축해요.", en: "I save money every month.", form: "매달 used adverbially; 돈 + 을 (object particle); 저축하다 → 저축해요 (present, polite casual)" } },
    "비용": { korean: "비용", note: "Cost or expenses — what something takes to do. 가격 is the price on the tag, 요금 a fee for a service, 비용 the total outlay.", example: { ko: "비용이 많이 들어요.", en: "It costs a lot.", form: "비용 + 이 (subject particle); 많이 modifies the verb; 들다 → 들어요 (present, polite casual — costs 'enter' in Korean)" } },
    "걱정": { korean: "걱정", note: "Worry. The verb is 걱정하다, and reassuring someone is 걱정하지 마세요. What you worry about takes 을/를 or 에 대해.", example: { ko: "걱정하지 마세요.", en: "Please don't worry.", form: "걱정하다 + -지 말다 + -세요 → 걱정하지 마세요 (prohibition; polite request)" } },
    "고민": { korean: "고민", note: "A concern you are mulling over — a personal dilemma rather than a fear. 고민이 있어요 means 'something is on my mind'; 걱정 is worry about an outcome.", example: { ko: "고민이 있어요.", en: "Something is troubling me.", form: "고민 + 이 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "만족": { korean: "만족", note: "Satisfaction. The adjective is 만족하다 and what satisfies you takes 에: 결과에 만족해요. Its opposite is 불만.", example: { ko: "결과에 만족해요.", en: "I am satisfied with the result.", form: "결과 + 에 (target particle); 만족하다 → 만족해요 (present, polite casual)" } },
    "불만": { korean: "불만", note: "Dissatisfaction or a complaint — 불 (not) + 만족. 불만이 있다 is 'to have a complaint', and voicing one is 불만을 말하다.", example: { ko: "불만이 있어요.", en: "I have a complaint.", form: "불만 + 이 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "스트레스": { korean: "스트레스", note: "Stress. You 'receive' it: 스트레스를 받다, never 가지다. Relieving it is 스트레스를 풀다.", example: { ko: "스트레스를 받아요.", en: "I feel stressed.", form: "스트레스 + 를 (object particle); 받다 → 받아요 (present, polite casual — stress is 'received' in Korean)" } },
    "자신감": { korean: "자신감", note: "Self-confidence — 자신 (oneself) + 감 (feeling). The 감 suffix builds feeling-nouns: 책임감, 만족감, 부담감.", example: { ko: "자신감이 생겼어요.", en: "I gained confidence.", form: "자신감 + 이 (subject particle); 생기다 → 생겼어요 (past, polite casual)" } },
    "성격": { korean: "성격", note: "Personality or temperament. 성격이 좋다 means someone is easy to get along with. 성질 is a much harsher word for temper.", example: { ko: "성격이 좋아요.", en: "He/she has a good personality.", form: "성격 + 이 (subject particle); 좋다 → 좋아요 (present, polite casual)" } },
    "태도": { korean: "태도", note: "Attitude — how someone conducts themselves. 태도가 좋다 / 나쁘다, and the thing the attitude is towards takes 에 대한.", example: { ko: "태도가 아주 좋아요.", en: "His/her attitude is very good.", form: "태도 + 가 (subject particle); 좋다 → 좋아요 (present, polite casual)" } },
    "노력": { korean: "노력", note: "Effort. The verb 노력하다 pairs with -려고: 잘하려고 노력해요. 'To make an effort' is 노력을 하다.", example: { ko: "열심히 노력해요.", en: "I make a real effort.", form: "열심히 modifies the verb; 노력하다 → 노력해요 (present, polite casual)" } },
    "책임감": { korean: "책임감", note: "A sense of responsibility — the personal quality, where 책임 is the duty itself. 책임감이 강하다 describes a reliable person.", example: { ko: "책임감이 강해요.", en: "He/she has a strong sense of responsibility.", form: "책임감 + 이 (subject particle); 강하다 → 강해요 (present, polite casual)" } },
    "식습관": { korean: "식습관", note: "Eating habits — 식 (food) + 습관. Improving them is 식습관을 개선하다, a standard TOPIK health collocation.", example: { ko: "식습관을 개선해요.", en: "I improve my eating habits.", form: "식습관 + 을 (object particle); 개선하다 → 개선해요 (present, polite casual)" } },
    "영양": { korean: "영양", note: "Nutrition. Compounds: 영양소 (nutrient), 영양가 (nutritional value). 'Nutritious' is 영양이 풍부하다.", example: { ko: "영양이 부족해요.", en: "The nutrition is insufficient.", form: "영양 + 이 (subject particle); 부족하다 → 부족해요 (present, polite casual)" } },
    "질병": { korean: "질병", note: "A disease — the formal medical term. 병 is the everyday word and 감기 a specific ailment. Preventing one is 질병을 예방하다.", example: { ko: "질병을 예방해요.", en: "I prevent disease.", form: "질병 + 을 (object particle); 예방하다 → 예방해요 (present, polite casual)" } },
    "치료": { korean: "치료", note: "Medical treatment. 치료하다 is what the doctor does; the patient 치료를 받다. 'To cure' as a result is 낫다.", example: { ko: "병원에서 치료를 받아요.", en: "I receive treatment at the hospital.", form: "병원 + 에서 (where the action happens); 치료 + 를 (object particle); 받다 → 받아요 (present, polite casual)" } },
    "예방": { korean: "예방", note: "Prevention — stopping something before it starts. 예방하다 takes 을/를: 사고를 예방해요. A vaccination is 예방 주사.", example: { ko: "감기를 예방해요.", en: "I prevent colds.", form: "감기 + 를 (object particle); 예방하다 → 예방해요 (present, polite casual)" } },
    "수면": { korean: "수면", note: "Sleep — the clinical noun used in health writing (수면 부족, 수면 시간). Everyday sleep is 잠, and the verb is 자다.", example: { ko: "수면이 부족해요.", en: "I'm short on sleep.", form: "수면 + 이 (subject particle); 부족하다 → 부족해요 (present, polite casual)" } },
    "피로": { korean: "피로", note: "Fatigue as a noun — 피로가 쌓이다 (fatigue builds up), 피로를 풀다 (to relieve it). The adjective 피곤하다 is what you say about yourself.", example: { ko: "피로가 쌓였어요.", en: "Fatigue has built up.", form: "피로 + 가 (subject particle); 쌓이다 → 쌓였어요 (past, polite casual)" } },
    "체력": { korean: "체력", note: "Physical stamina. 체력이 좋다 / 약하다, and building it is 체력을 기르다. 힘 is momentary strength, 체력 the reserve of it.", example: { ko: "체력을 길러요.", en: "I build up my stamina.", form: "체력 + 을 (object particle); 기르다 → 길러요 (르-irregular; present, polite casual)" } },
    "자연": { korean: "자연", note: "Nature. 자연스럽다 means 'natural' in the sense of unforced, while 자연적이다 refers to the natural world. 자연환경 is the natural environment.", example: { ko: "자연이 아름다워요.", en: "Nature is beautiful.", form: "자연 + 이 (subject particle); 아름답다 → 아름다워요 (ㅂ-irregular; present, polite casual)" } },
    "오염": { korean: "오염", note: "Pollution. 오염되다 is 'to become polluted' (intransitive) and 오염시키다 is 'to pollute'. Compounds: 환경 오염, 대기 오염, 수질 오염.", example: { ko: "공기가 오염됐어요.", en: "The air has become polluted.", form: "공기 + 가 (subject particle); 오염되다 → 오염됐어요 (passive/inchoative; past, polite casual)" } },
    "재활용": { korean: "재활용", note: "Recycling — 재 (again) + 활용 (utilisation). The verb is 재활용하다, and the bin is 재활용 쓰레기통.", example: { ko: "종이를 재활용해요.", en: "I recycle paper.", form: "종이 + 를 (object particle); 재활용하다 → 재활용해요 (present, polite casual)" } },
    "자원": { korean: "자원", note: "Resources — natural or human: 천연자원, 인적 자원. Note the homograph 자원하다 meaning to volunteer.", example: { ko: "자원을 아껴야 해요.", en: "We must conserve resources.", form: "자원 + 을 (object particle); 아끼다 + -어야 하다 → 아껴야 해요 (obligation; present, polite casual)" } },
    "에너지": { korean: "에너지", note: "Energy — both the physical kind (에너지 절약) and personal vigour (에너지가 넘치다).", example: { ko: "에너지를 절약해요.", en: "I save energy.", form: "에너지 + 를 (object particle); 절약하다 → 절약해요 (present, polite casual)" } },
    "기후": { korean: "기후", note: "Climate — the long-term pattern, as against 날씨, today's weather. 기후 변화 is climate change, a standard TOPIK II topic.", example: { ko: "기후가 변하고 있어요.", en: "The climate is changing.", form: "기후 + 가 (subject particle); 변하다 + -고 있다 → 변하고 있어요 (progressive; present, polite casual)" } },
    "지구": { korean: "지구", note: "The Earth. 지구 온난화 is global warming and 지구촌 the global village. The homograph 지구 also means a district.", example: { ko: "지구를 보호해요.", en: "We protect the Earth.", form: "지구 + 를 (object particle); 보호하다 → 보호해요 (present, polite casual)" } },
    "보호": { korean: "보호", note: "Protection. 보호하다 takes 을/를: 환경을 보호해요. 환경 보호 as a noun compound is one of the most-tested TOPIK phrases.", example: { ko: "환경을 보호해야 해요.", en: "We must protect the environment.", form: "환경 + 을 (object particle); 보호하다 + -아야 하다 → 보호해야 해요 (obligation; present, polite casual)" } },
    "개선하다": { korean: "개선하다", note: "To improve something — transitive, so what you improve takes 을/를: 제도를 개선해요. When something improves by itself, use 개선되다 or 나아지다.", example: { ko: "제도를 개선했어요.", en: "They improved the system.", form: "제도 + 를 (object particle — 개선하다 is transitive); 개선하다 → 개선했어요 (past, polite casual)" } },
    "해결하다": { korean: "해결하다", note: "To solve. The problem takes 을/를: 문제를 해결해요. When a problem resolves itself, use 해결되다.", example: { ko: "문제를 해결했어요.", en: "I solved the problem.", form: "문제 + 를 (object particle); 해결하다 → 해결했어요 (past, polite casual)" } },
    "예방하다": { korean: "예방하다", note: "To prevent. What you prevent takes 을/를: 사고를 예방해요. It always means acting before the fact, never fixing after it.", example: { ko: "사고를 예방해요.", en: "I prevent accidents.", form: "사고 + 를 (object particle); 예방하다 → 예방해요 (present, polite casual)" } },
    "비교하다": { korean: "비교하다", note: "To compare. The two things joined take 와/과: 한국과 일본을 비교해요, or ~을/를 ~와 비교하다. 'Compared to' is ~에 비해.", example: { ko: "두 제도를 비교해요.", en: "I compare the two systems.", form: "제도 + 를 (object particle); 비교하다 → 비교해요 (present, polite casual)" } },
    "참여하다": { korean: "참여하다", note: "To participate in an activity. What you join takes 에: 행사에 참여해요. 참석하다 is narrower — physically attending an event.", example: { ko: "행사에 참여했어요.", en: "I participated in the event.", form: "행사 + 에 (event particle — never 을/를); 참여하다 → 참여했어요 (past, polite casual)" } },
    "주장하다": { korean: "주장하다", note: "To claim or assert — putting forward an opinion in an argument. The claim takes -다고: 필요하다고 주장해요. Not the same as 말하다, which is neutral.", example: { ko: "그 사람은 다르게 주장해요.", en: "That person argues differently.", form: "다르다 → 다르게 (adverb form); 주장하다 → 주장해요 (present, polite casual)" } },
    "심각하다": { korean: "심각하다", note: "Serious or grave — for problems, situations, and illnesses, never for a serious-minded person (that is 진지하다). A 하다 adjective: 심각해요.", example: { ko: "문제가 심각해요.", en: "The problem is serious.", form: "문제 + 가 (subject particle); 심각하다 → 심각해요 (present, polite casual)" } },
    "편리하다": { korean: "편리하다", note: "Convenient — for things and systems: 교통이 편리해요. For a person feeling comfortable, use 편하다 instead. Its opposite is 불편하다.", example: { ko: "교통이 편리해요.", en: "The transport is convenient.", form: "교통 + 이 (subject particle); 편리하다 → 편리해요 (present, polite casual)" } },
    "불편하다": { korean: "불편하다", note: "Inconvenient, and also physically uncomfortable — 의자가 불편해요 works for both senses. The 불 prefix negates, as in 불만 and 불가능.", example: { ko: "의자가 불편해요.", en: "The chair is uncomfortable.", form: "의자 + 가 (subject particle); 불편하다 → 불편해요 (present, polite casual)" } },
    "다양하다": { korean: "다양하다", note: "Various, diverse. Before a noun it becomes 다양한: 다양한 문화. Its noun form 다양성 (diversity) is common in TOPIK II reading.", example: { ko: "다양한 문화가 있어요.", en: "There are various cultures.", form: "다양하다 → 다양한 (noun-modifying form); 있다 → 있어요 (present, polite casual)" } },
    "중요하다": { korean: "중요하다", note: "Important. What matters takes 이/가: 건강이 중요해요. Before a noun it is 중요한, and the noun form is 중요성.", example: { ko: "건강이 제일 중요해요.", en: "Health is the most important thing.", form: "건강 + 이 (subject particle); 제일 modifies the predicate; 중요하다 → 중요해요 (present, polite casual)" } },
    "필요하다": { korean: "필요하다", note: "To be necessary. This is an adjective, so what you need takes 이/가, not 을/를: 돈이 필요해요. Saying 돈을 필요해요 is the classic error — for an object particle you need the verb 필요로 하다.", example: { ko: "시간이 필요해요.", en: "I need time.", form: "시간 + 이 (subject particle — 필요하다 takes 이/가, never 을/를); 필요하다 → 필요해요 (present, polite casual)" } },
    "효과적이다": { korean: "효과적이다", note: "Effective. The 적 suffix turns a noun into a quality, and 이다 makes it a predicate: 효과적이에요. Before a noun it becomes 효과적인 방법.", example: { ko: "이 방법이 효과적이에요.", en: "This method is effective.", form: "효과적 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "긍정적이다": { korean: "긍정적이다", note: "Positive — in outlook or evaluation. Same 적 + 이다 construction, giving 긍정적인 태도 before a noun. Its opposite is 부정적이다.", example: { ko: "태도가 긍정적이에요.", en: "The attitude is positive.", form: "태도 + 가 (subject particle); 긍정적 + 이에요 (present, polite casual)" } },
    "부정적이다": { korean: "부정적이다", note: "Negative — the counterpart of 긍정적이다. 부정적인 영향 (a negative influence) is a stock TOPIK II phrase.", example: { ko: "부정적인 영향을 줘요.", en: "It has a negative influence.", form: "부정적이다 → 부정적인 (noun-modifying form); 영향 + 을 (object particle); 주다 → 줘요 (present, polite casual)" } },
    "~에 관심이 있다": { korean: "~에 관심이 있다", note: "'To be interested in ~'. The topic takes 에 and 관심 takes 이 — two particles, and neither is 을/를. The negative is 관심이 없다.", example: { ko: "저는 음악에 관심이 있어요.", en: "I am interested in music.", form: "음악 + 에 (topic of interest); 관심 + 이 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "~에 영향을 주다": { korean: "~에 영향을 주다", note: "'To have an influence on ~'. What is affected takes 에, and 영향 takes 을. The receiving side is ~의 영향을 받다, and the formal variant is 영향을 미치다.", example: { ko: "날씨가 기분에 영향을 줘요.", en: "The weather influences one's mood.", form: "기분 + 에 (what is affected); 영향 + 을 (object particle); 주다 → 줘요 (present, polite casual)" } },
    "~이/가 필요하다": { korean: "~이/가 필요하다", note: "'~ is necessary'. The slot takes 이 after a batchim and 가 after a vowel — never 을/를, because 필요하다 is an adjective describing the thing needed.", example: { ko: "연습이 필요해요.", en: "Practice is necessary.", form: "연습 + 이 (subject particle after a batchim); 필요하다 → 필요해요 (present, polite casual)" } },
    "~을/를 줄이다": { korean: "~을/를 줄이다", note: "'To reduce ~'. 줄이다 is the transitive causative of 줄다 ('to shrink'), so it takes an object with 을/를. Use 줄다 when something shrinks on its own.", example: { ko: "쓰레기를 줄여요.", en: "I reduce waste.", form: "쓰레기 + 를 (object particle after a vowel); 줄이다 → 줄여요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "~을/를 늘리다": { korean: "~을/를 늘리다", note: "'To increase ~'. 늘리다 is transitive, the causative of 늘다. The opposite pair is 줄이다 / 줄다.", example: { ko: "운동 시간을 늘려요.", en: "I increase my exercise time.", form: "시간 + 을 (object particle); 늘리다 → 늘려요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "~을/를 해결하다": { korean: "~을/를 해결하다", note: "'To solve ~'. The problem takes 을/를. When something gets resolved without an agent, switch to 해결되다 with 이/가.", example: { ko: "갈등을 해결해요.", en: "I resolve the conflict.", form: "갈등 + 을 (object particle); 해결하다 → 해결해요 (present, polite casual)" } },
    "~을/를 예방하다": { korean: "~을/를 예방하다", note: "'To prevent ~'. The thing prevented takes 을/를. It always means acting in advance, so it cannot describe fixing something already broken.", example: { ko: "질병을 예방해요.", en: "I prevent disease.", form: "질병 + 을 (object particle); 예방하다 → 예방해요 (present, polite casual)" } },
    "~에 참여하다": { korean: "~에 참여하다", note: "'To participate in ~'. The activity takes 에, never 을/를 — the single most-corrected particle error with this verb.", example: { ko: "봉사 활동에 참여해요.", en: "I take part in volunteer work.", form: "활동 + 에 (activity particle, never 을/를); 참여하다 → 참여해요 (present, polite casual)" } },
    "~을/를 경험하다": { korean: "~을/를 경험하다", note: "'To experience ~'. The thing lived through takes 을/를. The noun collocation 경험을 쌓다 ('build up experience') is separate and just as common.", example: { ko: "새로운 문화를 경험해요.", en: "I experience a new culture.", form: "문화 + 를 (object particle); 경험하다 → 경험해요 (present, polite casual)" } },
    "~을/를 실천하다": { korean: "~을/를 실천하다", note: "'To put ~ into practice'. It takes 을/를 and pairs with plans and resolutions: 계획을 실천해요. 실행하다 is closer to 'execute' for projects.", example: { ko: "계획을 실천해요.", en: "I put the plan into practice.", form: "계획 + 을 (object particle); 실천하다 → 실천해요 (present, polite casual)" } },

    // --------------------------------------------------- TOPIK II level 5
    "원인": { korean: "원인", note: "A cause — the objective source of a result, paired with 결과. 이유 is the reason a person gives, so an accident has an 원인 while a decision has an 이유.", example: { ko: "사고의 원인을 찾았어요.", en: "They found the cause of the accident.", form: "사고 + 의 (possessive particle); 원인 + 을 (object particle); 찾다 → 찾았어요 (past, polite casual)" } },
    "발전": { korean: "발전", note: "Development or advancement. 발전하다 is intransitive (기술이 발전해요) and 발전시키다 is the causative for developing something. The homograph 발전 also means power generation.", example: { ko: "경제 발전이 빨라요.", en: "Economic development is fast.", form: "경제 발전 (noun compound) + 이 (subject particle); 빠르다 → 빨라요 (르-irregular; present, polite casual)" } },
    "정책": { korean: "정책", note: "A policy. It is 'enforced' rather than done: 정책을 시행하다 or 정책을 실시하다. 제도 is the system a policy creates.", example: { ko: "새 정책을 시행해요.", en: "They implement a new policy.", form: "정책 + 을 (object particle); 시행하다 → 시행해요 (present, polite casual)" } },
    "지원하다": { korean: "지원하다", note: "Two verbs in one shape: to apply (대학원에 지원해요 — the target takes 에) and to support or fund (학생을 지원해요 — the beneficiary takes 을/를). The particle tells you which one is meant.", example: { ko: "대학원에 지원했어요.", en: "I applied to graduate school.", form: "대학원 + 에 (target particle, marking the 'apply' sense); 지원하다 → 지원했어요 (past, polite casual)" } },
    "판단하다": { korean: "판단하다", note: "To judge or determine. What you judge takes 을/를, and the basis takes -을 바탕으로 or -에 따라: 정보를 바탕으로 판단해요.", example: { ko: "상황을 판단해요.", en: "I assess the situation.", form: "상황 + 을 (object particle); 판단하다 → 판단해요 (present, polite casual)" } },
    "강조하다": { korean: "강조하다", note: "To emphasise. What you stress takes 을/를: 중요성을 강조해요. In writing it often reports someone's argument: -다고 강조했다.", example: { ko: "중요성을 강조했어요.", en: "They emphasised its importance.", form: "중요성 + 을 (object particle); 강조하다 → 강조했어요 (past, polite casual)" } },
    "영향을 미치다": { korean: "영향을 미치다", note: "'To exert an influence on' — the formal written twin of 영향을 주다. What is affected takes 에: 건강에 영향을 미쳐요.", example: { ko: "환경이 건강에 영향을 미쳐요.", en: "The environment affects health.", form: "건강 + 에 (what is affected); 영향 + 을 (object particle); 미치다 → 미쳐요 (ㅣ + 어 contracts to 여; present, polite casual)" } },
    "원인을 찾다": { korean: "원인을 찾다", note: "'To find the cause'. 원인 takes 을, and the thing whose cause it is takes 의: 사고의 원인을 찾다. 밝히다 ('to bring to light') is the more formal verb.", example: { ko: "문제의 원인을 찾아요.", en: "I look for the cause of the problem.", form: "문제 + 의 (possessive particle); 원인 + 을 (object particle); 찾다 → 찾아요 (present, polite casual)" } },
    "결과가 나타나다": { korean: "결과가 나타나다", note: "'Results appear'. 나타나다 is intransitive, so 결과 takes 이/가 — never 결과를 나타나다. To show a result yourself, use 나타내다.", example: { ko: "좋은 결과가 나타났어요.", en: "Good results appeared.", form: "결과 + 가 (subject particle — 나타나다 is intransitive); 나타나다 → 나타났어요 (past, polite casual)" } },
    "문제를 해결하다": { korean: "문제를 해결하다", note: "'To solve a problem' — the standard collocation. 문제 takes 을/를 with 해결하다, and 이/가 with 해결되다.", example: { ko: "환경 문제를 해결해야 해요.", en: "We must solve the environmental problem.", form: "문제 + 를 (object particle); 해결하다 + -아야 하다 → 해결해야 해요 (obligation; present, polite casual)" } },
    "기술이 발전하다": { korean: "기술이 발전하다", note: "'Technology develops'. 발전하다 is intransitive, so 기술 takes 이/가. To develop technology deliberately, say 기술을 발전시키다.", example: { ko: "기술이 빠르게 발전하고 있어요.", en: "Technology is developing rapidly.", form: "기술 + 이 (subject particle); 발전하다 + -고 있다 → 발전하고 있어요 (progressive; present, polite casual)" } },
    "인구가 감소하다": { korean: "인구가 감소하다", note: "'The population decreases'. 감소하다 is intransitive, so 인구 takes 이/가. Its opposite collocation is 인구가 증가하다.", example: { ko: "인구가 계속 감소해요.", en: "The population keeps decreasing.", form: "인구 + 가 (subject particle); 계속 modifies the verb; 감소하다 → 감소해요 (present, polite casual)" } },
    "사용이 증가하다": { korean: "사용이 증가하다", note: "'Usage increases'. Like 감소하다, 증가하다 is intransitive and takes 이/가. To increase usage deliberately, use 사용을 늘리다.", example: { ko: "스마트폰 사용이 증가했어요.", en: "Smartphone usage has increased.", form: "사용 + 이 (subject particle); 증가하다 → 증가했어요 (past, polite casual)" } },
    "연구를 수행하다": { korean: "연구를 수행하다", note: "'To conduct research' — the academic register. 연구를 하다 says the same thing more plainly, and 수행하다 also carries out duties and projects.", example: { ko: "새로운 연구를 수행해요.", en: "They conduct new research.", form: "연구 + 를 (object particle); 수행하다 → 수행해요 (present, polite casual)" } },
    "경험을 쌓다": { korean: "경험을 쌓다", note: "'To gain experience' — literally 'to stack up experience'. 쌓다 is the fixed verb here, as it is with 지식 and 스트레스; 얻다 sounds wrong.", example: { ko: "많은 경험을 쌓았어요.", en: "I gained a lot of experience.", form: "경험 + 을 (object particle); 쌓다 → 쌓았어요 (past, polite casual)" } },
    "사회 문제": { korean: "사회 문제", note: "A social issue — two nouns with a space, no particle between them. The pattern extends: 환경 문제, 경제 문제, 교육 문제.", example: { ko: "사회 문제가 심각해요.", en: "The social problem is serious.", form: "사회 + 문제 (noun compound) + 가 (subject particle); 심각하다 → 심각해요 (present, polite casual)" } },
    "경제 성장": { korean: "경제 성장", note: "Economic growth. 성장하다 is used for people growing up and for economies expanding; the noun compound is the TOPIK form.", example: { ko: "경제 성장이 느려요.", en: "Economic growth is slow.", form: "경제 성장 (noun compound) + 이 (subject particle); 느리다 → 느려요 (present, polite casual)" } },
    "환경 보호": { korean: "환경 보호", note: "Environmental protection — one of the most frequent TOPIK II noun compounds. As a full clause it becomes 환경을 보호하다.", example: { ko: "환경 보호가 중요해요.", en: "Environmental protection is important.", form: "환경 보호 (noun compound) + 가 (subject particle); 중요하다 → 중요해요 (present, polite casual)" } },
    "문화 차이": { korean: "문화 차이", note: "Cultural difference. 차이 is the gap between two things and takes 와/과 for what is being compared: 한국과 미국의 문화 차이.", example: { ko: "문화 차이가 커요.", en: "The cultural difference is large.", form: "문화 차이 (noun compound) + 가 (subject particle); 크다 → 커요 (ㅡ-irregular; present, polite casual)" } },
    "정책을 시행하다": { korean: "정책을 시행하다", note: "'To implement a policy'. 시행하다 is the formal verb for putting rules into force; 실시하다 is a close synonym.", example: { ko: "정부가 새 정책을 시행했어요.", en: "The government implemented a new policy.", form: "정책 + 을 (object particle); 시행하다 → 시행했어요 (past, polite casual)" } },
    "행사에 참여하다": { korean: "행사에 참여하다", note: "'To take part in an event'. The event takes 에, never 을/를 — the particle to memorise with 참여하다 and 참석하다 alike.", example: { ko: "학교 행사에 참여했어요.", en: "I took part in the school event.", form: "행사 + 에 (event particle, never 을/를); 참여하다 → 참여했어요 (past, polite casual)" } },
    "대학원에 지원하다": { korean: "대학원에 지원하다", note: "'To apply to graduate school'. In the 'apply' sense 지원하다 takes 에; in the 'support' sense it takes 을/를, so the particle disambiguates the verb.", example: { ko: "내년에 대학원에 지원할 거예요.", en: "I will apply to graduate school next year.", form: "대학원 + 에 (target particle); 지원하다 + -(으)ㄹ 거예요 → 지원할 거예요 (future, polite casual)" } },
    "제도를 비교하다": { korean: "제도를 비교하다", note: "'To compare systems'. What is compared takes 을/를 and the point of comparison takes 와/과: 한국 제도와 비교해요.", example: { ko: "두 나라의 제도를 비교해요.", en: "I compare the systems of the two countries.", form: "나라 + 의 (possessive particle); 제도 + 를 (object particle); 비교하다 → 비교해요 (present, polite casual)" } },
    "정보를 바탕으로 판단하다": { korean: "정보를 바탕으로 판단하다", note: "'To judge based on information'. 바탕 is a foundation, and the fixed pattern ~을/를 바탕으로 means 'on the basis of' — the noun takes 을/를 and 바탕 takes 으로.", example: { ko: "정보를 바탕으로 판단해요.", en: "I judge based on the information.", form: "정보 + 를 + 바탕 + 으로 (fixed 'on the basis of' pattern); 판단하다 → 판단해요 (present, polite casual)" } },
    "중요성을 강조하다": { korean: "중요성을 강조하다", note: "'To emphasise the importance'. 중요성 is the noun form of 중요하다, built with the -성 suffix that also gives 가능성 and 필요성.", example: { ko: "교육의 중요성을 강조해요.", en: "They emphasise the importance of education.", form: "교육 + 의 (possessive particle); 중요성 + 을 (object particle); 강조하다 → 강조해요 (present, polite casual)" } },
    "책임을 지다": { korean: "책임을 지다", note: "'To take responsibility' — literally 'to carry responsibility'. 지다 is the fixed verb; 책임을 가지다 and 책임을 하다 are both wrong.", example: { ko: "제가 책임을 지겠습니다.", en: "I will take responsibility.", form: "책임 + 을 (object particle); 지다 + -겠- + -습니다 → 지겠습니다 (speaker's intention; formal polite)" } },
    "가치": { korean: "가치", note: "Value or worth — moral values (가치관) and worthwhileness (가치가 있다). Monetary price is 가격, not 가치.", example: { ko: "이 일은 가치가 있어요.", en: "This work is worthwhile.", form: "가치 + 가 (subject particle); 있다 → 있어요 (present, polite casual)" } },
    "역할": { korean: "역할", note: "A role. You 'do' one: 역할을 하다, or 역할을 맡다 for taking one on. Pronounced [여칼].", example: { ko: "중요한 역할을 해요.", en: "It plays an important role.", form: "중요하다 → 중요한 (noun-modifying form); 역할 + 을 (object particle); 하다 → 해요 (present, polite casual)" } },
    "소통": { korean: "소통", note: "Communication in the sense of mutual understanding — 소통이 잘 되다. 의사소통 is the fuller term, and 통신 is telecommunications.", example: { ko: "소통이 중요해요.", en: "Communication is important.", form: "소통 + 이 (subject particle); 중요하다 → 중요해요 (present, polite casual)" } },
    "산업": { korean: "산업", note: "Industry as an economic sector: 자동차 산업, 관광 산업. 공업 is manufacturing specifically, and 기업 is a company.", example: { ko: "산업이 발전했어요.", en: "The industry developed.", form: "산업 + 이 (subject particle); 발전하다 → 발전했어요 (past, polite casual)" } },
    "생산": { korean: "생산", note: "Production. 생산하다 takes 을/를 and its opposite is 소비. 생산성 is productivity.", example: { ko: "자동차를 생산해요.", en: "They produce cars.", form: "자동차 + 를 (object particle); 생산하다 → 생산해요 (present, polite casual)" } },
    "경쟁": { korean: "경쟁", note: "Competition. 경쟁하다 takes 와/과 for the rival: 다른 회사와 경쟁해요. Do not confuse it with 경제 (economy).", example: { ko: "경쟁이 치열해요.", en: "The competition is fierce.", form: "경쟁 + 이 (subject particle); 치열하다 → 치열해요 (present, polite casual)" } },
    "실험": { korean: "실험", note: "An experiment. 실험하다 is to conduct one, and the collocation is 실험을 하다. 경험 (experience) differs by one syllable.", example: { ko: "실험을 했어요.", en: "We conducted an experiment.", form: "실험 + 을 (object particle); 하다 → 했어요 (past, polite casual)" } },
    "분석": { korean: "분석", note: "Analysis. 분석하다 takes 을/를: 자료를 분석해요. Common in TOPIK II reading passages about research.", example: { ko: "결과를 분석해요.", en: "I analyse the results.", form: "결과 + 를 (object particle); 분석하다 → 분석해요 (present, polite casual)" } },
    "자료": { korean: "자료", note: "Data or source materials — documents, figures, references. 정보 is information as content, 자료 the material it comes in.", example: { ko: "자료를 준비했어요.", en: "I prepared the materials.", form: "자료 + 를 (object particle); 준비하다 → 준비했어요 (past, polite casual)" } },
    "인공지능": { korean: "인공지능", note: "Artificial intelligence — 인공 (artificial) + 지능 (intelligence). Usually abbreviated AI in writing, and a frequent TOPIK II reading topic.", example: { ko: "인공지능이 발전하고 있어요.", en: "Artificial intelligence is developing.", form: "인공지능 + 이 (subject particle); 발전하다 + -고 있다 → 발전하고 있어요 (progressive; present, polite casual)" } },
    "학습": { korean: "학습", note: "Learning — the formal, systematic word used in educational writing. 공부 is what a student does day to day.", example: { ko: "학습 방법을 바꿨어요.", en: "I changed my learning method.", form: "학습 방법 (noun compound) + 을 (object particle); 바꾸다 → 바꿨어요 (past, polite casual)" } },
    "교수": { korean: "교수", note: "A professor. Addressed with the honorific 교수님, never bare 교수 — the same rule as 선생님 and 사장님.", example: { ko: "교수님께 질문했어요.", en: "I asked the professor a question.", form: "교수 + 님 (honorific suffix) + 께 (honorific recipient particle); 질문하다 → 질문했어요 (past, polite casual)" } },
    "토론": { korean: "토론", note: "A debate or structured discussion. 토론하다 takes 에 대해 for the topic: 환경에 대해 토론해요. A casual chat is 대화.", example: { ko: "환경에 대해 토론해요.", en: "We debate about the environment.", form: "환경 + 에 대해 (fixed 'about' pattern); 토론하다 → 토론해요 (present, polite casual)" } },
    "법률": { korean: "법률", note: "Law as a body of legislation — the formal term. 법 is the everyday word, and 규칙 is a rule.", example: { ko: "법률을 지켜야 해요.", en: "We must obey the law.", form: "법률 + 을 (object particle); 지키다 + -어야 하다 → 지켜야 해요 (obligation; present, polite casual)" } },
    "제도": { korean: "제도", note: "A system or institution — an established arrangement: 교육 제도, 복지 제도. 시스템 is the loanword for technical systems.", example: { ko: "교육 제도를 개선해요.", en: "They improve the education system.", form: "제도 + 를 (object particle); 개선하다 → 개선해요 (present, polite casual)" } },
    "공공": { korean: "공공", note: "Public, as a prefix on institutions and services: 공공 기관, 공공장소, 공공 정책. It does not stand alone as a predicate.", example: { ko: "공공장소에서 조용히 해요.", en: "Be quiet in public places.", form: "공공장소 + 에서 (where the action happens); 조용히 modifies the verb; 하다 → 해요 (present, polite casual)" } },
    "복지": { korean: "복지", note: "Welfare — social provision: 복지 제도, 사회 복지, 복지 정책. Not the same as 행복 (happiness).", example: { ko: "복지 제도가 좋아요.", en: "The welfare system is good.", form: "복지 제도 (noun compound) + 가 (subject particle); 좋다 → 좋아요 (present, polite casual)" } },
    "의료": { korean: "의료", note: "Medical care as a field: 의료 서비스, 의료비, 의료 기관. 치료 is the treatment given to one patient.", example: { ko: "의료 서비스가 좋아요.", en: "The medical service is good.", form: "의료 서비스 (noun compound) + 가 (subject particle); 좋다 → 좋아요 (present, polite casual)" } },
    "과정": { korean: "과정", note: "A process, and also a course of study (석사 과정). 결과 is the outcome, 과정 the path to it — the pair appears constantly in TOPIK II writing.", example: { ko: "과정이 중요해요.", en: "The process is important.", form: "과정 + 이 (subject particle); 중요하다 → 중요해요 (present, polite casual)" } },
    "특징": { korean: "특징", note: "A characteristic or distinguishing feature. 특징이 있다 is 'to have a feature'; 특성 is a property in a more technical sense.", example: { ko: "이 제도의 특징을 설명해요.", en: "I explain the features of this system.", form: "제도 + 의 (possessive particle); 특징 + 을 (object particle); 설명하다 → 설명해요 (present, polite casual)" } },
    "변화하다": { korean: "변화하다", note: "To change — intransitive, with 이/가: 사회가 변화해요. 바꾸다 is changing something, 바뀌다 is something being changed, and 변하다 is a plainer synonym.", example: { ko: "사회가 빠르게 변화해요.", en: "Society changes rapidly.", form: "사회 + 가 (subject particle — 변화하다 is intransitive); 변화하다 → 변화해요 (present, polite casual)" } },
    "연구하다": { korean: "연구하다", note: "To research. The subject takes 을/를: 역사를 연구해요. In academic writing 연구를 수행하다 is the fuller collocation.", example: { ko: "역사를 연구해요.", en: "I research history.", form: "역사 + 를 (object particle); 연구하다 → 연구해요 (present, polite casual)" } },
    "조사하다": { korean: "조사하다", note: "To investigate or survey. What you look into takes 을/를: 원인을 조사해요. A questionnaire survey is 설문 조사.", example: { ko: "원인을 조사했어요.", en: "They investigated the cause.", form: "원인 + 을 (object particle); 조사하다 → 조사했어요 (past, polite casual)" } },
    "분석하다": { korean: "분석하다", note: "To analyse. The data takes 을/를: 자료를 분석해요. It implies breaking something down, unlike 조사하다, which is gathering.", example: { ko: "자료를 분석해요.", en: "I analyse the data.", form: "자료 + 를 (object particle); 분석하다 → 분석해요 (present, polite casual)" } },
    "협력하다": { korean: "협력하다", note: "To cooperate. The partner takes 와/과: 다른 나라와 협력해요. 협동 is teamwork within a group.", example: { ko: "두 나라가 협력해요.", en: "The two countries cooperate.", form: "나라 + 가 (subject particle); 협력하다 → 협력해요 (present, polite casual)" } },
    "인정하다": { korean: "인정하다", note: "To acknowledge or admit — a fact, a mistake, or someone's ability. It takes 을/를: 실수를 인정해요. The passive 인정받다 means 'to be recognised'.", example: { ko: "실수를 인정했어요.", en: "I admitted my mistake.", form: "실수 + 를 (object particle); 인정하다 → 인정했어요 (past, polite casual)" } },
    "유지하다": { korean: "유지하다", note: "To maintain or keep something as it is: 건강을 유지해요, 관계를 유지해요. What is maintained takes 을/를.", example: { ko: "건강을 유지해요.", en: "I maintain my health.", form: "건강 + 을 (object particle); 유지하다 → 유지해요 (present, polite casual)" } },
    "향상시키다": { korean: "향상시키다", note: "To improve something — the causative of 향상되다. Use 향상시키다 with an object (실력을 향상시켜요) and 향상되다 when the thing improves on its own (실력이 향상돼요).", example: { ko: "실력을 향상시켜요.", en: "I improve my skills.", form: "실력 + 을 (object particle); 향상시키다 → 향상시켜요 (causative; ㅣ + 어 contracts to 여; present, polite casual)" } },
  };

  // Part-of-speech buckets for the vocabulary bank: the standard English
  // categories, adjusted for Korean. Descriptive verbs ("adjectives"),
  // counters, dependent nouns, particles, and 관형사 determiners have no clean
  // English equivalent, so each keeps its own group.
  const POS_GROUPS = Object.freeze([
    { id: "noun", label: "Nouns", korean: "명사", parts: ["noun", "proper noun", "noun phrase"], note: "Names of things, people, and places. Korean nouns have no articles and no plural ending; particles do the grammatical work." },
    { id: "pronoun", label: "Pronouns", korean: "대명사", parts: ["pronoun", "determiner/pronoun", "adverb/pronoun"], note: "Stand-ins for nouns. Politeness matters here: 저 is humble, 나 is casual." },
    { id: "verb", label: "Action verbs", korean: "동사", parts: ["verb"], note: "Words for actions. The dictionary form ends in -다 and is never used as-is in a sentence." },
    { id: "adjective", label: "Descriptive verbs (adjectives)", korean: "형용사", parts: ["adjective", "noun/adjective"], note: "Korean adjectives are a kind of verb: they conjugate (좋다 → 좋아요) and end a sentence on their own, with no copula." },
    { id: "adverb", label: "Adverbs", korean: "부사", parts: ["adverb", "noun/adverb"], note: "Modify verbs, adjectives, or whole sentences, and normally sit right before what they modify." },
    { id: "determiner", label: "Determiners (before a noun)", korean: "관형사", parts: ["determiner"], note: "Sit directly in front of a noun and never take a particle or an ending: 무슨 색, 이 책." },
    { id: "numeral", label: "Numbers", korean: "수사", parts: ["numeral", "noun/numeral"], note: "Korean runs two number systems — native Korean and Sino-Korean — and the counter decides which one you use." },
    { id: "counter", label: "Counters (measure words)", korean: "단위 명사", parts: ["counter", "counter phrase"], note: "Bound units that follow a number when counting: 사람 세 명, 책 두 권. English has no obligatory equivalent." },
    { id: "dependent-noun", label: "Dependent nouns", korean: "의존 명사", parts: ["dependent noun"], note: "Nouns that cannot stand alone and always need a modifier in front: 것, 수, 때." },
    { id: "particle", label: "Particles", korean: "조사", parts: ["particle"], note: "Attached to the end of a noun to mark its role — subject, object, topic, place, time." },
    { id: "conjunction", label: "Conjunctions", korean: "접속사", parts: ["conjunction"], note: "Join clauses or sentences: 그리고, 그런데, 하지만." },
    { id: "interjection", label: "Interjections", korean: "감탄사", parts: ["interjection"], note: "Standalone reaction words. They never conjugate and never take particles." },
    { id: "expression", label: "Set expressions", korean: "관용 표현", parts: ["expression"], note: "Fixed phrases learned whole rather than built from parts, including patterns with a particle slot." },
    { id: "phrase", label: "Collocations", korean: "연어", parts: ["phrase"], note: "Word pairings that are fixed in Korean: 춤을 추다, 경험을 쌓다. The noun decides which verb goes with it, so learn the pair together." }
  ]);

  // Part of speech by Korean headword, for pages that carry their own word
  // lists and do not load shared-vocab.js (the TOPIK vocabulary references).
  // Values are space-separated headwords; taken from shared-vocab, with the
  // particle-slot patterns added by hand.
  const POS_WORDS = Object.freeze({
    "pronoun": "언제 누구 무엇 무엇/뭐 어디",
    "adverb": "왜 어떻게 항상 자주 가끔 다시 같이 빨리 천천히 잘 많이 조금",
    "determiner": "어느 몇",
    "noun": "보통 밥 물 커피 차 우유 빵 과일 사과 바나나 고기 생선 김치 라면 떡 가게 가격 돈 카드 현금 얼마 빨간색 파란색 노란색 초록색 검은색 흰색 날씨 비 눈 바람 집 학교 회사 병원 은행 우체국 식당 카페 공원 시장 백화점 도서관 약국 공항 호텔 버스 지하철 택시 기차 비행기 자동차 자전거 오늘 내일 어제 아침 점심 저녁 밤 오전 오후 시간 월요일 화요일 수요일 목요일 금요일 토요일 일요일 열 일 아버지 어머니 부모님 형 오빠 누나 언니 남동생 여동생 할아버지 할머니 아들 딸 이름 성 나이 생일 국적 사람 학생 선생님 회사원 의사 간호사 경찰 가족 친구 남자 여자 경험 문화 사회 경제 환경 건강 습관 계획 준비 목적 기회 방법 결과 이유 문제 해결 관계 책임 약속 실수 수업 과제 시험 성적 발표 연구 졸업 장학금 직원 회의 업무 월급 출근 퇴근 생활 이사 여행 교통 계절 음식 취미 변화 전통 관심 영향 교육 지식 전공 강의 실력 직업 취업 면접 소비 저축 비용 걱정 고민 만족 불만 스트레스 자신감 성격 태도 노력 책임감 운동 식습관 영양 질병 치료 예방 수면 피로 체력 자연 오염 쓰레기 재활용 자원 에너지 기후 지구 보호 원인 발전 정책 가치 역할 소통 산업 생산 경쟁 실험 분석 자료 인공지능 학습 교수 토론 법률 제도 공공 복지 의료 과정 특징",
    "verb": "가다 오다 먹다 마시다 보다 듣다 읽다 쓰다 말하다 공부하다 일하다 자다 일어나다 앉다 서다 만나다 배우다 만들다 좋아하다 싫어하다 신청하다 이용하다 참석하다 선택하다 결정하다 설명하다 증가하다 감소하다 발전하다 성공하다 개선하다 해결하다 예방하다 비교하다 참여하다 주장하다 지원하다 판단하다 강조하다 변화하다 연구하다 조사하다 분석하다 협력하다 인정하다 유지하다 향상시키다",
    "adjective": "좋다 나쁘다 크다 작다 많다 적다 빠르다 느리다 쉽다 어렵다 예쁘다 맛있다 재미있다 싸다 비싸다 덥다 춥다 맑다 흐리다 심각하다 복잡하다 편리하다 불편하다 다양하다 중요하다 필요하다 효과적이다 긍정적이다 부정적이다",
    "noun/adverb": "지금",
    "dependent noun": "시 분",
    "numeral": "하나 둘 셋 넷 다섯 여섯 일곱 여덟 아홉 이 삼 사 오 육 칠 구 십",
    "noun/numeral": "팔",
    "interjection": "네 아니요",
    "expression": "안녕하세요 감사합니다 고맙습니다 죄송합니다 미안합니다 괜찮아요 맞아요 아니에요 반갑습니다"
  });

  // Headwords that contain spaces, so they cannot live in the space-separated
  // table above.
  const POS_MULTIWORD = Object.freeze({
    "안녕히 가세요": "expression", "안녕히 계세요": "expression", "처음 뵙겠습니다": "expression",
    "~에 관심이 있다": "expression", "~에 영향을 주다": "expression", "~에 참여하다": "expression",
    "~이/가 필요하다": "expression", "~을/를 줄이다": "expression", "~을/를 늘리다": "expression",
    "~을/를 해결하다": "expression", "~을/를 예방하다": "expression", "~을/를 경험하다": "expression",
    "~을/를 실천하다": "expression",
    "사회 문제": "noun phrase", "경제 성장": "noun phrase", "환경 보호": "noun phrase", "문화 차이": "noun phrase",
    "영향을 미치다": "phrase", "원인을 찾다": "phrase", "결과가 나타나다": "phrase",
    "문제를 해결하다": "phrase", "기술이 발전하다": "phrase", "인구가 감소하다": "phrase",
    "사용이 증가하다": "phrase", "연구를 수행하다": "phrase", "경험을 쌓다": "phrase",
    "정책을 시행하다": "phrase", "행사에 참여하다": "phrase", "대학원에 지원하다": "phrase",
    "제도를 비교하다": "phrase", "정보를 바탕으로 판단하다": "phrase", "중요성을 강조하다": "phrase",
    "책임을 지다": "phrase"
  });

  const PART_TO_GROUP = new Map();
  POS_GROUPS.forEach(group => group.parts.forEach(part => PART_TO_GROUP.set(part, group.id)));
  const GROUP_BY_ID = new Map(POS_GROUPS.map(group => [group.id, group]));
  const GROUP_ORDER = POS_GROUPS.map(group => group.id);

  const BY_KOREAN = new Map();
  Object.values(NOTES).forEach(note => { if (note.korean && !BY_KOREAN.has(note.korean)) BY_KOREAN.set(note.korean, note); });

  function get(entry) {
    if (!entry) return null;
    return NOTES[entry.id] || BY_KOREAN.get(entry.korean) || null;
  }
  function has(entry) { return Boolean(get(entry)); }
  // An unlisted part of speech falls back to a bucket of its own so that no
  // word can be dropped from the bank.
  function groupIdFor(entry) { return PART_TO_GROUP.get(entry?.partOfSpeech) || entry?.partOfSpeech || "other"; }
  function groupFor(entry) {
    const id = groupIdFor(entry);
    return GROUP_BY_ID.get(id) || { id, label: id.replaceAll("-", " "), korean: "", parts: [id], note: "" };
  }
  function groupRank(id) {
    const index = GROUP_ORDER.indexOf(id);
    return index === -1 ? GROUP_ORDER.length : index;
  }

  const POS_BY_KOREAN = new Map(Object.entries(POS_MULTIWORD));
  Object.entries(POS_WORDS).forEach(([pos, words]) =>
    words.split(" ").filter(Boolean).forEach(word => { if (!POS_BY_KOREAN.has(word)) POS_BY_KOREAN.set(word, pos); }));

  // A page's own word list may write a headword with alternatives ("무엇/뭐"),
  // so fall back to the part before the slash — but only when the whole string
  // is unknown, since the particle-slot patterns ("~이/가 필요하다") contain a
  // slash of their own.
  function resolve(korean, table) {
    if (korean == null) return undefined;
    const whole = table.get ? table.get(korean) : table[korean];
    if (whole !== undefined) return whole;
    const head = String(korean).split("/")[0].trim();
    return table.get ? table.get(head) : table[head];
  }
  // Literal jamo transcription for the example sentences, so a page can show
  // them romanized without pulling in shared-vocab.js. Same rules as
  // KoreanVocab.romanize: syllables joined with dashes, a two-value consonant
  // taking the first form in the onset and the second in the coda, and no
  // liaison, tensing, or assimilation. Non-Hangul characters pass through.
  const CHO = ["g", "gg", "n", "d", "dd", "r", "m", "b", "bb", "s", "ss", "", "j", "jj", "ch", "k", "t", "p", "h"];
  const JUNG = ["a", "ae", "ya", "yae", "eo", "e", "yeo", "ye", "o", "oa", "oae", "oi", "yo", "u", "ueo", "ue", "ui", "yu", "eu", "eui", "i"];
  const JONG = ["", "k", "kk", "ks", "n", "nj", "nh", "t", "l", "lk", "lm", "lp", "ls", "lt", "lp", "lh", "m", "p", "ps", "s", "ss", "ng", "j", "ch", "k", "t", "p", "h"];
  function romanize(text) {
    return String(text == null ? "" : text).split(" ").map(word => {
      const parts = [];
      let syllables = [];
      for (let i = 0; i < word.length; i++) {
        const code = word.charCodeAt(i);
        if (code >= 0xAC00 && code <= 0xD7A3) {
          const offset = code - 0xAC00;
          syllables.push(CHO[Math.floor(offset / (28 * 21))] + JUNG[Math.floor(offset / 28) % 21] + JONG[offset % 28]);
        } else {
          if (syllables.length) { parts.push(syllables.join("-")); syllables = []; }
          parts.push(word[i]);
        }
      }
      if (syllables.length) parts.push(syllables.join("-"));
      return parts.join("");
    }).join(" ");
  }

  function posForKorean(korean) { return resolve(korean, POS_BY_KOREAN) || ""; }
  function noteForKorean(korean) { return resolve(korean, BY_KOREAN) || null; }
  function groupForKorean(korean) { return groupFor({ partOfSpeech: posForKorean(korean), korean }); }

  return {
    NOTES, POS_GROUPS, get, has, groupIdFor, groupFor, groupRank,
    posForKorean, noteForKorean, groupForKorean, romanize
  };
});
